INSERT INTO public.recipes (id, name, source_cuisine, cuisine, diet, is_jain, dish_type, serves, prep_time, cook_time, blurb, tip, badge, tags, ingredients, method, meal_hint, serving_unit, serving_weight_g, kcal, protein_g, carbs_g, fat_g, fibre_g, iron_mg, calcium_mg, vit_b12_mcg, sodium_mg, nutrition_estimated) VALUES
  (369, 'Enduri Pitha', 'Odia', 'east_indian', 'vegan', true, 'main', NULL, '20 min (plus soak)', '20 min', 'Enduri Pitha is Odisha''s most aromatic pitha — steamed inside turmeric leaves, which impart a distinctive earthy-golden fragrance to the sweet coconut-jaggery filling. Made during Prathamashtami (the festival honouring the eldest child), it is one of Odisha''s most culturally specific dishes.', 'If turmeric leaves are unavailable, banana leaves work — but the characteristic turmeric flavour is lost.', 'Traditional', NULL, ARRAY['Rice — 1 cup, soaked','Urad dal — ¼ cup, soaked','Grated fresh coconut — ¼ cup','Jaggery — 3 tbsp','Cardamom powder — ½ tsp','Turmeric leaves — 4-5 (for steaming)','Salt — a pinch']::text[], ARRAY['Soak rice and urad dal separately; blend each separately then combine.','Mix in grated coconut, jaggery and cardamom to the batter.','Wash turmeric leaves; place a spoonful of batter on each leaf and fold to enclose.','Arrange in a steamer; steam 15–18 minutes until the batter is set.','Unwrap and eat straight from the leaf — the turmeric imparts a subtle earthiness.']::text[], ARRAY['breakfast']::text[], 'piece', 120, 210, 6, 36, 5, 2, 1.2, 30, 0, 100, true),
  (370, 'Makki di Roti', 'Punjabi', 'north_indian', 'veg', true, 'staple', NULL, '15 min', '25 min', 'Makki di Roti is Punjab''s winter icon — the thick, slightly grainy maize flatbread that is inseparable from sarson ka saag (mustard greens). Eaten from November through February when mustard fields bloom across the Punjab plains, it is a seasonal ritual as much as a meal.', 'Maize dough cracks easily — keep a bowl of water nearby and patch cracks as you pat.', 'Traditional', NULL, ARRAY['Maize flour (makki atta) — 1 cup','Fenugreek leaves (methi) — ¼ cup, chopped','Green chilli — 2, finely chopped','Ginger — ½ inch, grated','Ghee — 1 tsp (for serving)','Salt to taste']::text[], ARRAY['Knead makki atta with methi leaves, green chilli, ginger and salt using warm water — it will be stiffer than wheat dough.','Divide into balls; pat each ball between wet palms into a thick round (it cracks easily — this is normal; patch the cracks).','Cook on a dry tawa on medium heat until both sides have golden spots and the roti is cooked through.','Spread generously with ghee; serve hot with sarson ka saag, jaggery and raw onion.']::text[], ARRAY['breakfast']::text[], 'piece', 100, 240, 5, 38, 8, 4, 1.8, 25, 0.02, 250, true),
  (371, 'Dal Baati Churma', 'Rajasthani', 'north_indian', 'veg', true, 'main', NULL, '30 min', '60 min', 'Dal Baati Churma is Rajasthan''s ceremonial meal — hard wheat dumplings (baati) baked in desert sand or a wood fire, served with five-lentil dal and sweet churma. Originally the food of Rajput warriors who could bake baati in embers while on the move, it is now Rajasthan''s proudest culinary symbol.', 'Generous ghee is not optional; it is the dish. Dal Baati Churma eaten without ghee is not Dal Baati Churma.', 'Traditional', NULL, ARRAY['Whole wheat flour — 1 cup','Semolina (sooji) — ¼ cup','Ghee — 3 tbsp','Toor dal — ½ cup','Moong dal — ¼ cup','Turmeric — ½ tsp','Red chilli powder — 1 tsp','Ghee — 2 tbsp (for serving)','Jaggery — 2 tbsp','Salt to taste']::text[], ARRAY['Make baati: mix wheat flour, semolina, ghee and salt; add water to form a stiff dough. Shape into round balls. Bake at 200°C for 30 minutes until golden, or roast in an oven directly on the rack.','Make panchmel dal: pressure cook all dals together with turmeric. Temper with ghee, red chilli, cumin seeds and hing.','Make churma: crush two baatis coarsely; add jaggery, ghee and cardamom; mix.','Crack baatis open, pour ghee over each. Serve baati, dal and churma together.']::text[], ARRAY['lunch']::text[], 'plate', 300, 580, 18, 72, 22, 10, 4, 90, 0.1, 600, true),
  (372, 'Gatte ki Sabzi', 'Rajasthani', 'north_indian', 'veg', true, 'curry', NULL, '20 min', '35 min', 'Gatte ki Sabzi is Rajasthan''s most ingenious dish — besan cylinders boiled until firm and then simmered in a spiced curd gravy. In a desert state where fresh vegetables were historically scarce, gatte was a protein-rich alternative that kept for days.', 'Boil gatte in plenty of water; they swell slightly and need room. Crowded gatte stick together.', 'Traditional', NULL, ARRAY['Besan (gram flour) — 1 cup','Curd — ½ cup','Coriander powder — 1 tsp','Turmeric — ½ tsp','Red chilli powder — 1 tsp','Ajwain — ½ tsp','Fennel seeds — ½ tsp','Oil — 2 tsp','Salt to taste']::text[], ARRAY['Mix besan, coriander powder, turmeric, chilli powder, ajwain, fennel and oil into a stiff dough using a little water.','Roll into a thick log; cut into cylinders (gatte).','Boil gatte in salted water 8–10 minutes until firm; remove and slice.','Whisk curd with besan, red chilli and remaining spices; cook in a pan stirring constantly until it thickens to a curry.','Add sliced gatte; simmer 5 minutes. Finish with a mustard tempering.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 320, 12, 38, 14, 5, 2.5, 100, 0.2, 500, true),
  (373, 'Ker Sangri', 'Rajasthani', 'north_indian', 'veg', true, 'side', NULL, '10 min (plus overnight soak)', '20 min', 'Ker Sangri is Rajasthan''s desert pickle-vegetable — two wild desert plants (ker berry and sangri bean) that were foraged and sun-dried for preservation across the Thar Desert. The dried vegetables require soaking and the dish has an intense, concentrated flavour found nowhere else in Indian cuisine.', 'Soak ker and sangri for at least 8 hours; under-soaked ker retains a bitter astringency.', 'Traditional', NULL, ARRAY['Ker (dried berries) — ¼ cup, soaked','Sangri (dried beans) — ½ cup, soaked','Curd — ½ cup','Red chilli powder — 1 tsp','Coriander powder — 1 tsp','Turmeric — ¼ tsp','Amchur (dry mango powder) — ½ tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Drain soaked ker and sangri; pat dry.','Heat oil; add whole red chilli and let it bloom.','Add ker and sangri; fry on medium heat 3 minutes.','Add curd, red chilli powder, coriander powder, turmeric and amchur; cook until oil surfaces and the masala clings to the vegetables.','Adjust salt; serve with bajra roti.']::text[], ARRAY['lunch']::text[], 'bowl', 100, 180, 6, 22, 8, 8, 2, 90, 0.2, 450, true),
  (374, 'Dal Dhokli', 'Gujarati', 'west_indian', 'veg', true, 'main', NULL, '20 min', '40 min', 'Dal Dhokli is Gujarat''s one-pot comfort meal — wheat strips simmered in tangy-sweet toor dal until they absorb its character. The simultaneous sweetness of jaggery, sourness of tamarind and warmth of spices reflects the Gujarati palate''s love of balanced flavour.', 'Add dhokli strips one by one so they do not clump; stir gently every 5 minutes.', 'Traditional', NULL, ARRAY['Toor dal — 1 cup','Whole wheat flour — ½ cup','Turmeric — ½ tsp','Jaggery — 1 tbsp','Tamarind — small ball','Red chilli powder — 1 tsp','Coriander powder — 1 tsp','Ghee — 1 tbsp','Mustard seeds — ½ tsp','Salt to taste']::text[], ARRAY['Boil toor dal with turmeric until completely soft; keep aside.','Make wheat dough with salt and a little oil; rest 15 min. Roll into strips.','In the cooked dal, add tamarind, jaggery, red chilli powder, coriander powder and mustard tempering.','Drop dough strips into simmering dal and cook 15 minutes until dhokli is cooked through.','Finish with ghee and coriander. The dish thickens as it sits.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 380, 14, 58, 10, 7, 3, 60, 0.05, 550, true),
  (375, 'Undhiyu', 'Gujarati', 'west_indian', 'vegan', false, 'side', NULL, '30 min', '45 min', 'Undhiyu is Gujarat''s winter festival dish — a slow-cooked medley of seasonal vegetables and steamed fenugreek dumplings named for the clay pot (undhu = upside down) it was traditionally cooked in underground. Entire Gujarati families gather to cook it for Uttarayan (Makar Sankranti).', 'Do not lift the lid during cooking — the steam builds the dish''s flavour; every lid-lift loses 5 minutes of progress.', 'Traditional', NULL, ARRAY['Raw banana — 1, cubed','Purple yam — ½ cup, cubed','Surti papdi (flat beans) — ½ cup','Sweet potato — ½ cup, cubed','Brinjal — 2 small, slit','Muthia (fenugreek dumplings) — ½ cup','Coconut — ¼ cup, grated','Coriander — 3 tbsp','Green chilli — 3','Oil — 3 tbsp','Salt to taste']::text[], ARRAY['Make muthia: mix besan, wheat flour, methi, ginger-chilli paste and salt; shape into small cylinders and steam 15 min.','Boil all the hard vegetables (yam, raw banana, sweet potato) partially.','Grind coconut, coriander, green chilli and a little oil into a coarse masala.','Layer vegetables and muthia in a heavy pan; spread masala between layers.','Pour oil over the top; cook covered on very low heat 25 minutes without stirring.','Toss gently once done and serve.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 320, 10, 42, 14, 9, 3, 90, 0, 500, true),
  (376, 'Aloo Posto', 'Bengali', 'east_indian', 'vegan', false, 'side', NULL, '10 min', '20 min', 'Aloo Posto is quintessential Bengali soul food — white poppy seeds (posto) ground into a paste that coats potato with a nutty, creamy richness. In Bengal, posto is not just an ingredient but an identity; no monsoon meal is complete without it.', 'Grind posto with a little water to a fine paste — any coarseness makes the dish gritty.', 'Traditional', NULL, ARRAY['Potato — 3 medium, cubed','Poppy seeds (posto) — 3 tbsp','Green chilli — 3, slit','Mustard oil — 2 tbsp','Turmeric — ½ tsp','Salt to taste']::text[], ARRAY['Boil cubed potatoes until just tender; drain.','Heat mustard oil; add slit green chillies and let them sizzle.','Add boiled potatoes and turmeric; stir to coat.','Add poppy seed paste (grind 3 tbsp posto with 2 tbsp water); mix well.','Cook on low 5 minutes until oil separates. Season with salt.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 260, 5, 32, 14, 4, 1.8, 90, 0, 350, true),
  (377, 'Cholar Dal', 'Bengali', 'east_indian', 'veg', true, 'dal', NULL, '10 min (plus soak)', '30 min', 'Cholar Dal is Bengal''s festive dal, served at pujas and weddings — the sweetness of grated coconut against the earthy chana dal, fragrant with whole spices and ghee, makes it unlike any other dal in the subcontinent. It is paired with deep-fried luchi (puri).', 'Do not overcook chana dal; it should hold its shape. Mushy dal loses the dish''s distinct texture.', 'Traditional', NULL, ARRAY['Chana dal — 1 cup','Coconut — 3 tbsp, fresh grated','Ginger — 1 inch, grated','Ghee — 1 tsp','Bay leaf — 1','Cardamom — 2 pods','Clove — 2','Cinnamon — 1 inch','Cumin seeds — ½ tsp','Salt to taste']::text[], ARRAY['Pressure cook chana dal until soft but not mushy (2 whistles).','Heat ghee; add bay leaf, cardamom, clove and cinnamon; let them bloom.','Add ginger; sauté briefly.','Add cooked dal, fresh coconut and salt; simmer 8 minutes.','Garnish with a final drizzle of ghee and serve with luchi or rice.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 280, 14, 38, 8, 6, 3, 60, 0.05, 450, true),
  (378, 'Shorshe Begun', 'Bengali', 'east_indian', 'vegan', true, 'side', NULL, '15 min', '20 min', 'Shorshe Begun is Bengal''s mustardy masterpiece — whole brinjals stuffed with a sharp paste of ground mustard, poppy seeds and green chilli, then cooked in their own steam. The combination of mustard heat and poppy creaminess is a uniquely Bengali flavour profile.', 'Use sharp, freshly ground mustard paste; store-bought paste is often stale and lacks the necessary bite.', 'Traditional', NULL, ARRAY['Brinjal (begun) — 4 long, slit','Mustard paste — 3 tbsp','Poppy seed paste — 1 tbsp','Green chilli paste — 1 tsp','Turmeric — ¼ tsp','Mustard oil — 2 tbsp','Salt to taste']::text[], ARRAY['Slit long brinjals carefully — keep stalks on; mix mustard paste, poppy paste, green chilli paste, turmeric and salt.','Stuff the paste gently into the slits of each brinjal.','Heat mustard oil to smoking; carefully place stuffed brinjals in.','Cover and cook on very low heat 12–15 minutes, turning once, until brinjals are tender.','Serve with steamed rice — the paste is the sauce.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 180, 4, 16, 12, 4, 1.5, 80, 0, 350, true),
  (379, 'Bharli Vangi', 'Maharashtrian', 'west_indian', 'vegan', false, 'side', NULL, '20 min', '30 min', 'Bharli Vangi is Maharashtra''s stuffed brinjal masterpiece — small purple brinjals packed with a nutty, coconut-peanut filling and cooked in their own steam. Goda masala, the sweet-spiced Maharashtrian blend, is what makes this dish unmistakably Marathi.', 'Choose small, firm brinjals of equal size so they cook evenly and hold their shape.', 'Traditional', NULL, ARRAY['Small brinjals (vangi) — 8, slit','Peanuts — ¼ cup, roasted and ground','Sesame seeds — 2 tbsp, roasted','Dried coconut — 3 tbsp, grated','Onion — 1 medium, finely chopped','Coriander powder — 1 tsp','Cumin powder — 1 tsp','Goda masala — 1 tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Mix peanuts, sesame seeds, dried coconut, coriander-cumin powder and goda masala into a dry filling.','Slit brinjals from the bottom, keeping the stem intact; stuff filling into each.','Heat oil in a wide pan; place stuffed brinjals carefully.','Add remaining filling and ½ cup water; cover and cook on low heat 20 minutes, turning once.','Uncover and cook 5 more minutes until oil surfaces and brinjals are fully soft.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 220, 6, 22, 14, 6, 2, 120, 0, 400, true),
  (380, 'Varan Bhaat', 'Maharashtrian', 'west_indian', 'veg', true, 'main', NULL, '5 min', '20 min', 'Varan Bhaat is Maharashtra''s most primal comfort meal — the simplest preparation of toor dal poured over hot rice with ghee. It is the first solid food given to children, the food craved in illness, and the dish served at the end of the most elaborate wedding feasts.', 'The varan should be watery, not thick; it pools into the rice rather than sitting on top.', 'Traditional', NULL, ARRAY['Toor dal — ½ cup','Steamed rice — 1 cup','Turmeric — ¼ tsp','Ghee — 1 tsp','Kokum — 2 petals','Salt to taste']::text[], ARRAY['Wash and pressure cook toor dal with turmeric until very soft (3 whistles).','Lightly mash the dal; add kokum petals and salt.','Heat ghee in a small pan; add mustard seeds — pour over the dal once they splutter.','Serve the varan over hot steamed rice with a drizzle of extra ghee on top.']::text[], ARRAY['lunch']::text[], 'plate', 300, 280, 10, 46, 6, 4, 2, 40, 0.05, 400, true),
  (381, 'Dalma', 'Odia', 'east_indian', 'veg', true, 'dal', NULL, '15 min', '30 min', 'Dalma is Odisha''s defining dal dish — a medley of toor dal cooked with seasonal vegetables and finished with coconut and panch phoron. It is a prasad (sacred offering) at Puri''s Jagannath Temple and is served in the Mahaprasad — one of the world''s largest community kitchens.', 'Add vegetables in order of cooking time; drumstick needs 15 minutes, pumpkin only 8.', 'Traditional', NULL, ARRAY['Toor dal — ½ cup','Raw banana — 1, cubed','Drumstick — 2 pieces','Pumpkin — ½ cup, cubed','Brinjal — 1 small, cubed','Tomato — 1, chopped','Coconut — 2 tbsp, grated','Turmeric — ½ tsp','Panch phoron — 1 tsp','Ghee — 1 tsp','Salt to taste']::text[], ARRAY['Boil toor dal with turmeric until soft; keep aside.','In a separate pot, cook all vegetables (raw banana, drumstick, pumpkin, brinjal) with a little water, panch phoron and turmeric.','Add cooked dal to the vegetables; mix gently.','Heat ghee; add dry red chillies and pour over the dalma.','Add fresh grated coconut; stir, adjust salt and serve with rice.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 320, 16, 44, 8, 10, 3.5, 100, 0.05, 450, true),
  (382, 'Potala Rasa', 'Odia', 'east_indian', 'vegan', false, 'curry', NULL, '10 min', '25 min', 'Potala Rasa is one of Odisha''s most beloved vegetable curries — pointed gourd (parwal) cooked in a light, tomato-based gravy with the distinctive panch phoron tempering that marks all Odia and Bengali cooking. In Odisha, potol (pointed gourd) is revered enough to appear as a Jagannath Temple offering.', 'Do not overcook pointed gourd; it becomes mushy quickly. It should hold its shape in the finished dish.', 'Traditional', NULL, ARRAY['Pointed gourd (parwal) — 6, slit','Potatoes — 2 medium, cubed','Tomato — 2, chopped','Ginger — 1 inch, paste','Turmeric — ½ tsp','Cumin powder — 1 tsp','Coriander powder — 1 tsp','Panch phoron — ½ tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Slit pointed gourds along the length without cutting through; season inside with salt.','Heat oil; add panch phoron; let it splutter.','Add potatoes and fry 3 minutes.','Add tomato, ginger paste, turmeric, cumin and coriander powder; cook until oil surfaces.','Add pointed gourds and ½ cup water; cover and simmer 15 minutes until fully tender.','Adjust salt; serve with rice.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 200, 5, 28, 8, 5, 1.5, 40, 0, 400, true),
  (383, 'Sol Kadhi', 'Konkani', 'west_indian', 'vegan', true, 'drink', NULL, '20 min', '0 min', 'Sol Kadhi is Konkan''s digestive cooler — a pale pink, tangy-spiced drink made from kokum and coconut milk that doubles as a beverage and a digestive curry. Along coastal Maharashtra and Goa, it is drunk straight from a glass after a fish meal to soothe the stomach.', 'Never heat Sol Kadhi — warmth separates the coconut milk and destroys the pink colour.', 'Traditional', NULL, ARRAY['Kokum (sol) — 10 petals, soaked in warm water','Coconut milk — 1 cup','Green chilli — 2, finely chopped','Ginger — ½ inch, grated','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Extract kokum colour and flavour by soaking petals in ½ cup warm water for 15 minutes; squeeze and strain.','Add coconut milk to the kokum water.','Add finely chopped green chilli, grated ginger and salt; stir well.','Garnish with coriander. Serve cold or at room temperature — never heat Sol Kadhi.']::text[], ARRAY['lunch']::text[], 'glass', 200, 90, 2, 8, 6, 1, 1, 20, 0, 300, true),
  (387, 'Dum Aloo Kashmiri', 'Kashmiri', 'north_indian', 'veg', false, 'curry', NULL, '10 min', '30 min', 'Kashmiri Dum Aloo is defined by what it does not contain — no onion, no garlic, no tomato. The sauce is built entirely from whole spices and whisked curd, giving it a pale, ivory warmth that is deeply aromatic but not red-orange like its Punjabi counterpart. A signature of the Kashmiri Pandit kitchen.', 'Fry the potatoes until the skin blisters; this prevents them absorbing too much gravy and going mushy.', 'Traditional', NULL, ARRAY['Baby potatoes — 10, boiled and peeled','Fennel powder — 1 tsp','Ginger powder (saunth) — ½ tsp','Red chilli powder — 1 tsp','Curd — ½ cup','Mustard oil — 2 tbsp','Bay leaves — 2','Cardamom — 3 pods','Clove — 3','Cinnamon — 1 inch','Salt to taste']::text[], ARRAY['Heat mustard oil to smoking; add baby potatoes and fry until golden on all sides. Drain.','In the same oil, add whole spices (bay, cardamom, clove, cinnamon); sauté briefly.','Whisk together curd, fennel powder, ginger powder, red chilli powder and salt.','Add the curd masala to the pan; cook on medium stirring until oil surfaces (5 min).','Add fried potatoes; coat well. Add ½ cup water and simmer 10 minutes covered.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 280, 6, 36, 12, 4, 1.5, 90, 0.2, 450, true),
  (388, 'Vegetable Tenga', 'Assamese', 'northeast_indian', 'vegan', true, 'curry', NULL, '10 min', '20 min', 'Vegetable Tenga is Assam''s signature sour curry, brightened with tomato and lemon — a palate-cleansing counterpoint to rich dals. Tenga means sour and is a compulsory part of the traditional Assamese thali, served toward the end of the meal.', 'Add lemon juice only off the heat; boiling it can turn the broth bitter.', 'Traditional', NULL, ARRAY['Raw papaya — 1 cup, cubed','Tomato — 2, chopped','Lemon — 1 (juice)','Panch phoron — ½ tsp','Mustard oil — 2 tbsp','Green chilli — 2, slit','Turmeric — ¼ tsp','Salt to taste']::text[], ARRAY['Heat mustard oil; add panch phoron and let it splutter.','Add green chilli and ginger; sauté briefly.','Add cubed raw papaya; stir to coat.','Add tomato and turmeric; cook 3 minutes.','Add lemon juice and a little water; cover and cook until papaya is just tender.','Season with salt; the broth should remain light and sour.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 180, 5, 24, 8, 5, 1.2, 50, 0, 350, true),
  (389, 'Rajma Chawal', 'Punjabi', 'north_indian', 'vegan', false, 'main', NULL, '10 min (plus overnight soak)', '50 min', 'Rajma Chawal is Delhi and Punjab''s ultimate Sunday meal — rich, slow-cooked kidney beans over rice, a combination so beloved it has spawned restaurants, T-shirts and a generational nostalgia that transcends regional identity. Every Punjabi home has a slightly different rajma recipe.', 'Cook rajma in its soaking water — the liquid carries flavour that is lost when you drain and start fresh.', 'Traditional', NULL, ARRAY['Kidney beans (rajma) — 1 cup, soaked overnight','Basmati rice — ½ cup','Onion — 2 medium, finely chopped','Tomato — 2, chopped','Ginger-garlic paste — 1 tbsp','Rajma masala — 1 tbsp','Cumin seeds — 1 tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Pressure cook soaked rajma until very tender (5–6 whistles); do not drain.','Cook basmati rice until fluffy; keep warm.','Heat oil; fry onion until deep brown. Add ginger-garlic paste; cook 2 min.','Add tomato and rajma masala; cook until oil surfaces.','Add cooked rajma with its liquid; simmer 20 minutes mashing a few beans.','Serve rajma over rice — they are always eaten together.']::text[], ARRAY['lunch']::text[], 'plate', 350, 420, 18, 64, 10, 12, 4, 100, 0, 600, true),
  (391, 'Nadru Yakhni', 'Kashmiri', 'north_indian', 'veg', false, 'curry', NULL, '10 min', '25 min', 'Nadru Yakhni is a Kashmiri Pandit delicacy — lotus stem cooked in a fragrant yoghurt-based sauce (yakhni) scented with fennel and cardamom. Yakhni gravies are among Kashmiri cuisine''s most elegant preparations: pale, aromatic and built without any browning or caramelisation.', 'Slice lotus stem into equal-thickness rounds so they cook evenly — thick pieces stay hard while thin ones overcook.', 'Traditional', NULL, ARRAY['Lotus stem (nadru) — 2 cups, sliced','Curd — ½ cup','Fennel powder — 1 tsp','Ginger powder (saunth) — ½ tsp','Cardamom powder — ¼ tsp','Clove — 3','Bay leaf — 1','Mustard oil — 2 tbsp','Salt to taste']::text[], ARRAY['Heat mustard oil; add cloves and bay leaf; sauté briefly.','Add sliced lotus stem; fry 2 minutes until lightly coloured.','Whisk curd with fennel powder, ginger powder, cardamom and salt.','Add curd mixture to the lotus stem; stir and cook on medium heat 8 minutes.','Add ½ cup water; simmer until lotus stem is fully tender and sauce coats it.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 240, 7, 32, 10, 5, 2, 120, 0.3, 400, true),
  (392, 'Kashmiri Paneer Curry', 'Kashmiri', 'north_indian', 'veg', true, 'curry', NULL, '10 min', '25 min', 'Kashmiri Paneer Curry follows the Wazwan tradition of cooking without onion or tomato — the sourced curd does all the work, bloomed with fennel and ginger powder that are the twin pillars of Kashmiri spice. The result is a delicate, ivory-hued curry of great depth.', 'Use full-fat paneer and full-fat curd; both low-fat versions tend to split in the sauce.', 'Traditional', NULL, ARRAY['Paneer — 200 g, cubed','Curd — ½ cup','Fennel powder — 1 tsp','Ginger powder — ½ tsp','Kashmiri red chilli powder — 1 tsp','Cardamom — 3 pods','Clove — 3','Cinnamon — 1 inch','Mustard oil — 2 tbsp','Salt to taste']::text[], ARRAY['Heat mustard oil; add whole spices (cardamom, clove, cinnamon); sauté 30 seconds.','Whisk curd with fennel powder, ginger powder, Kashmiri chilli powder and salt.','Add paneer and half the curd mixture; cook on medium 5 minutes.','Add remaining curd mixture; simmer until oil separates from the sauce (10 min).','Adjust seasoning; serve with rice or sheermal.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 360, 18, 20, 24, 2, 1, 450, 0.8, 500, true),
  (393, 'Dhokar Dalna', 'Bengali', 'east_indian', 'vegan', false, 'curry', NULL, '20 min (plus soak)', '35 min', 'Dhokar Dalna is one of Bengal''s most ingenious vegetarian dishes — a lentil cake (dhokar) fried golden and then braised in a fragrant potato curry. The dhoka absorbs the gravy while retaining its firm, satisfying bite, making it a prized centrepiece of the Bengali thali.', 'Cool the steamed dhoka completely before frying; warm dhoka crumbles in hot oil.', 'Traditional', NULL, ARRAY['Chana dal — 1 cup, soaked','Ginger — 1 inch, paste','Green chilli — 2, finely chopped','Potato — 2, cubed','Tomato — 1, chopped','Turmeric — ½ tsp','Cumin powder — 1 tsp','Garam masala — ½ tsp','Oil — 3 tbsp','Salt to taste']::text[], ARRAY['Soak chana dal; grind coarsely with ginger and green chilli.','Season with salt; steam in greased moulds or a flat pan until firm (15 min).','Cut into diamond shapes once cooled.','Shallow-fry the dhokar pieces in oil until golden on both sides.','Make a potato curry with tomato, turmeric, cumin and garam masala.','Add fried dhokar pieces to the curry; simmer 5 minutes and serve.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 340, 14, 38, 16, 7, 3, 70, 0, 500, true),
  (394, 'Begun Bhaja with Dal', 'Bengali', 'east_indian', 'vegan', true, 'main', NULL, '15 min', '25 min', 'Begun Bhaja with Dal is a simple Bengali pairing that elevates an everyday dinner — the smoky crust of the fried brinjal contrasts with the light, delicately spiced moong dal. Mustard oil is non-negotiable; it carries the dish''s characteristic pungency.', 'Salt the brinjal slices before frying to draw out moisture and prevent oil splatter.', 'Traditional', NULL, ARRAY['Brinjal (begun) — 2 large, sliced thick','Moong dal — ½ cup','Turmeric — ¼ tsp','Mustard oil — 3 tbsp','Panch phoron — ½ tsp','Green chilli — 2, slit','Salt to taste']::text[], ARRAY['Slice brinjal into thick rounds; salt and rest 10 minutes, then pat dry.','Heat mustard oil generously; fry brinjal slices until golden on both sides. Drain on paper.','In the same pan, cook moong dal with turmeric and water until soft.','Temper the dal with panch phoron in hot oil; add green chilli.','Serve fried brinjal alongside the dal — they are eaten together.']::text[], ARRAY['dinner']::text[], 'serving', 250, 300, 12, 38, 12, 6, 3, 70, 0, 450, true),
  (395, 'Kolhapuri Paneer', 'Maharashtrian', 'west_indian', 'veg', false, 'curry', NULL, '15 min', '30 min', 'Kolhapuri cuisine is Maharashtra''s most fiery school — Kolhapur in southern Maharashtra is famous for its fierce red chilli use and complex spice blends. Kolhapuri Paneer brings this heat to a rich, coconut-thickened gravy that is emphatically not for the mild palate.', 'Kolhapuri masala varies by brand — taste before adding to judge heat level.', 'Traditional', NULL, ARRAY['Paneer — 200 g, cubed','Onion — 2, finely chopped','Tomato — 2, chopped','Ginger-garlic paste — 1 tbsp','Kolhapuri masala — 2 tsp','Coconut — 2 tbsp, grated','Sesame seeds — 1 tbsp','Oil — 3 tbsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Heat oil; add onion and sauté until deep brown. Add ginger-garlic paste; cook 2 minutes.','Add tomato and cook until oil separates.','Add Kolhapuri masala, grated coconut and sesame seeds; sauté 2 minutes.','Add whisked curd; stir and simmer 5 minutes.','Add paneer cubes; coat with gravy and simmer 8 minutes covered.','Garnish with coriander and serve with bhakri or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 380, 20, 18, 26, 4, 1.5, 450, 0.8, 550, true),
  (396, 'Shengdana Kadhi', 'Maharashtrian', 'west_indian', 'veg', true, 'dal', NULL, '5 min', '15 min', 'Shengdana Kadhi is Maharashtra''s peanut-enriched kadhi — distinctly different from Gujarati kadhi in its use of ground peanuts and absence of sweetness. It is a peasant dish from the Vidarbha and Marathwada regions where peanuts are a primary crop.', 'Stir continuously after adding the curd mixture — any pause can cause it to split or stick.', 'Traditional', NULL, ARRAY['Peanuts — ¼ cup, roasted and ground','Curd — 1 cup','Besan — 1 tbsp','Jaggery — 1 tsp','Green chilli — 2, slit','Ginger — ½ inch, grated','Mustard seeds — ½ tsp','Curry leaves — 8','Coriander — 2 tbsp','Salt to taste']::text[], ARRAY['Whisk curd with besan and salt in a bowl until smooth.','Heat oil; add mustard seeds, curry leaves, green chilli and ginger.','Pour in the curd-besan mixture; stir continuously on low heat 8 minutes until thickened.','Add ground peanut paste; mix well and simmer 3 more minutes.','Add jaggery; stir and adjust consistency with water. Serve hot with rice or bhakri.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 200, 8, 22, 10, 4, 1, 200, 0.4, 400, true),
  (397, 'Panchkuta Sabzi', 'Rajasthani', 'north_indian', 'veg', true, 'side', NULL, '10 min (plus overnight soak)', '20 min', 'Panchkuta Sabzi is a celebration of Rajasthan''s desert ingenuity — five wild, sun-dried plants (panchkuta means five ingredients) cooked together into an intensely flavoured dry sabzi. All five ingredients grow wild in the Thar Desert and were historically preserved through drying for year-round use.', 'Cook completely dry — any moisture makes panchkuta heavy and dulls its sharp, concentrated flavour.', 'Traditional', NULL, ARRAY['Ker (dried berries) — ¼ cup, soaked','Sangri (dried beans) — ¼ cup, soaked','Kumatiya (dried seeds) — 2 tbsp','Amchur — ½ tsp','Gunda (dried berry) — 2 tbsp, soaked','Red chilli powder — 1 tsp','Coriander powder — 1 tsp','Ghee — 2 tbsp','Salt to taste']::text[], ARRAY['Drain soaked ker, sangri, kumatiya and gunda.','Heat ghee; add soaked gunda and kumatiya; fry 2 minutes.','Add ker and sangri; sauté on medium heat 3 minutes.','Add red chilli powder, coriander powder and amchur; mix well.','Cook covered on low heat 10 minutes. Season with salt.','Serve with bajra roti — this dish is deliberately dry.']::text[], ARRAY['dinner']::text[], 'bowl', 100, 180, 5, 20, 10, 7, 2, 80, 0.05, 450, true),
  (398, 'Kathal Ghee Roast', 'Karnataka', 'south_indian', 'veg', false, 'side', NULL, '20 min', '35 min', 'Kathal Ghee Roast is Mangalore''s vegetarian answer to the legendary ghee roast — a fiery, aromatic preparation of raw jackfruit in a red-chilli and ghee-based masala. The restaurant Shetty Lunch Home in Mangalore made ghee roast famous; the jackfruit version is now celebrated in its own right.', 'Drain and pat jackfruit completely dry before frying; moisture prevents the charring that defines the dish.', 'Traditional', NULL, ARRAY['Raw jackfruit (kathal) — 2 cups, boiled','Ghee — 3 tbsp','Onion — 2, thinly sliced','Tomato — 2, chopped','Ginger-garlic paste — 1 tbsp','Ghee roast masala — 2 tsp','Curd — 3 tbsp','Curry leaves — 10','Salt to taste']::text[], ARRAY['Boil jackfruit until just tender; drain and pat dry.','Marinate with ghee roast masala, curd, salt and turmeric for 15 minutes.','Heat ghee in a wide pan; fry onion slices until deep golden brown.','Add marinated jackfruit and fry on high heat until edges char slightly.','Add tomato and cook until gravy is thick and coats the jackfruit.','Finish with more ghee and curry leaves; serve with neer dosa.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 320, 8, 36, 16, 6, 2, 80, 0.1, 500, true),
  (399, 'Jackfruit Gassi', 'Konkani', 'west_indian', 'vegan', false, 'curry', NULL, '15 min', '35 min', 'Jackfruit Gassi is the pride of Konkani coastal cooking — a rich, deep-red curry built on a paste of roasted red chillies and coconut that is ground on a stone slab. Gassi (from the Tulu word for curry) is the essential preparation of Mangalorean cuisine.', 'Roast the red chillies and coriander seeds dry before grinding — this deepens the gassi''s colour and flavour.', 'Traditional', NULL, ARRAY['Raw jackfruit — 2 cups, boiled and cubed','Coconut — ½ cup, grated','Red chillis — 4, dried','Coriander seeds — 2 tsp','Cumin seeds — 1 tsp','Tamarind — small piece','Turmeric — ¼ tsp','Onion — 1, chopped','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Grind coconut, red chillies, coriander seeds, cumin and tamarind into a thick paste using a little water.','Heat oil; sauté onion until golden.','Add raw jackfruit and the ground masala paste; cook on medium heat 5 minutes.','Add 1 cup water; cover and simmer 20 minutes until jackfruit is fully cooked and masala is thick.','Adjust salt and serve with neer dosa or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 7, 32, 16, 7, 2, 70, 0, 450, true),
  (401, 'Khichdi with Gujarati Kadhi', 'Gujarati', 'west_indian', 'veg', true, 'main', NULL, '10 min', '35 min', 'Khichdi with Gujarati Kadhi is the definitive Gujarati comfort meal — the sweetened, tangy kadhi complements the bland, nourishing khichdi. Gujarati kadhi is notably sweeter than its Rajasthani cousin; jaggery is what makes the difference.', 'Stir the kadhi continuously from the start; even one minute unattended can cause it to split.', 'Traditional', NULL, ARRAY['Rice — ½ cup','Moong dal — ¼ cup','Curd — 1 cup','Besan — 2 tbsp','Jaggery — 1 tsp','Ginger — ½ inch, grated','Green chilli — 2, slit','Ghee — 1 tbsp','Mustard seeds — ½ tsp','Curry leaves — 8','Salt to taste']::text[], ARRAY['Cook rice and moong dal together with turmeric until soft and mushy (khichdi).','Whisk curd with besan, jaggery and salt; add water to make a thin batter.','Heat ghee; add mustard seeds, curry leaves, ginger and green chilli.','Pour in the curd-besan mixture; stir continuously until it thickens (10 min).','Serve hot kadhi poured over khichdi — they are meant to be eaten together.']::text[], ARRAY['dinner']::text[], 'plate', 350, 380, 14, 54, 12, 6, 2.5, 200, 0.4, 550, true),
  (404, 'Mor Kuzhambu', 'Tamil', 'south_indian', 'veg', true, 'curry', NULL, '15 min', '25 min', 'Mor Kuzhambu is Tamil Nadu''s curd-based curry — a cousin of Kerala''s mor kuzhambu and Karnataka''s majjige huli, all descended from the same ancient South Indian tradition of cooking vegetables in tempered, spiced curd. The coconut paste makes the Tamil version thicker and richer than its Kerala counterpart.', 'Never let mor kuzhambu boil after adding curd — it splits into grainy curds and watery whey in seconds.', 'Traditional', NULL, ARRAY['Curd — 1 cup','Coconut — 3 tbsp, grated','Raw banana or colocasia — 1 cup, cubed and boiled','Green chilli — 2','Ginger — ½ inch','Cumin seeds — 1 tsp','Turmeric — ¼ tsp','Coconut oil — 1 tbsp','Mustard seeds — ½ tsp','Curry leaves — 10','Salt to taste']::text[], ARRAY['Blend coconut, green chilli, ginger and cumin to a fine paste.','Boil colocasia or raw banana until tender; keep aside.','Whisk the coconut paste into the curd with turmeric.','Temper coconut oil with mustard seeds and curry leaves; add to the curd paste.','Add cooked vegetable; warm gently on very low heat. Do not boil.','Serve with rice — the consistency should be like a thin curry.']::text[], ARRAY['dinner']::text[], 'bowl', 160, 160, 6, 16, 8, 3, 1, 160, 0.4, 420, true),
  (407, 'Sindhi Kadhi', 'Sindhi', 'west_indian', 'vegan', false, 'dal', NULL, '15 min', '35 min', 'Sindhi Kadhi is unlike any other kadhi in India — instead of a curd base, it uses roasted besan (gram flour) as the thickening agent, making it suitable for those who do not eat curd. The roasting is essential; raw besan makes the kadhi taste floury and bitter.', 'Roast the besan until it smells nutty and turns light brown — this is the most important step in the entire dish.', 'Traditional', NULL, ARRAY['Besan (gram flour) — 3 tbsp','Tomato — 2, chopped','Drumstick — 2 pieces','Bhindi (okra) — 6, whole','Potato — 1, cubed','Tamarind — small piece','Turmeric — ½ tsp','Cumin seeds — 1 tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Dry-roast besan in a heavy pan on low heat, stirring continuously, until golden and fragrant (5 min). This removes rawness.','Add chopped tomato and drumstick pieces; cook 3 minutes.','Pour in 3 cups water; bring to a boil stirring to prevent lumps.','Add bhindi, potato and tamarind; simmer 20 minutes.','Temper with cumin seeds in hot oil; pour over kadhi. Adjust salt and consistency.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 220, 6, 30, 10, 5, 2.2, 70, 0, 480, true),
  (408, 'Dalma with Ghee', 'Odia', 'east_indian', 'veg', false, 'dal', NULL, '10 min', '30 min', 'Dalma with Ghee is the evening version of Odisha''s temple dal — richer, more nourishing, and deliberately simple. The ghee is not optional; it is the flavour. This is the kind of meal that Odia grandmothers make when they want to restore someone.', 'Use good-quality ghee and add it at the end off the heat to preserve its aroma.', 'Traditional', NULL, ARRAY['Toor dal — ½ cup','Raw banana — 1, cubed','Yam — ½ cup, cubed','Pumpkin — ½ cup, cubed','Tomato — 1, chopped','Coconut — 2 tbsp, grated','Ghee — 2 tsp','Panch phoron — 1 tsp','Dry red chilli — 2','Salt to taste']::text[], ARRAY['Pressure cook toor dal with turmeric until very soft.','Cook yam and pumpkin together in a pot with water, panch phoron and red chilli.','Add soft-cooked dal to the vegetables; stir gently.','Drizzle generously with ghee; add grated coconut and season with salt.','Serve hot — dalma with ghee is best when freshly made.']::text[], ARRAY['dinner']::text[], 'bowl', 220, 320, 15, 44, 9, 10, 3.2, 90, 0.05, 450, true),
  (409, 'Chhena Poda', 'Odia', 'east_indian', 'veg', true, 'dessert', NULL, '15 min', '40 min', 'Chhena Poda (meaning burnt cheese) is Odisha''s most distinctive sweet — fresh paneer baked with jaggery until the exterior caramelises to an almost bitter crust while the interior stays soft and custardy. It is said to be Lord Jagannath''s favourite offering at Puri Temple.', 'The dark, almost charred exterior is correct and intentional — do not remove it from the oven too early.', 'Traditional', NULL, ARRAY['Fresh paneer (chhena) — 200 g','Jaggery — 4 tbsp','Semolina — 2 tbsp','Cardamom powder — ½ tsp','Cashews — 8','Raisins — 1 tbsp','Ghee — 1 tsp (for greasing)']::text[], ARRAY['Crumble fresh chhena into a bowl; add jaggery, semolina, cardamom and mix well.','Fold in cashews and raisins. The mixture should be slightly sticky.','Grease a baking pan with ghee; spread the mixture 2–3 cm thick.','Bake at 180°C for 35–40 minutes until the top is deeply caramelised and a toothpick comes out clean.','Cool completely before cutting — the crust should be dark brown.']::text[], ARRAY['dinner','snack']::text[], 'piece', 110, 280, 12, 36, 10, 1, 0.8, 320, 0.6, 60, true),
  (410, 'Pesarattu Upma', 'Andhra', 'south_indian', 'vegan', false, 'main', NULL, '15 min', '25 min', 'Pesarattu Upma is Andhra''s beloved combo dish — a crisp moong crepe wrapped around lightly spiced semolina upma. The contrast of textures makes it a filling dinner that is lighter than it looks.', 'Serve immediately; the crepe softens within minutes of plating.', 'Traditional', NULL, ARRAY['Pesarattu (green moong crepe) — 2, fresh','Semolina upma — 1 cup (semolina ½ cup, onion, green chilli, ginger, oil 1 tsp, salt)','Ginger — 1 inch, finely chopped','Green chilli — 2, finely chopped','Onion — 1 small, finely chopped','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Prepare semolina upma: sauté onion, green chilli, ginger in oil; add semolina, toast briefly, add 1 cup hot water and cook dry.','Blend soaked moong dal with ginger, chilli and salt into a thick batter.','Spread pesarattu batter on a hot griddle into a thin round.','Place a portion of hot upma in the centre; fold the crepe over it.','Cook until crisp on both sides. Serve with coconut chutney.']::text[], ARRAY['dinner']::text[], 'plate', 260, 300, 12, 44, 8, 5, 3, 60, 0, 520, true),
  (411, 'Jhal Muri', 'Bengali', 'east_indian', 'vegan', false, 'snack', NULL, '10 min', '0 min', 'Jhal Muri is Kolkata''s most democratic street food — vendors on Victoria Memorial lawns and Howrah Bridge approaches toss this spiced puffed rice in conical newspaper cones. The mustard oil is what separates genuine Jhal Muri from imitations.', 'Toss and eat immediately; even 5 minutes of waiting makes the puffed rice lose its crunch.', 'Traditional', NULL, ARRAY['Puffed rice (muri) — 2 cups','Boiled potato — 1 small, diced','Onion — 1 small, finely chopped','Tomato — 1 small, diced','Green chilli — 2, finely chopped','Cucumber — ½, diced','Sev (crispy noodles) — 2 tbsp','Tamarind chutney — 1 tbsp','Mustard oil — 1 tsp','Salt to taste']::text[], ARRAY['Boil potato until tender; cool and dice small.','Combine puffed rice, diced potato, onion, tomato, cucumber and green chilli in a wide bowl.','Add tamarind chutney, mustard oil and salt; toss vigorously.','Top with sev and serve immediately — jhal muri goes soggy within 2 minutes.']::text[], ARRAY['snack']::text[], 'bowl', 120, 180, 5, 30, 6, 3, 1.5, 35, 0, 520, true),
  (412, 'Singara', 'Bengali', 'east_indian', 'vegan', false, 'snack', NULL, '30 min', '30 min', 'Singara is West Bengal''s version of the samosa — but more triangular, with a filling that is potato-forward rather than pea-heavy, and a crust that is thicker and flakier. Every neighbourhood''s mishti dokan has its own singara recipe, and Bengalis are fiercely loyal to their local variety.', 'The dough must be quite stiff — a soft dough absorbs too much oil and turns greasy.', 'Traditional', NULL, ARRAY['Maida — 1 cup','Potato — 2 medium, boiled and mashed','Green peas — ¼ cup, boiled','Ginger — ½ inch, grated','Green chilli — 2, finely chopped','Cumin seeds — ½ tsp','Coriander powder — ½ tsp','Oil — for frying','Salt to taste']::text[], ARRAY['Boil potato cubes until half done; cool.','Make dough: rub oil into maida, add salt and water to form a tight dough; rest 20 min.','Mix mashed potato filling with peas, ginger, green chilli, cumin and spices.','Roll dough into rounds; cut into halves; shape each half into a cone.','Fill with potato mixture; seal edges with a little water.','Deep-fry in medium oil until golden and crisp.']::text[], ARRAY['snack']::text[], 'piece', 80, 220, 6, 28, 10, 4, 1.2, 25, 0, 320, true),
  (413, 'Dahi Vada', 'South Indian', 'south_indian', 'veg', true, 'snack', NULL, '15 min (plus 2 hr soak)', '20 min', 'Dahi Vada (or Dahi Bhalla in the North) is one of India''s most ancient snacks — urad dal fritters soaked in water to make them tender, then drowned in curd and chutney. The contrast of warm-cool, soft-crisp, sour-sweet makes it one of Indian cuisine''s most complete sensory experiences.', 'Soaking fried vadas in water (not curd directly) is the step that makes them soft — skip it and they stay dense.', 'Traditional', NULL, ARRAY['Urad dal — ½ cup, soaked','Curd — 1 cup','Tamarind chutney — 2 tbsp','Green chutney — 2 tbsp','Roasted cumin powder — ½ tsp','Red chilli powder — ¼ tsp','Oil — for frying','Salt to taste']::text[], ARRAY['Soak urad dal 2 hours; grind to a smooth, fluffy batter. Season with salt.','Drop tablespoons of batter into medium-hot oil; fry vadas until golden brown.','Soak fried vadas in warm water for 2 minutes; gently squeeze excess water out.','Whisk curd smooth; arrange vadas on a plate and pour curd over.','Top with tamarind chutney, green chutney, cumin powder and chilli powder.']::text[], ARRAY['snack','breakfast','lunch','dinner']::text[], 'serving', 180, 220, 10, 28, 8, 3, 1.8, 180, 0.4, 560, true),
  (414, 'Khakhra', 'Gujarati', 'west_indian', 'vegan', true, 'snack', NULL, '15 min', '20 min', 'Khakhra is Gujarat''s iconic thin, crispy flatbread — traditionally made by Jain communities as a shelf-stable, oil-free snack. Unlike phulkas which puff and soften, khakhra is pressed flat and dried on the tawa until completely crisp. It can last weeks without refrigeration.', 'The key is patience — cook on the lowest possible heat to dry the khakhra without burning it.', 'Traditional', NULL, ARRAY['Whole wheat flour — 1 cup','Methi (fenugreek) leaves — ¼ cup, finely chopped','Red chilli powder — ½ tsp','Cumin seeds — ½ tsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Mix whole wheat flour, methi leaves, red chilli powder, cumin, oil, salt and curd into a soft but not sticky dough.','Divide into balls; roll each into a thin round (thinner than paratha).','Cook on a dry tawa on low-medium heat, pressing firmly, until both sides are dry, spotted and crisp.','Khakhra must be fully dry — continue cooking on very low heat if needed.']::text[], ARRAY['snack']::text[], 'piece', 30, 120, 4, 20, 3, 2, 1.2, 30, 0, 200, true),
  (415, 'Chevdo', 'Gujarati', 'west_indian', 'vegan', true, 'snack', NULL, '5 min', '10 min', 'Chevdo is Gujarat''s beloved travel snack — a spiced, crunchy poha mix that keeps for weeks and accompanies every Gujarati road trip, train journey and tea time. Each household adds its own combination of nuts and dried fruit.', 'The mix crisps only once fully cooled — do not judge it while hot.', 'Traditional', NULL, ARRAY['Thin poha (flattened rice) — 1 cup','Peanuts — ¼ cup','Cashews — 2 tbsp','Raisins — 1 tbsp','Curry leaves — 10','Mustard seeds — ½ tsp','Turmeric — ¼ tsp','Red chilli powder — ½ tsp','Sugar — 1 tsp','Oil — 2 tbsp','Salt to taste']::text[], ARRAY['Heat oil; add mustard seeds, curry leaves and red chilli powder.','Add thin poha and toss quickly so it coats evenly.','Add peanuts, cashews and raisins; toss on medium heat 3–4 minutes.','Add turmeric, sugar and salt; mix well.','Spread on a plate to cool completely before storing. It crisps as it cools.']::text[], ARRAY['snack']::text[], 'bowl', 45, 200, 6, 26, 9, 3, 1.2, 25, 0, 380, true),
  (416, 'Mirchi Vada', 'Rajasthani', 'north_indian', 'vegan', false, 'snack', NULL, '15 min', '20 min', 'Mirchi Vada is Jodhpur''s most iconic street food — a massive green chilli stuffed with spiced potato and encased in a thick besan batter, sold by roadside stalls outside Jodhpur''s Sardar Market. The chilli''s heat against the mild potato filling is its defining paradox.', 'Remove all seeds from the chilli to control the heat level; the chilli itself provides enough flavour without the seeds.', 'Traditional', NULL, ARRAY['Large green chillies — 4','Boiled potato — 2, mashed','Besan — ¾ cup','Ginger — ½ inch, grated','Coriander powder — 1 tsp','Amchur — ½ tsp','Oil — for frying','Salt to taste']::text[], ARRAY['Make the stuffing: combine mashed potato with coriander powder, amchur and salt.','Slit each large green chilli lengthwise and remove seeds.','Fill each chilli with potato stuffing.','Make a thick batter with besan, ginger and salt; dip stuffed chillies to coat.','Deep-fry in hot oil until batter is golden and crisp.','Drain and serve hot with tamarind chutney.']::text[], ARRAY['snack']::text[], 'piece', 90, 200, 6, 24, 10, 3, 1.6, 35, 0, 380, true),
  (417, 'Dal Kachori', 'Rajasthani', 'north_indian', 'vegan', true, 'snack', NULL, '20 min (plus soak)', '25 min', 'Dal Kachori is Jaipur''s most famous street food — a crisp, flaky shell enclosing a spiced urad dal filling, sold at chai stalls from 6 AM. The Rawat Mishthan Bhandar''s version near Ajmer Gate has been feeding Jaipuris for over 80 years.', 'Fry on medium heat only; a high flame seals the outside before the kachori puffs properly.', 'Traditional', NULL, ARRAY['Maida — 1 cup','Urad dal — ½ cup, soaked','Fennel seeds — ½ tsp','Ginger — ½ inch, grated','Green chilli — 2, finely chopped','Coriander powder — 1 tsp','Oil — for frying','Salt to taste']::text[], ARRAY['Soak urad dal; blend to a smooth, thick paste with fennel, ginger and chilli.','Season with salt; the filling should be stiff.','Make a dough with maida, salt, and oil; rest 15 min.','Stuff filling into dough balls; roll into thick puris.','Deep-fry on medium heat until puffed and golden on both sides.','Serve hot with tamarind chutney.']::text[], ARRAY['snack']::text[], 'piece', 80, 250, 8, 32, 12, 5, 1.8, 30, 0, 350, true),
  (418, 'Chakli', 'Maharashtrian', 'west_indian', 'vegan', true, 'snack', NULL, '20 min', '25 min', 'Chakli is Maharashtra and Karnataka''s most beloved festival snack — a crisp, spiral-shaped savoury made from rice flour that is fried to a satisfying crunch. No Diwali faral (snack box) is complete without it; every family has its signature ratio of sesame to cumin.', 'The dough must be soft enough to press without cracking — if it cracks, add a few drops of warm water.', 'Traditional', NULL, ARRAY['Rice flour — 1 cup','Besan — ¼ cup','Sesame seeds — 1 tbsp','Cumin seeds — 1 tsp','Red chilli powder — ½ tsp','Oil — 1 tbsp (in dough)','Oil — for frying','Salt to taste']::text[], ARRAY['Mix rice flour, besan, sesame seeds, cumin, chilli powder, salt and hot oil into a stiff dough using warm water.','Fill a chakli press with the dough and squeeze in spirals onto a plate.','Heat oil on medium; fry chaklis in batches until golden and crisp.','Drain on paper; cool completely before storing — they crisp further as they cool.']::text[], ARRAY['snack']::text[], 'piece', 35, 180, 5, 24, 8, 2, 1, 40, 0, 300, true),
  (419, 'Karanji', 'Maharashtrian', 'west_indian', 'vegan', true, 'dessert', NULL, '25 min', '25 min', 'Karanji is Maharashtra''s Diwali favourite — a half-moon pastry with a sweet coconut-jaggery filling, similar to Goa''s nevri and Andhra''s kajjikayalu. In Maharashtra, Karanji symbolises abundance and is made in large batches and gifted to neighbours during the festival.', 'Seal the edges well with water and press with a fork; any gap will cause the filling to leak out into the oil.', 'Traditional', NULL, ARRAY['Maida — 1 cup','Grated fresh coconut — ½ cup','Jaggery — ¼ cup','Cardamom powder — ½ tsp','Poppy seeds — 1 tbsp','Oil — for frying','Salt — a pinch']::text[], ARRAY['Knead maida with a little oil and salt into a firm dough; rest 20 min.','Toast coconut in a dry pan until lightly golden. Mix with jaggery, cardamom and poppy seeds.','Roll dough into thin circles; place filling on one half, fold and seal edges.','Deep-fry in medium oil until golden on both sides.','Drain and serve; they firm up as they cool.']::text[], ARRAY['snack']::text[], 'piece', 50, 220, 5, 28, 10, 2, 1, 30, 0, 40, true),
  (420, 'Mathri', 'Rajasthani', 'north_indian', 'vegan', true, 'snack', NULL, '15 min', '25 min', 'Mathri is North India''s evergreen snack — a firm, crumbly, ajwain-flavoured biscuit that is the pantry staple of every Punjabi and Rajasthani household. Made in bulk for journeys, festivals and unexpected guests, mathri paired with pickle and chai is a universal North Indian afternoon ritual.', 'Fry on low heat — mathri must dry out from the inside; high heat browns the outside while leaving a raw centre.', 'Traditional', NULL, ARRAY['Maida — 1 cup','Ajwain — ½ tsp','Cumin seeds — ½ tsp','Black pepper — ¼ tsp, crushed','Oil — 2 tbsp (in dough)','Oil — for frying','Salt to taste']::text[], ARRAY['Mix maida, ajwain, cumin, black pepper, salt and oil into a firm dough using water.','Divide into small balls; roll into thick discs (thicker than puri, smaller than roti).','Deep-fry on low-medium heat until very light gold and crisp throughout.','Drain and cool completely — mathri firms up further as it cools.','Store in an airtight tin; keeps 2–3 weeks.']::text[], ARRAY['snack']::text[], 'piece', 35, 180, 4, 22, 9, 1, 0.8, 15, 0, 280, true),
  (421, 'Chana Jor Garam', 'Rajasthani', 'north_indian', 'vegan', false, 'snack', NULL, '5 min', '0 min', 'Chana Jor Garam is Rajasthan''s street food classic — spiced whole chickpeas sold piping hot in railway stations and bazaars across North India. The name means simply hot puffed chickpeas; the spicing is designed to be eaten quickly on the move.', 'Warm the boiled chickpeas before seasoning — cold chickpeas absorb spices poorly.', 'Traditional', NULL, ARRAY['White chickpeas — 1 cup, soaked and boiled','Black salt — ½ tsp','Cumin powder — ½ tsp','Chaat masala — ½ tsp','Red chilli powder — ¼ tsp','Lemon juice — 1 tbsp','Onion — 1 small, finely chopped','Green chilli — 1, finely chopped','Coriander leaves — 2 tbsp']::text[], ARRAY['Boil chickpeas until tender; drain and cool.','Combine chickpeas, onion, green chilli and coriander in a bowl.','Add black salt, cumin powder, chaat masala and red chilli powder.','Squeeze lemon juice; toss vigorously until every chickpea is coated.','Serve immediately.']::text[], ARRAY['snack']::text[], 'bowl', 120, 160, 8, 22, 5, 6, 2.2, 60, 0, 520, true),
  (422, 'Roasted Makhana', 'Pan-Indian', 'pan_indian', 'veg', true, 'snack', NULL, '2 min', '8 min', 'Roasted Makhana is India''s most ancient snack food — fox nuts (lotus seeds) were eaten by Vedic sages as a sattvic, fasting-appropriate food thousands of years ago. Light, crisp and protein-rich, they have made a significant comeback as a health snack in modern India.', 'Keep the heat on medium throughout — high heat makes them hard without crisping; low heat makes them chewy.', 'Traditional', NULL, ARRAY['Fox nuts (makhana) — 2 cups','Ghee — 1 tsp','Rock salt — ¼ tsp','Cumin powder — ¼ tsp','Black pepper — ¼ tsp','Chilli flakes — ¼ tsp']::text[], ARRAY['Heat a wide heavy pan on medium; add ghee.','Add makhana and toss continuously for 5–7 minutes until they puff further and turn crisp.','Reduce heat; add rock salt, cumin powder, black pepper and chilli flakes.','Toss to coat evenly; serve immediately while warm, or cool completely for storage.']::text[], ARRAY['snack']::text[], 'bowl', 30, 140, 5, 20, 5, 1, 0.9, 50, 0.02, 230, true),
  (423, 'Moong Dal Chilla', 'Pan-Indian', 'pan_indian', 'vegan', false, 'snack', NULL, '10 min (plus soak)', '20 min', 'Moong Dal Chilla is North India''s protein-rich breakfast crepe — a more filling alternative to the vegetable omelette with none of the cholesterol. Widely adopted in health-conscious kitchens, it is also a traditional Rajasthani breakfast eaten with achar and curd.', 'Keep the batter thick — a runny batter produces lacy crepes that are difficult to flip.', 'Traditional', NULL, ARRAY['Green moong dal — ½ cup, soaked','Onion — 1 small, finely chopped','Green chilli — 2, finely chopped','Ginger — ½ inch, grated','Turmeric — ¼ tsp','Cumin seeds — ½ tsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Soak moong dal; blend with a little water to a thick smooth batter.','Add ginger, green chilli, turmeric, cumin and onion; mix well.','Heat a griddle; pour a ladleful of batter and spread into a small thick circle.','Drizzle oil around edges; cook 3 minutes until the bottom is set.','Flip and cook 2 more minutes until golden on both sides.']::text[], ARRAY['snack','breakfast']::text[], 'piece', 120, 180, 10, 26, 4, 4, 2.4, 45, 0, 340, true),
  (424, 'Pazham Pori', 'Kerala', 'south_indian', 'vegan', true, 'snack', NULL, '10 min', '15 min', 'Pazham Pori (banana fritter) is Kerala''s most beloved evening snack — a golden, crisp batter sleeve around a sweet, soft plantain interior. No school tiffin box, no roadside tea stall, and no Onam feast is complete without it. The use of coconut oil gives it a distinctive aroma.', 'Use very ripe plantain (yellow with black spots) for maximum sweetness; unripe plantain stays starchy and bland inside.', 'Traditional', NULL, ARRAY['Ripe plantain — 2, sliced lengthwise','Maida — ½ cup','Rice flour — 2 tbsp','Turmeric — ¼ tsp','Sugar — 1 tbsp','Coconut oil — for frying','Salt — a pinch']::text[], ARRAY['Mix maida, rice flour, turmeric, sugar and a pinch of salt with water into a thick, smooth batter.','Peel plantain and slice lengthwise into thin strips.','Dip each plantain strip into the batter to coat evenly.','Deep-fry in coconut oil on medium heat until golden and crisp.','Drain and serve hot with chai.']::text[], ARRAY['snack']::text[], 'piece', 70, 200, 3, 32, 8, 2, 0.6, 15, 0, 60, true),
  (426, 'Mandakki Oggarane', 'Karnataka', 'south_indian', 'vegan', false, 'snack', NULL, '5 min', '8 min', 'Mandakki Oggarane is North Karnataka''s street-side puffed rice snack — simpler and earthier than Mumbai''s bhel, its flavour built from mustard oil, peanuts and curry leaves. In Hubli-Dharwad, vendors sell it from large baskets at bus stands, and it is eaten standing up.', 'Use the freshest mandakki (puffed rice) you can find; stale puffed rice soaks up oil and goes limp.', 'Traditional', NULL, ARRAY['Puffed rice (mandakki) — 2 cups','Onion — 1 small, finely chopped','Tomato — 1 small, diced','Green chilli — 2, finely chopped','Peanuts — 2 tbsp','Curry leaves — 8','Mustard seeds — ½ tsp','Turmeric — ¼ tsp','Oil — 1 tbsp','Salt to taste']::text[], ARRAY['Heat oil in a wide pan; add mustard seeds and curry leaves; let them pop.','Add peanuts and fry until just golden.','Add onion, tomato and green chilli; toss briefly.','Add turmeric and puffed rice; toss vigorously on high heat for 2 minutes.','Season with salt; serve immediately while still warm and crisp.']::text[], ARRAY['snack']::text[], 'bowl', 120, 180, 4, 30, 6, 2, 1.3, 30, 0, 400, true),
  (427, 'Arisa Pitha', 'Odia', 'east_indian', 'vegan', true, 'dessert', NULL, '15 min (plus soak)', '25 min', 'Arisa Pitha is Odisha''s festival sweet — a dense, jaggery-sweetened rice cake fried until dark and fragrant. Made for Raja Parba (the agricultural festival) and other Odia celebrations, each pitha is pressed with a distinctive pattern using a wooden block.', 'Fry on medium-low heat — the outside must not brown before the inside cooks through.', 'Traditional', NULL, ARRAY['Rice — 1 cup, soaked and ground to paste','Jaggery — ½ cup','Sesame seeds — 2 tbsp','Cardamom powder — ½ tsp','Oil — for frying']::text[], ARRAY['Soak and coarsely grind rice to a thick paste.','Dissolve jaggery in a little warm water; mix into the rice paste.','Add sesame seeds and cardamom; the batter should be thick enough to hold its shape.','Heat oil on medium; drop tablespoons of batter and flatten into rounds.','Fry slowly until deep brown and cooked through (5–6 min per side). Drain well.']::text[], ARRAY['snack']::text[], 'piece', 60, 240, 4, 40, 8, 1, 1.2, 60, 0, 15, true),
  (428, 'Sprout Salad Chaat', 'Pan-Indian', 'pan_indian', 'vegan', false, 'salad', NULL, '10 min', '0 min', 'Sprout Salad Chaat is the street-food version of a sprouted legume salad — simpler and quicker than the chaat stall''s more elaborate bhel, but carrying the same bright, tangy spirit. The sprouts provide complete protein without any cooking.', 'Use freshly sprouted legumes for crunch; over-sprouted legumes (sprouted more than 48 hours) become too soft for chaat.', 'Traditional', NULL, ARRAY['Mixed sprouts (moong, matki) — 1 cup','Onion — 1 small, finely chopped','Tomato — 1 small, diced','Cucumber — ½, diced','Green chilli — 1, finely chopped','Lemon juice — 2 tbsp','Chaat masala — ½ tsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Combine mixed sprouts, onion, tomato, cucumber and green chilli in a bowl.','Add lemon juice, chaat masala and coriander; season with salt.','Toss well and serve immediately as a snack.']::text[], ARRAY['snack']::text[], 'bowl', 150, 160, 10, 22, 4, 6, 2.8, 70, 0, 380, true),
  (429, 'Ribbon Pakoda', 'Tamil', 'south_indian', 'veg', true, 'snack', NULL, '15 min', '20 min', 'Ribbon Pakoda (also called ribbon murukku) is Tamil Nadu''s Diwali snack — a flat, crisp strip of rice-besan dough that crunches like a wafer. Simpler to make than spiral murukku, it is often the first snack prepared in Diwali batch-cooking sessions because it requires no special moulds.', 'Use a ribbon attachment with a single wide slit; a narrow slit produces strings rather than ribbons and they break in the oil.', 'Traditional', NULL, ARRAY['Rice flour — 1 cup','Besan — ¼ cup','Butter — 1 tbsp','Sesame seeds — 1 tbsp','Red chilli powder — ½ tsp','Cumin seeds — ½ tsp','Asafoetida (hing) — ¼ tsp','Oil — for frying','Salt to taste']::text[], ARRAY['Mix rice flour, besan, butter, sesame, cumin, chilli powder, hing and salt with warm water to form a stiff dough.','Fill a murukku press fitted with a ribbon (flat slit) attachment.','Press directly into hot oil in long strips.','Fry on medium heat until pale gold and very crisp.','Drain, cool and break into pieces for serving.']::text[], ARRAY['snack']::text[], 'bowl', 35, 160, 5, 22, 7, 1, 1, 35, 0.02, 290, true),
  (430, 'Kadboli', 'Maharashtrian', 'west_indian', 'vegan', true, 'snack', NULL, '15 min', '20 min', 'Kadboli is a less-known Maharashtrian Diwali snack — crispier and lighter than chakli, made with a mix of rice flour and besan. Each region has its own shape; the Konkan version is ring-shaped while the Vidarbha version is straight.', 'Fry on medium heat — high heat browns them before the inside dries out, making them soft on the inside.', 'Traditional', NULL, ARRAY['Rice flour — ½ cup','Besan — ½ cup','Sesame seeds — 1 tbsp','Ajwain — ½ tsp','Red chilli powder — ½ tsp','Turmeric — ¼ tsp','Oil — 1 tbsp (in dough)','Oil — for frying','Salt to taste']::text[], ARRAY['Mix rice flour, besan, sesame, ajwain, chilli powder and turmeric with hot oil; add warm water to form a stiff dough.','Press through a kadboli mould or a chakli press with a flat attachment into small rings or sticks.','Deep-fry in medium-hot oil until light gold and crisp.','Drain well and cool before storing.']::text[], ARRAY['snack']::text[], 'piece', 35, 170, 5, 22, 8, 1, 1.2, 40, 0, 300, true),
  (431, 'Tulsi-Ginger Kadha', 'Ayurvedic', 'pan_indian', 'vegan', true, 'drink', NULL, '2 min', '10 min', 'Tulsi-Ginger Kadha is India''s most trusted household remedy — tulsi is Ayurveda''s queen of herbs, revered as an adaptogen, anti-viral and expectorant. Combined with ginger and pepper, this kadha has been simmered on Indian stoves for thousands of years at the first sign of seasonal change.', 'Use fresh tulsi whenever possible; the volatile eugenol in fresh leaves far exceeds dried.', 'Traditional', NULL, ARRAY['Fresh tulsi (holy basil) leaves — 10','Ginger — ½ inch, sliced','Black pepper — 3 corns','Jaggery — 1 tsp','Hot water — 250 ml']::text[], ARRAY['Bring 250 ml water to a boil.','Add tulsi leaves, sliced ginger, black pepper and jaggery.','Simmer 8 minutes until the decoction turns deep amber.','Strain into a cup and sip warm.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 20, 0, 5, 0, 0, 0.2, 10, 0, 5, true),
  (432, 'Ashwagandha Warm Milk', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '5 min', 'Ashwagandha warm milk is an ancient Ayurvedic rasayana — a nightly adaptogenic drink that is said to reduce cortisol, ease nervous tension and promote deep sleep. Turmeric adds anti-inflammatory support.', 'Drink 30 minutes before bed; black pepper is essential as it dramatically increases ashwagandha bioavailability.', 'Traditional', NULL, ARRAY['Milk — 250 ml','Ashwagandha powder — ½ tsp','Turmeric — ¼ tsp','Cardamom powder — ¼ tsp','Honey — 1 tsp','Black pepper — a pinch']::text[], ARRAY['Warm milk in a saucepan over low heat — do not boil.','Whisk in ashwagandha powder, turmeric and cardamom until fully dissolved.','Add a pinch of black pepper (aids absorption of ashwagandha).','Remove from heat; stir in honey once slightly cooled. Serve warm.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 140, 5, 14, 7, 0, 0.3, 300, 1.1, 110, true),
  (433, 'Giloy Kadha', 'Ayurvedic', 'pan_indian', 'vegan', true, 'drink', NULL, '2 min', '12 min', 'Giloy Kadha is Ayurveda''s premier immunity decoction. Tinospora cordifolia (giloy) is classified as a rasayana herb — one that rejuvenates tissues and builds natural resistance. Combined with tulsi and black pepper, this kadha became widely adopted during respiratory illness seasons.', 'Do not use powdered giloy for kadha; the fresh or dried stem releases the bitter tikta compounds that carry its benefit.', 'Traditional', NULL, ARRAY['Giloy stem or giloy powder — 1 tsp','Ginger — ½ inch, sliced','Tulsi leaves — 5','Black pepper — 2 corns','Jaggery — ½ tsp','Hot water — 250 ml']::text[], ARRAY['Combine giloy, ginger and tulsi in a small pot with 250 ml water.','Add black pepper and bring to a boil; simmer 10 minutes until reduced by a third.','Strain into a cup; add jaggery and stir.','Sip warm; best consumed morning or evening.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 15, 0, 4, 0, 0, 0.2, 10, 0, 5, true),
  (434, 'Triphala Water', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '1 min', '0 min', 'Triphala is Ayurveda''s most prescribed rasayana — a tri-fruit formulation of amalaki, bibhitaki and haritaki that collectively support digestion, detoxification and cellular rejuvenation. Used for over 2,000 years, it is considered a tridoshic balancer.', 'Start with ¼ tsp and gradually increase to ½ tsp; a sudden full dose can cause loose stools in sensitive individuals.', 'Traditional', NULL, ARRAY['Triphala powder — ½ tsp','Warm water — 250 ml','Honey — ½ tsp (optional)']::text[], ARRAY['Mix triphala powder with warm (not hot) water.','Add honey if desired and stir well.','Drink on an empty stomach first thing in the morning, or just before bed.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 10, 0, 2, 0, 0, 0.3, 12, 0, 4, true),
  (435, 'Brahmi Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '5 min', 'Brahmi tea is Ayurveda''s memory tonic — Bacopa monnieri has been used in Indian medicine for over 3,000 years to sharpen cognition, calm an anxious mind and support the nervous system. Traditionally consumed by students and scholars.', 'Do not boil brahmi; high heat degrades its bacosides. Steep off the boil for best potency.', 'Traditional', NULL, ARRAY['Brahmi leaves or brahmi powder — 1 tsp','Ginger — ¼ inch, sliced','Honey — ½ tsp','Hot water — 250 ml','Lemon juice — ½ tsp']::text[], ARRAY['Bring 250 ml water to a boil; remove from heat.','Add brahmi leaves or powder and ginger; steep 5 minutes covered.','Strain into a cup.','Stir in lemon juice and honey once warm (not hot). Serve immediately.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 15, 0, 3, 0, 0, 0.2, 10, 0, 4, true),
  (436, 'Shatavari Milk', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '5 min', 'Shatavari milk is Ayurveda''s premier feminine tonic — Asparagus racemosus is classified as a sattvic herb that nourishes ojas (vital essence), supports hormonal balance and is traditionally prescribed for women at all life stages, from menstruation to menopause.', 'Warm rather than boil the milk to preserve shatavari''s delicate saponins.', 'Traditional', NULL, ARRAY['Milk — 250 ml','Shatavari powder — 1 tsp','Cardamom powder — ¼ tsp','Jaggery — 1 tsp','Saffron — a pinch']::text[], ARRAY['Warm milk on low heat; do not boil.','Whisk in shatavari powder, cardamom and jaggery until fully dissolved.','Add saffron strands; stir and let steep 2 minutes off the heat.','Serve warm — best consumed in the evening.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 150, 6, 16, 7, 0, 0.4, 310, 1.1, 110, true),
  (437, 'Mulethi Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '10 min', 'Mulethi (liquorice root) tea is Ayurveda''s throat and respiratory remedy — glycyrrhizin in liquorice soothes inflamed mucous membranes and has antiviral properties. Combined with tulsi and ginger, this kadha has been a household remedy across India for generations.', 'Do not consume daily for more than 4 weeks; mulethi in high doses can affect blood pressure with prolonged use.', 'Traditional', NULL, ARRAY['Mulethi (liquorice) powder — 1 tsp','Ginger — ¼ inch, sliced','Tulsi — 5 leaves','Honey — ½ tsp','Hot water — 250 ml']::text[], ARRAY['Bring 250 ml water to a gentle boil; add mulethi powder, ginger and tulsi.','Simmer 8 minutes on low; strain into a cup.','Add honey when warm (not hot) and sip slowly.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 250, 20, 0, 5, 0, 0, 0.2, 10, 0, 5, true),
  (438, 'CCF Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '1 min', '5 min', 'CCF (Cumin-Coriander-Fennel) tea is Ayurveda''s tridoshic digestive tonic — the three seeds together balance Vata, Pitta and Kapha. Widely prescribed by Ayurvedic practitioners for bloating, sluggish digestion and post-meal discomfort.', 'Sip slowly and warm — gulping rapidly reduces its digestive benefit.', 'Traditional', NULL, ARRAY['Cumin seeds — ½ tsp','Coriander seeds — ½ tsp','Fennel seeds — ½ tsp','Hot water — 250 ml','Honey — ½ tsp (optional)']::text[], ARRAY['Combine cumin, coriander and fennel seeds in a small pot.','Pour 250 ml hot (not boiling) water over them and steep 5 minutes covered.','Strain into a cup.','Add honey if desired and sip slowly between meals.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 250, 15, 0, 3, 0, 1, 0.5, 20, 0, 5, true),
  (439, 'Amla Juice', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '5 min', '0 min', 'Amla juice is Ayurveda''s most celebrated morning tonic — a single amla provides 20 times the vitamin C of an orange. Consumed on an empty stomach it is believed to kindle digestive fire and slow oxidative ageing.', 'Drink within 5 minutes of juicing; add a pinch of black salt to reduce the astringency.', 'Traditional', NULL, ARRAY['Fresh amla (Indian gooseberry) — 2, grated','Honey — 1 tsp','Ginger juice — ½ tsp','Black salt — a pinch','Water — 200 ml']::text[], ARRAY['Grate fresh amla or blend with 2 tbsp water and strain to extract juice.','Combine amla juice with honey, ginger juice, black salt and 200 ml water.','Stir well and serve immediately — amla oxidises quickly once juiced.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 220, 30, 0, 7, 0, 1, 0.4, 15, 0, 90, true),
  (440, 'Moringa Leaf Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '5 min', 'Moringa leaf tea harnesses what Ayurveda calls shigru — a tree described as capable of curing 300 diseases. Moringa oleifera leaves contain all 9 essential amino acids, iron, calcium and potent antioxidants. The tea is a gentle way to absorb these nutrients.', 'Dried moringa is milder than fresh; for the fresh version, steep for only 2 minutes to avoid bitterness.', 'Traditional', NULL, ARRAY['Dried moringa leaves — 1 tsp','Ginger — ¼ inch, sliced','Lemon juice — ½ tsp','Honey — ½ tsp','Hot water — 250 ml']::text[], ARRAY['Bring 250 ml water to a simmer; add dried moringa and ginger.','Steep off the heat for 5 minutes covered.','Strain into a cup; add lemon juice and honey when warm.','Sip slowly in the morning or before meals.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 250, 20, 1, 4, 0, 1, 0.8, 40, 0, 8, true),
  (441, 'Methi Water', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '1 min (plus overnight soak)', '0 min', 'Methi water is one of Ayurveda''s simplest fasting tonics — soaking fenugreek seeds overnight releases mucilaginous compounds and alkaloids (especially trigonelline) that lower fasting blood sugar and aid digestion. Widely prescribed as a morning ritual.', 'Chew and swallow the soaked seeds for maximum fibre benefit; do not discard them.', 'Traditional', NULL, ARRAY['Methi (fenugreek) seeds — 1 tsp, soaked overnight','Water — 250 ml (from soaking)','Lemon juice — ½ tsp','Honey — ½ tsp']::text[], ARRAY['Soak fenugreek seeds in 250 ml water overnight (8 hours minimum).','In the morning, strain seeds out or drink with seeds for additional fibre.','Add lemon juice and honey; stir and drink on an empty stomach.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 20, 1, 4, 0, 1, 0.8, 20, 0, 5, true),
  (442, 'Karela Juice', 'Ayurvedic', 'pan_indian', 'vegan', true, 'drink', NULL, '8 min', '0 min', 'Karela juice is Ayurveda''s bitter medicine — bitter gourd contains compounds that mimic insulin and support glucose metabolism. Consumed for centuries in diabetic households across India, it is one of the most studied plants in Ayurvedic pharmacology.', 'Peel and deseed karela before juicing to reduce extreme bitterness without losing the active compounds.', 'Traditional', NULL, ARRAY['Bitter gourd (karela) — 1 small, peeled and chopped','Amla — 1 (optional)','Ginger — ¼ inch','Black salt — a pinch','Water — 200 ml']::text[], ARRAY['Peel and roughly chop karela; blend with amla and ginger if using.','Add 200 ml water and blend smooth.','Strain through a fine-mesh strainer pressing the pulp.','Add black salt and serve immediately on an empty stomach.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 25, 1, 5, 0, 2, 0.6, 25, 0, 120, true),
  (443, 'Jamun Juice', 'Ayurvedic', 'pan_indian', 'vegan', true, 'drink', NULL, '5 min', '0 min', 'Jamun juice is Ayurveda''s blood-sugar regulating tonic — the dark Indian plum has been used for centuries to support pancreatic function. Its deep purple pigment (jamboline) is considered one of nature''s most effective insulin sensitisers.', 'Do not strain too finely — the pulp contains the fibre that slows sugar absorption.', 'Traditional', NULL, ARRAY['Jamun (black plum) — 1 cup, pitted','Black salt — a pinch','Cumin powder — ¼ tsp','Mint leaves — 5','Water — 100 ml']::text[], ARRAY['Wash ripe jamun and remove seeds.','Blend jamun with mint leaves and 100 ml water until smooth.','Strain through a fine mesh if desired.','Add black salt and cumin powder; stir and serve chilled.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 220, 60, 1, 14, 0, 1, 0.5, 20, 0, 120, true),
  (444, 'Hibiscus and Rose Petal Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '5 min', 'Hibiscus and rose petal tea is an Ayurvedic Pitta-pacifying drink, cooling to the body and beautifying to the skin in classical texts. The deep ruby colour comes from anthocyanins in hibiscus — potent antioxidants that support cardiovascular health.', 'Steep hibiscus off the boil; a rolling boil makes the tea tart and tannic.', 'Traditional', NULL, ARRAY['Dried hibiscus flowers — 1 tsp','Dried rose petals — 1 tsp','Honey — 1 tsp','Cardamom powder — ¼ tsp','Hot water — 250 ml']::text[], ARRAY['Bring 250 ml water to a gentle simmer; do not boil hard.','Add hibiscus flowers, rose petals and cardamom; steep 5 minutes off the heat.','Strain into a cup.','Stir in honey and sip warm or allow to cool and serve chilled.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 250, 20, 0, 5, 0, 0, 0.3, 15, 0, 5, true),
  (445, 'Arjuna Bark Tea', 'Ayurvedic', 'pan_indian', 'veg', true, 'drink', NULL, '2 min', '10 min', 'Arjuna bark tea is one of Ayurveda''s heart tonics, derived from Terminalia arjuna, a tree revered in ancient texts for strengthening the cardiac muscle. It is traditionally consumed in the morning on a light stomach.', 'Add honey only when the tea is warm, not boiling — high heat destroys its beneficial enzymes.', 'Traditional', NULL, ARRAY['Arjuna bark powder — ½ tsp','Cinnamon — ½ inch','Cardamom — 1 pod','Honey — ½ tsp','Milk — 100 ml','Hot water — 150 ml']::text[], ARRAY['Combine arjuna bark powder with cinnamon, cardamom pod and milk in a small pot.','Bring to a gentle simmer and steep 8 minutes — do not boil hard.','Strain into a cup; add hot water to adjust strength.','Stir in honey once slightly cooled and serve warm.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 250, 15, 0, 3, 0, 0, 0.2, 110, 0.2, 25, true),
  (446, 'Tomato-Pepper Rasam', 'Tamil', 'south_indian', 'veg', false, 'dal', NULL, '10 min', '20 min', 'Tomato-Pepper Rasam is Tamil Nadu''s daily medicine — a thin, pungent broth drunk straight from a tumbler or poured over rice. Piperine in black pepper and lycopene in tomato make rasam nutritionally potent; in Tamil households, rasam is the first thing prepared when someone falls ill.', 'Rasam must be thin enough to pour through a strainer — a thick rasam is sambar. Do not over-reduce.', 'Traditional', NULL, ARRAY['Tomato — 3, chopped','Tamarind — small piece','Black pepper — 1 tsp, crushed','Cumin seeds — 1 tsp','Garlic — 3 cloves','Ghee — 1 tsp','Mustard seeds — ½ tsp','Curry leaves — 8','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Soak tamarind in ½ cup warm water; extract the pulp and strain.','Combine tamarind water with chopped tomato and 2 cups water; bring to a boil.','Crush black pepper and cumin together coarsely; add to the boiling rasam.','Add garlic; simmer 10 minutes until the raw tomato smell disappears.','Temper with ghee, mustard seeds and curry leaves; pour over rasam.','Finish with coriander. Rasam should be very thin and peppery — not thick.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 80, 3, 14, 2, 2, 1.2, 35, 0, 450, true),
  (447, 'Kollu Rasam', 'Tamil', 'south_indian', 'veg', false, 'dal', NULL, '10 min (plus overnight soak)', '30 min', 'Kollu Rasam is Tamil cuisine''s medicinal soup — horse gram (kollu) is uniquely thermogenic among Indian pulses, traditionally prescribed in Siddha medicine for weight management, kidney stones and respiratory conditions. In Tamil Nadu, it is eaten every week in winter.', 'Use the horse gram cooking water — it carries the rasam''s characteristic tannic depth that water cannot replicate.', 'Traditional', NULL, ARRAY['Horse gram (kollu) — ¼ cup, boiled and water reserved','Tamarind — small piece','Tomato — 2, chopped','Black pepper — 1 tsp','Cumin seeds — 1 tsp','Garlic — 3 cloves','Ghee — 1 tsp','Mustard seeds — ½ tsp','Curry leaves — 8','Salt to taste']::text[], ARRAY['Boil horse gram until tender; strain and reserve the cooking water.','Prepare tamarind extract; combine with tomato and the horse gram water.','Add black pepper, cumin and crushed garlic; bring to a boil. Simmer 8 minutes.','Temper with ghee, mustard seeds and curry leaves; pour over the rasam.','Finish with horse gram pieces; simmer 2 minutes. Serve piping hot.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 100, 5, 14, 2, 3, 2, 45, 0, 480, true),
  (448, 'Mulligatawny Soup', 'Tamil', 'south_indian', 'vegan', false, 'soup', NULL, '10 min', '25 min', 'Mulligatawny Soup is a dish with a dual identity — born in colonial Madras as a British adaptation of Tamil pepper water (milagu tannir), it evolved into a rich, coconut-based meal in its own right. The name itself is a corruption of milagu tannir — pepper water.', 'Blend raw rather than cooked — this produces a creamier soup without the slightly gluey texture of cooked-then-blended lentils.', 'Traditional', NULL, ARRAY['Red lentils — ½ cup','Onion — 1 medium, chopped','Tomato — 2, chopped','Coconut milk — ¼ cup','Ginger — 1 inch, grated','Garlic — 3 cloves','Curry powder — 1 tsp','Turmeric — ¼ tsp','Coconut oil — 1 tbsp','Salt to taste']::text[], ARRAY['Blend red lentils with onion, tomato, coconut milk, ginger, garlic and curry powder using a little water.','Heat coconut oil; pour in the blended mixture.','Simmer 20 minutes until the soup is thick and fragrant.','Add turmeric and salt; adjust consistency with water.','Serve hot in bowls with a swirl of coconut milk.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 160, 7, 22, 5, 4, 2.2, 45, 0, 420, true),
  (449, 'Tomato Shorba', 'Mughal', 'north_indian', 'veg', false, 'soup', NULL, '10 min', '25 min', 'Tomato Shorba is a Mughal-era soup, refined in the kitchens of Lucknow and Hyderabad''s nawabs. The spice profile — cinnamon, cardamom and black pepper rather than chilli — reflects the Persian influence that characterises high Mughal cooking.', 'Use overripe tomatoes for maximum sweetness; under-ripe tomatoes make the shorba sour and thin.', 'Traditional', NULL, ARRAY['Tomato — 4, blanched and pureed','Onion — 1 small, chopped','Ginger — ½ inch, grated','Cinnamon — 1 inch','Cardamom — 2 pods','Black pepper — ¼ tsp','Fresh cream — 1 tbsp','Oil — 1 tsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Blanch tomatoes in hot water for 2 minutes; peel and blend to a smooth puree.','Heat oil; add cinnamon and cardamom; sauté 30 seconds.','Add onion and ginger; cook until soft but not coloured.','Add tomato puree; simmer 15 minutes on low heat until the raw smell disappears.','Add black pepper and salt; add cream and stir.','Garnish with coriander and serve hot in bowls.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 90, 2, 14, 3, 2, 1, 35, 0.1, 420, true),
  (450, 'Dal Shorba', 'Mughal', 'north_indian', 'vegan', false, 'soup', NULL, '10 min', '25 min', 'Dal Shorba is Mughal court cuisine''s refined lentil soup — the word shorba comes from Arabic for broth. Where peasant dal is thick and filling, Mughal shorba is velvety and delicate, finished with aromatic whole spices that perfume rather than overpower.', 'Strain the shorba after blending for a silky texture worthy of the Mughal table.', 'Traditional', NULL, ARRAY['Red lentils (masoor dal) — ½ cup','Onion — 1, chopped','Tomato — 1, chopped','Ginger-garlic paste — 1 tsp','Cumin seeds — ½ tsp','Bay leaf — 1','Garam masala — ¼ tsp','Lemon juice — 1 tbsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Bring 1.5 L water to boil; add red lentils, onion, tomato, ginger-garlic paste, bay leaf and cumin.','Simmer 20 minutes until dal is fully cooked and soft.','Blend smooth using a hand blender; strain if desired.','Return to heat; season with garam masala, lemon juice and salt.','Serve in cups; drizzle fresh cream if desired. Garnish with coriander.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 140, 8, 20, 4, 4, 2.5, 40, 0, 450, true),
  (451, 'Moong Dal Soup', 'Pan-Indian', 'pan_indian', 'veg', true, 'soup', NULL, '5 min', '20 min', 'Moong Dal Soup is India''s most healing food — the first thing cooked for the sick, the elderly and new mothers across every region. Yellow moong dal is considered the most easily digestible pulse in Ayurveda, and its gentle warmth is understood as restorative rather than merely nourishing.', 'Do not fully blend; a half-smooth consistency gives it body without becoming too heavy.', 'Traditional', NULL, ARRAY['Yellow moong dal — ½ cup','Ginger — ½ inch, grated','Cumin seeds — ½ tsp','Turmeric — ¼ tsp','Lemon juice — 1 tbsp','Ghee — 1 tsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Wash moong dal; pressure cook or simmer with water and turmeric until very soft.','Heat ghee in a small pan; add cumin seeds; let them splutter.','Pour ghee tempering over the dal; add ginger.','Add lemon juice; season with salt.','Blend partially for a half-smooth texture; thin with water if needed.','Garnish with coriander and serve in a bowl.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 130, 8, 18, 3, 4, 1.8, 35, 0, 400, true),
  (452, 'Drumstick Soup', 'South Indian', 'south_indian', 'vegan', true, 'soup', NULL, '10 min', '25 min', 'Drumstick Soup is South India''s healing broth — moringa drumsticks are among the most nutrient-dense vegetables on earth, containing calcium, iron and all essential amino acids. This light soup is prescribed in South Indian households for recovery, lactation and as a general winter tonic.', 'Extract maximum flavour by boiling drumstick pieces until they are completely soft and scrape the inside flesh into the broth.', 'Traditional', NULL, ARRAY['Drumstick — 4 pieces','Toor dal — 2 tbsp','Tomato — 2, chopped','Ginger — ½ inch','Cumin seeds — ½ tsp','Black pepper — ¼ tsp, crushed','Turmeric — ¼ tsp','Coriander leaves — 2 tbsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Boil drumstick pieces with toor dal, tomato and turmeric until very soft.','Blend or mash; strain to extract a smooth, thin broth.','Heat oil; add cumin seeds, black pepper and garlic; sauté briefly.','Add drumstick broth; bring to a simmer. Season with salt.','Garnish with coriander and serve hot in cups.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 80, 3, 12, 2, 3, 1.5, 50, 0, 400, true),
  (453, 'Palak Soup', 'Pan-Indian', 'pan_indian', 'veg', false, 'soup', NULL, '10 min', '15 min', 'Palak Soup is a hospital kitchen staple that deserves better — when made with fresh spinach and a restrained hand on the cream, it is vibrant green, velvety and deeply nourishing. The blanching and immediate cooling is what preserves the colour.', 'Use the cold-water shock after blanching — this is the only step that keeps the soup brilliantly green rather than olive-drab.', 'Traditional', NULL, ARRAY['Spinach (palak) — 2 cups, blanched','Onion — 1 small, chopped','Garlic — 3 cloves','Ginger — ½ inch, grated','Fresh cream — 1 tbsp','Butter — 1 tsp','Black pepper — ¼ tsp','Nutmeg — a pinch','Salt to taste']::text[], ARRAY['Blanch spinach leaves in hot water for 1 minute; drain and transfer immediately to cold water. Drain again.','Blend blanched spinach with garlic and ginger until completely smooth.','Heat butter; sauté onion until soft. Add spinach puree and simmer 5 minutes.','Add fresh cream, black pepper and nutmeg; stir and adjust salt.','Serve hot in bowls — do not reheat after adding cream.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 90, 5, 10, 4, 3, 3, 140, 0.2, 400, true),
  (454, 'Kaddu Shorba', 'Rajasthani', 'north_indian', 'veg', false, 'soup', NULL, '10 min', '20 min', 'Kaddu Shorba is Rajasthan''s warming soup — a velvety pumpkin broth with a touch of jaggery or honey that echoes the Rajasthani preference for sweet-spice balance. Pumpkin (kaddu) is one of the few vegetables that grew reliably in the desert, making it a cornerstone of Rajasthani cooking.', 'Roasting the pumpkin before blending adds a smoky depth; boiling gives a brighter, fresher flavour.', 'Traditional', NULL, ARRAY['Pumpkin (kaddu) — 2 cups, cubed','Onion — 1 small, chopped','Ginger — ½ inch, grated','Cinnamon — ½ inch','Cardamom — 1 pod','Ghee — 1 tsp','Honey — ½ tsp','Fresh cream — 1 tbsp','Salt to taste']::text[], ARRAY['Blend cooked pumpkin with onion, ginger and a little water until smooth.','Heat ghee; add cinnamon and cardamom; sauté 30 seconds.','Add the pumpkin puree; simmer 10 minutes.','Add salt and honey; stir in cream.','Serve warm in bowls; the shorba should be lightly sweet and subtly spiced.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 250, 100, 2, 16, 4, 3, 1, 45, 0.1, 400, true),
  (455, 'Majjige Huli', 'Karnataka', 'south_indian', 'veg', true, 'curry', NULL, '10 min', '20 min', 'Majjige Huli is Karnataka''s cooling curd curry — a gentle, coconut-thickened buttermilk dish that is the vegetarian counterpart to Kerala''s mor kuzhambu. In coastal Karnataka it is served as a digestive at the end of a meal, its cooling properties prized in the hot coastal climate.', 'Never boil once the curd is added — high heat will curdle it. Keep the flame on its lowest setting.', 'Traditional', NULL, ARRAY['Curd (majjige) — 1 cup','Ash gourd or cucumber — 1 cup, cubed','Coconut — 3 tbsp, grated','Green chilli — 2','Ginger — ½ inch','Cumin seeds — 1 tsp','Turmeric — ¼ tsp','Coconut oil — 1 tsp','Mustard seeds — ½ tsp','Curry leaves — 8','Salt to taste']::text[], ARRAY['Blend coconut, green chilli, ginger and cumin to a fine paste with a little water.','Boil ash gourd or cucumber in a little water with turmeric until just tender.','Whisk the coconut paste into the curd until smooth; add to the cooked vegetable.','Heat coconut oil; add mustard seeds and curry leaves; pour over the curry.','Warm gently — do not boil the curd base. Season and serve with rice.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 180, 120, 5, 14, 5, 3, 0.8, 140, 0.3, 400, true),
  (456, 'Panchphala Bowl', 'Ayurvedic', 'pan_indian', 'veg', true, 'fruit', NULL, '10 min', '0 min', 'Panchphala (five-fruit) bowl is an Ayurvedic tradition of combining fruits that collectively balance all three doshas. Each of the five fruits contributes a distinct rasa (taste): sweet, sour, astringent — making the bowl nutritionally and energetically complete.', 'Use seasonal, fully ripe fruit; unripe fruit is harder to digest and energetically heavy in Ayurvedic tradition.', 'Traditional', NULL, ARRAY['Apple — ½, diced','Banana — 1 small, sliced','Papaya — ½ cup, cubed','Pomegranate seeds — ¼ cup','Grapes — ½ cup','Honey — 1 tsp','Cardamom powder — ¼ tsp','Lemon juice — ½ tsp']::text[], ARRAY['Wash and peel all five fruits; dice apple, banana and papaya into even cubes.','Combine all fruits in a wide bowl.','Add honey, cardamom powder and lemon juice.','Toss gently and serve within 20 minutes.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 250, 160, 3, 36, 2, 5, 0.8, 40, 0, 10, true),
  (457, 'Papaya-Pomegranate Chaat', 'Pan-Indian', 'pan_indian', 'veg', true, 'fruit', NULL, '8 min', '0 min', 'Papaya-Pomegranate Chaat is a modern Indian fruit bowl rooted in the chaat tradition — tart, sweet, peppery and fresh in a single spoonful. Papaya is a Pitta-reducing fruit in Ayurveda; pomegranate is its blood-building complement. Together they make a digestive powerhouse.', 'Use deep-orange, ripe papaya — pale or greenish papaya lacks sweetness and stays starchy.', 'Traditional', NULL, ARRAY['Ripe papaya — 1 cup, cubed','Pomegranate seeds — ¼ cup','Mint leaves — 8','Chaat masala — ¼ tsp','Black salt — a pinch','Lemon juice — 1 tsp','Honey — ½ tsp']::text[], ARRAY['Cube and combine papaya and pomegranate seeds in a bowl.','Tear mint leaves and add.','Mix together chaat masala, black salt, lemon juice and honey in a small bowl.','Pour dressing over fruit; toss gently.','Serve within 20 minutes — papaya softens quickly once dressed.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 200, 120, 2, 28, 1, 4, 0.6, 35, 0, 150, true),
  (458, 'Mango-Coconut Salad', 'Kerala', 'south_indian', 'vegan', true, 'salad', NULL, '10 min', '0 min', 'This Kerala-inspired pairing of ripe mango and fresh coconut is rooted in the Sadya tradition of serving fresh fruit with grated coconut as a palate refresher. The addition of cardamom is a Kerala signature — the spice grows wild in the Western Ghats that border the state.', 'Use Alphonso or Kerala''s local Muvandan mango; semi-ripe mangoes carry the best balance of sweet and tart.', 'Traditional', NULL, ARRAY['Ripe mango — 1 large, cubed','Fresh grated coconut — 3 tbsp','Mint leaves — 8','Lime juice — 1 tbsp','Jaggery — 1 tsp','Cardamom powder — ¼ tsp']::text[], ARRAY['Peel and cube mango; combine with grated coconut and torn mint leaves.','Squeeze lime juice over; drizzle jaggery (softened or powdered).','Add cardamom powder; toss gently.','Serve immediately — best enjoyed fresh when mango is at room temperature.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 200, 180, 2, 34, 6, 4, 0.8, 30, 0, 10, true),
  (459, 'Watermelon-Mint Bowl', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', NULL, '5 min', '0 min', 'Watermelon-Mint Bowl is India''s summer answer — the combination of watermelon, lime and black salt is found in street stalls from Delhi to Mumbai as a cooling tonic on hot afternoons. Black salt (kala namak) is what separates this from a plain fruit bowl.', 'Serve immediately after dressing — watermelon releases a lot of juice in minutes and the bowl becomes a diluted soup.', 'Traditional', NULL, ARRAY['Watermelon — 2 cups, cubed','Mint leaves — 10','Lime juice — 1 tbsp','Black salt — a pinch','Chaat masala — ¼ tsp']::text[], ARRAY['Cube watermelon into bite-sized pieces; remove seeds.','Tear mint leaves and add to watermelon.','Squeeze lime juice over; add black salt and chaat masala.','Toss gently and serve immediately — watermelon releases water quickly.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 300, 90, 1, 20, 0, 1, 0.6, 25, 0, 180, true),
  (460, 'Banana-Date-Walnut Bowl', 'Ayurvedic', 'pan_indian', 'veg', true, 'fruit', NULL, '5 min', '0 min', 'This no-cook bowl draws on Ayurveda''s tradition of combining naturally sweet, grounding foods for morning nourishment. Banana and dates provide quick energy; walnuts add omega-3 fats that classical texts associate with brain clarity.', 'Eat within 20 minutes of preparation — banana browns quickly and dates absorb moisture from the bowl.', 'Traditional', NULL, ARRAY['Banana — 2, sliced','Dates — 4, pitted and chopped','Walnuts — 2 tbsp, roughly chopped','Honey — 1 tsp','Cinnamon powder — ¼ tsp','Cardamom powder — ¼ tsp']::text[], ARRAY['Slice bananas into a bowl.','Chop dates and roughly crush walnuts.','Add all ingredients to the bowl: honey, cinnamon, cardamom.','Toss gently and serve immediately at room temperature.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 280, 280, 5, 44, 10, 4, 1.5, 60, 0, 10, true),
  (461, 'Amla-Apple Salad', 'Ayurvedic', 'pan_indian', 'veg', true, 'salad', NULL, '10 min', '0 min', 'This Ayurvedic salad pairs the cooling sweetness of apple with the sharp, astringent amla — a combination that balances Pitta and Vata doshas. The ginger adds digestive warmth to make it suitable year-round.', 'Do not prepare ahead; amla and apple both discolour and lose vitamin C quickly once cut.', 'Traditional', NULL, ARRAY['Amla (Indian gooseberry) — 2, grated','Apple — 1, diced','Ginger — ¼ inch, finely grated','Honey — 1 tsp','Lemon juice — ½ tsp','Black salt — a pinch','Coriander leaves — 1 tbsp']::text[], ARRAY['Grate amla finely (discard the central pit).','Dice apple and toss immediately with lemon juice to prevent browning.','Combine amla, apple, grated ginger, honey and black salt in a bowl.','Garnish with coriander leaves and serve within 10 minutes.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 200, 100, 1, 22, 1, 4, 0.7, 30, 0, 120, true),
  (462, 'Guava Chaat', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', NULL, '5 min', '0 min', 'Guava Chaat celebrates one of India''s most beloved winter fruits — eaten with spices since ancient times as a digestive after meals. The combination of sweet-astringent guava with tangy chaat masala and chilli is a quintessential Indian sensory experience that balances all six tastes.', 'Use slightly under-ripe guava for chaat — fully ripe guava is too soft and sweet to hold the spices.', 'Traditional', NULL, ARRAY['Guava — 2, cubed','Red chilli powder — ¼ tsp','Black salt — ¼ tsp','Cumin powder — ¼ tsp','Lemon juice — 1 tbsp','Mint leaves — 6','Chaat masala — ¼ tsp']::text[], ARRAY['Wash and cube guava into bite-sized pieces.','Toss with red chilli powder, black salt, cumin powder and chaat masala.','Squeeze lemon juice over; add torn mint leaves.','Toss again and serve immediately.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 200, 100, 2, 22, 1, 6, 0.6, 35, 0, 350, true),
  (463, 'Custard Apple Bowl', 'South Indian', 'pan_indian', 'veg', true, 'fruit', NULL, '10 min', '0 min', 'Custard apple (sitaphal) is South India''s autumn gift — intensely sweet, fragrant and grainy, available only for a few weeks. This simple bowl celebrates it at its peak, paired with banana and coconut milk in a South Indian tradition of combining local fruits with coconut.', 'Taste before adding honey — a fully ripe custard apple is intensely sweet and may need none.', 'Traditional', NULL, ARRAY['Custard apple (sitaphal) — 2, pulp extracted','Ripe banana — 1, sliced','Honey — 1 tsp','Cardamom powder — ¼ tsp','Coconut milk — 2 tbsp']::text[], ARRAY['Scoop out custard apple pulp, removing all seeds.','Slice banana and toss with lemon juice to prevent browning.','Combine custard apple pulp, banana slices, coconut milk, honey and cardamom.','Stir gently — custard apple is fragile.','Serve immediately or chill briefly.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 220, 160, 3, 34, 2, 4, 1, 45, 0, 15, true),
  (464, 'Chikoo-Coconut Bowl', 'Pan-Indian', 'pan_indian', 'veg', true, 'fruit', NULL, '8 min', '0 min', 'Chikoo (sapodilla) is one of India''s most underappreciated fruits — naturally caramel-sweet, with a grainy texture similar to a ripe pear. This bowl celebrates it simply with coconut and cardamom, a combination that appears in South Indian fruit preparations.', 'Use fully ripe chikoo — it should feel soft when pressed gently; under-ripe chikoo is gritty and tasteless.', 'Traditional', NULL, ARRAY['Chikoo (sapodilla) — 3, peeled and cubed','Fresh grated coconut — 2 tbsp','Cardamom powder — ¼ tsp','Honey — 1 tsp','Lime juice — ½ tsp','Raisins — 1 tbsp']::text[], ARRAY['Peel and cube chikoo; combine with grated coconut and raisins.','Add cardamom powder, honey and lime juice.','Toss gently — chikoo is soft and breaks apart easily.','Serve immediately or chill briefly.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 220, 180, 2, 36, 4, 4, 1.2, 45, 0, 15, true),
  (465, 'Mixed Berry with Tulsi', 'Ayurvedic', 'pan_indian', 'veg', true, 'fruit', NULL, '8 min', '0 min', 'This berry bowl bridges Ayurvedic and modern nutrition — tulsi (holy basil) is an adaptogen that reduces cortisol, while the anthocyanin-rich berries fight oxidative stress. Black pepper is added in Ayurveda to enhance absorption of the herb''s volatile oils.', 'Tear tulsi rather than chopping — a blade oxidises the essential oils that carry its adaptogenic benefit.', 'Traditional', NULL, ARRAY['Strawberry — ½ cup, halved','Blueberries — ¼ cup','Jamun (black plum) — ¼ cup','Tulsi leaves — 5, finely torn','Honey — 1 tsp','Lemon juice — ½ tsp','Black pepper — a pinch']::text[], ARRAY['Wash and hull strawberries; combine all berries in a wide bowl.','Tear tulsi leaves finely and add to the berries.','Drizzle honey, lemon juice and a pinch of black pepper.','Toss gently and serve within 15 minutes — tulsi wilts quickly.']::text[], ARRAY['breakfast','snack']::text[], 'bowl', 200, 100, 2, 22, 1, 4, 0.7, 30, 0, 8, true),
  (466, 'Kachumber', 'Pan-Indian', 'pan_indian', 'vegan', false, 'salad', NULL, '10 min', '0 min', 'Kachumber is India''s simplest and most universal salad — three diced vegetables, lemon, cumin and coriander. It appears as a side across the entire subcontinent from Punjabi dhabas to Malabari homes. Its genius is its restraint.', 'Dice all vegetables to the same size so every forkful contains all three — uneven cutting means you get one vegetable per bite.', 'Traditional', NULL, ARRAY['Cucumber — 1, finely diced','Tomato — 1, finely diced','Onion — 1 small, finely chopped','Green chilli — 1, finely chopped','Coriander leaves — 3 tbsp','Lemon juice — 1 tbsp','Cumin powder — ¼ tsp','Salt to taste']::text[], ARRAY['Finely dice cucumber, tomato and onion into uniform small cubes.','Add green chilli and coriander; toss together.','Squeeze lemon juice; add cumin powder and salt.','Toss and serve immediately — kachumber is a fresh salad and deteriorates within an hour.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 60, 2, 10, 2, 3, 0.8, 35, 0, 320, true),
  (467, 'Sprout Chaat Salad', 'Pan-Indian', 'pan_indian', 'vegan', false, 'salad', NULL, '10 min', '0 min', 'Sprout Chaat Salad combines two Indian traditions — the nutritional wisdom of sprouting pulses (which multiplies their protein and reduces anti-nutrients) and the flavour tradition of chaat. Every gram of sprouted moong or chana is significantly more bioavailable than the unsprouted pulse.', 'Sprout at home for best nutrition: soak 8 hours, rinse and keep wrapped in a damp cloth for 12–24 hours.', 'Traditional', NULL, ARRAY['Mixed sprouts (moong, chana) — 1 cup','Tomato — 1, diced','Cucumber — ½, diced','Onion — 1 small, finely chopped','Green chilli — 1, finely chopped','Chaat masala — ½ tsp','Lemon juice — 2 tbsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Combine mixed sprouts, tomato, cucumber, onion and green chilli in a bowl.','Add chaat masala, lemon juice, coriander and salt.','Toss well; taste and adjust seasoning.','Serve immediately — sprout salads wilt within 30 minutes of dressing.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 160, 10, 22, 4, 6, 2.5, 60, 0, 400, true),
  (468, 'Beet-Peanut Salad', 'Maharashtrian', 'west_indian', 'vegan', false, 'salad', NULL, '10 min', '8 min', 'Beet-Peanut Salad is a Maharashtrian koshimbir — a class of quick, tempered salads that appear at every Marathi meal as a cooling counterpoint to spicy main dishes. The earthiness of beetroot and crunch of peanuts make it one of the most satisfying in this family of salads.', 'Grate beetroot on the largest grater holes for texture; finely grated beetroot releases too much moisture and goes mushy.', 'Traditional', NULL, ARRAY['Beetroot — 2 medium, grated','Peanuts — ¼ cup, roasted','Coconut — 2 tbsp, grated','Green chilli — 1, finely chopped','Lemon juice — 1 tbsp','Coriander leaves — 2 tbsp','Mustard seeds — ½ tsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Grate beetroot; heat oil with mustard seeds until they pop.','Add curry leaves and green chilli; sauté 30 seconds.','Add grated beetroot and turmeric; toss and cook 3 minutes.','Remove from heat; add grated coconut, roasted peanuts, lemon juice and coriander.','Toss well and serve at room temperature.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 120, 160, 7, 20, 7, 5, 1.5, 45, 0, 300, true),
  (469, 'Carrot-Ginger-Sesame Salad', 'Pan-Indian', 'pan_indian', 'veg', false, 'salad', NULL, '10 min', '0 min', 'Carrot-Ginger-Sesame Salad is a pan-Indian recipe drawing on the tradition of grated vegetable salads (koshimbir, pachadi) found across the subcontinent. Sesame oil is an unusual addition that bridges the Indian and East Asian pantry — it works especially well with ginger and carrot.', 'Grate on the coarser setting for texture; finely grated carrot releases water and makes the dressing thin.', 'Traditional', NULL, ARRAY['Carrot — 2 large, grated','Sesame seeds — 1 tbsp, roasted','Ginger — ½ inch, finely grated','Lemon juice — 2 tbsp','Honey — ½ tsp','Sesame oil — 1 tsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Grate carrots into a wide bowl; add grated ginger.','In a small bowl whisk lemon juice, sesame oil and honey.','Pour dressing over carrots; add roasted sesame seeds and coriander.','Toss well and serve immediately or chill 10 minutes.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 100, 100, 3, 14, 4, 4, 1.2, 80, 0, 250, true),
  (470, 'Cucumber-Yogurt Raita', 'Pan-Indian', 'pan_indian', 'veg', true, 'dairy', NULL, '10 min', '0 min', 'Cucumber Yogurt Raita is India''s universal cooling accompaniment — served at every meal from Kashmir to Kerala as a digestive buffer against spiced food. The act of squeezing cucumber before adding is essential; it prevents a watery raita that cannot hold its own.', 'Squeeze the cucumber very well — a wet raita dilutes the curd and loses its creamy body.', 'Traditional', NULL, ARRAY['Cucumber — 1, grated','Curd — 1 cup','Cumin powder — ½ tsp','Green chilli — 1, finely chopped','Mint leaves — 8','Coriander leaves — 2 tbsp','Black salt — ¼ tsp','Salt to taste']::text[], ARRAY['Grate cucumber; squeeze out excess water firmly using your hands.','Beat curd until smooth.','Add squeezed cucumber, cumin powder, green chilli, mint, coriander and black salt.','Stir well; taste and adjust salt. Serve chilled.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 100, 5, 10, 4, 1, 0.5, 180, 0.4, 400, true),
  (471, 'Raw Papaya Salad', 'Assamese', 'northeast_indian', 'veg', false, 'salad', NULL, '15 min', '0 min', 'Raw papaya salad is a light, enzyme-rich dish popular across Assam and North-East India, eaten as a digestive side. The unripe papaya contains papain which aids protein digestion.', 'Squeeze grated papaya in your fist to remove excess moisture before dressing so it stays crisp.', 'Traditional', NULL, ARRAY['Raw papaya — 1 cup, grated','Carrot — 1 small, grated','Green chilli — 2, finely sliced','Lemon juice — 2 tbsp','Peanuts — 2 tbsp, roasted','Coriander leaves — 2 tbsp','Honey — ½ tsp','Salt to taste']::text[], ARRAY['Grate raw papaya and carrot into a wide bowl.','Add green chilli, coriander and roasted peanuts.','Squeeze lemon juice, drizzle honey and season with salt.','Toss and rest 5 minutes before serving to let flavours meld.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 120, 80, 2, 14, 2, 3, 0.8, 40, 0, 250, true),
  (472, 'Mooli Salad', 'Punjabi', 'north_indian', 'vegan', false, 'salad', NULL, '10 min', '0 min', 'Mooli Salad is Punjab''s simplest digestive side — raw white radish with its own leaves, dressed only with lemon, mustard oil and salt. In North India this salad accompanies every winter meal; the mild bitterness of the leaves and the peppery crunch of the radish cut through rich dals and curries.', 'Use the leaves — they contain more iron than the radish and are at their best when young and fresh.', 'Traditional', NULL, ARRAY['White radish (mooli) — 2, grated','Mooli leaves — ½ cup, finely chopped','Green chilli — 1, finely chopped','Lemon juice — 1 tbsp','Coriander leaves — 2 tbsp','Mustard oil — ½ tsp','Salt to taste']::text[], ARRAY['Grate mooli and the mooli leaves finely.','Add green chilli, coriander, lemon juice and a few drops of mustard oil.','Season with salt; toss well.','Serve immediately as a side salad — mooli leaves wilt quickly.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 100, 60, 2, 10, 2, 3, 1, 60, 0, 300, true),
  (473, 'Corn-Capsicum Chaat', 'Pan-Indian', 'pan_indian', 'vegan', false, 'snack', NULL, '10 min', '5 min', 'Corn Capsicum Chaat is India''s street food tradition applied to sweet corn — a quick toss of boiled corn with raw vegetables, chaat masala and lemon that appears on roadside carts from Delhi to Bengaluru. Simple, bright and satisfying at any hour.', 'Use boiled corn rather than canned for best texture; canned corn is too soft for chaat.', 'Traditional', NULL, ARRAY['Sweet corn — 1 cup, boiled','Capsicum — ½, finely diced','Onion — 1 small, finely chopped','Tomato — 1 small, diced','Chaat masala — ½ tsp','Lemon juice — 1 tbsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Boil sweet corn until just done; drain and cool slightly.','Combine corn, capsicum, onion and tomato in a bowl.','Add chaat masala, lemon juice, salt and coriander; toss well.','Serve immediately — best eaten within 30 minutes.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 150, 160, 5, 28, 4, 4, 1, 25, 0, 350, true),
  (474, 'Cabbage-Coconut Poriyal', 'Tamil', 'south_indian', 'vegan', true, 'side', NULL, '10 min', '12 min', 'Cabbage-Coconut Poriyal is Tamil Nadu''s quintessential dry side dish — a lightly cooked vegetable poriyal seasoned with mustard seeds and finished with fresh coconut. Every Tamil household has a repertoire of poriyals; this is often the first one taught to new cooks.', 'Cook on high heat and keep stirring — slow cooking makes cabbage watery and loses the fresh texture.', 'Traditional', NULL, ARRAY['Cabbage — 2 cups, shredded','Grated fresh coconut — 3 tbsp','Green chilli — 2, slit','Mustard seeds — ½ tsp','Urad dal — ½ tsp','Curry leaves — 8','Turmeric — ¼ tsp','Oil — 1 tsp','Salt to taste']::text[], ARRAY['Heat oil; add mustard seeds, urad dal, curry leaves and green chilli; let them splutter.','Add shredded cabbage and turmeric; stir-fry on high heat 3–4 minutes.','Reduce heat; cover and cook 5 minutes until cabbage is just tender.','Add fresh grated coconut; toss well. Season with salt.','Serve hot or at room temperature.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 100, 100, 3, 14, 4, 4, 0.8, 50, 0, 300, true),
  (475, 'Nadru Lotus Root Salad', 'Kashmiri', 'north_indian', 'vegan', false, 'salad', NULL, '15 min', '0 min', 'Nadru (lotus root) is Kashmir''s most prized vegetable — a crunchy, starchy rhizome harvested from the Dal Lake by houseboat communities. In this salad form it appears light and cooling, far removed from its more famous fried avatar (nadru chips).', 'Boil lotus root in water with a teaspoon of vinegar to keep it from turning grey.', 'Traditional', NULL, ARRAY['Lotus root (nadru) — 1 cup, thinly sliced and boiled','Cucumber — ½, diced','Pomegranate seeds — 2 tbsp','Lemon juice — 2 tbsp','Fennel seeds — ¼ tsp','Black salt — ¼ tsp','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Thinly slice boiled lotus root; combine with diced cucumber and pomegranate seeds.','Whisk lemon juice, fennel seeds, black salt and regular salt in a small bowl.','Pour dressing over the salad; toss gently.','Garnish with coriander and serve immediately or chill 10 minutes.']::text[], ARRAY['lunch','dinner','snack']::text[], 'bowl', 130, 120, 3, 22, 3, 4, 1.2, 40, 0, 350, true),
  (476, 'Oats Upma with Mixed Vegetables', 'South Indian', 'south_indian', 'vegan', false, 'main', '2', '10 min', '15 min', 'Rolled oats tempered with mustard seeds and cooked with colourful seasonal vegetables — a fibre-rich, iron-boosting twist on the classic upma.', 'Dry-roast the oats for 2 minutes before cooking; it prevents the upma turning mushy and deepens the nutty flavour.', 'Therapeutic', ARRAY['Vegan','Nut-Free','Iron-Rich','High-Fibre','Cholesterol-Friendly']::text[], ARRAY['Rolled oats — 1 cup','Carrot, diced small — 1','Peas, fresh or frozen — ¼ cup','Onion, finely chopped — 1','Green chilli, slit — 1','Ginger, grated — 1 tsp','Mustard seeds — ½ tsp','Urad dal — 1 tsp','Curry leaves — 8','Turmeric — ¼ tsp','Lemon juice — 2 tsp','Fresh coriander — for garnish','Oil — 1 tsp','Salt — to taste']::text[], ARRAY['Dry-roast the oats in a non-stick pan over medium heat for 2 minutes until lightly golden; set aside.','Heat oil in the same pan; add mustard seeds and let them splutter.','Add urad dal and curry leaves; fry 30 seconds.','Add onion, green chilli, and ginger; cook until the onion softens, about 3 minutes.','Add carrot and peas; stir and cook 3 minutes.','Sprinkle in turmeric, then pour in 1½ cups water and bring to a simmer.','Stir in the roasted oats; cook, stirring frequently, 4–5 minutes until the upma comes together.','Finish with lemon juice, season with salt, garnish with coriander, and serve hot.']::text[], ARRAY['breakfast','dinner']::text[], 'bowl', 220, 220, 7.5, 38, 5.5, 5.2, 2.8, 45, 0, 320, false),
  (477, 'Overnight Oats with Chia and Fresh Berries', 'Indian Fusion', 'pan_indian', 'veg', true, 'main', '1', '5 min + overnight', 'No cook', 'Rolled oats soaked overnight with protein-rich chia seeds, yogurt, and fresh berries — a no-cook breakfast built for soluble fibre and omega-3s.', 'Swap dairy yogurt for coconut yogurt to keep it fully vegan; it works equally well and adds a subtle tropical note.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','Iron-Rich','High-Fibre','Cholesterol-Friendly','Calcium-Rich']::text[], ARRAY['Rolled oats — ½ cup','Chia seeds — 1 tbsp','Low-fat yogurt — ½ cup','Milk (dairy or plant-based) — ¼ cup','Mixed berries (strawberry, blueberry, raspberry) — ½ cup','Honey — 1 tsp','Cardamom, ground — a pinch','Pumpkin seeds — 1 tsp (for garnish)']::text[], ARRAY['Combine oats, chia seeds, yogurt, milk, honey, and cardamom in a jar or bowl.','Stir well to break up any clumps of chia seeds.','Cover and refrigerate overnight, or for at least 6 hours.','In the morning, give it a good stir; add a splash of milk if you prefer a looser consistency.','Top with fresh berries and pumpkin seeds; serve chilled.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 280, 9.2, 42, 7.8, 8.5, 3.2, 180, 0.35, 95, false),
  (478, 'Ragi Cheela', 'South Indian', 'south_indian', 'vegan', false, 'main', '2', '10 min', '15 min', 'Thin, crisp finger-millet pancakes spiced with cumin and green chilli — one of the richest plant sources of calcium and iron in Indian cooking.', 'Letting the batter rest 5 minutes after mixing helps the ragi flour hydrate fully, giving you thinner and crisper cheelas.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','Iron-Rich','Calcium-Rich']::text[], ARRAY['Ragi flour (finger millet) — 1 cup','Onion, finely chopped — 1 small','Green chilli, minced — 1','Ginger, grated — ½ tsp','Cumin seeds — ½ tsp','Fresh coriander, chopped — 2 tbsp','Turmeric — ¼ tsp','Salt — to taste','Oil — for cooking','Water — as needed']::text[], ARRAY['In a bowl, combine ragi flour, onion, green chilli, ginger, cumin seeds, coriander, turmeric, and salt.','Add water gradually, whisking to form a smooth, pourable batter (consistency of crêpe batter).','Rest the batter 5 minutes.','Heat a non-stick tawa over medium-high heat; brush lightly with oil.','Pour a ladleful of batter and spread in a thin circle; drizzle a few drops of oil around the edges.','Cook 2–3 minutes until the edges lift; flip and cook 1 minute more.','Serve hot with coconut chutney or yogurt.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 190, 6.8, 32, 4.5, 3.8, 3.6, 195, 0, 265, false),
  (479, 'Oats-Moong Dal Chilla', 'North Indian', 'north_indian', 'vegan', false, 'main', '2', '15 min + 30 min soak', '15 min', 'Savoury pancakes made from soaked split green moong and rolled oats — high in plant protein, soluble fibre, and iron, with a satisfying bite.', 'For best texture, grind the batter to a coarse consistency rather than silky-smooth; the oats give it pleasant body.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Moong dal (split green gram), soaked 30 min — ½ cup','Rolled oats — ¼ cup','Green chilli — 1','Ginger, 1-inch piece','Onion, finely chopped — ½','Cumin seeds — ½ tsp','Fresh coriander, chopped — 2 tbsp','Turmeric — ¼ tsp','Salt — to taste','Oil — for cooking']::text[], ARRAY['Drain the soaked moong dal; add to a blender with oats, green chilli, ginger, and ¼ cup water.','Blend to a coarse, pourable batter; transfer to a bowl.','Mix in onion, cumin seeds, coriander, turmeric, and salt.','Heat a non-stick tawa; brush with oil.','Pour a ladleful of batter and spread to a 15 cm circle.','Cook 2–3 minutes until golden underneath; flip and cook 1–2 minutes.','Serve with green chutney.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 210, 9.5, 34, 4.2, 5.5, 2.4, 52, 0, 290, false),
  (480, 'Dalia Upma', 'North Indian', 'north_indian', 'veg', false, 'main', '2', '5 min', '20 min', 'Broken wheat (dalia) cooked with aromatic tempering and mixed vegetables — a low-glycaemic, high-fibre breakfast that sustains energy throughout the morning.', 'Toast the dalia in ghee for 2 minutes before adding water; it deepens the nutty flavour and prevents clumping.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','High-Fibre','Iron-Rich','Cholesterol-Friendly']::text[], ARRAY['Broken wheat (dalia) — ½ cup','Mixed vegetables (carrot, peas, beans), chopped — ¾ cup','Onion, chopped — 1','Green chilli — 1','Ginger, grated — 1 tsp','Ghee — 1 tsp','Mustard seeds — ½ tsp','Urad dal — 1 tsp','Curry leaves — 8','Turmeric — ¼ tsp','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Heat ghee in a pressure cooker or saucepan; add mustard seeds and let them pop.','Add urad dal and curry leaves; fry 30 seconds.','Add onion, green chilli, and ginger; cook until softened.','Add the mixed vegetables and turmeric; stir 2 minutes.','Add the broken wheat and toast, stirring, for 2 minutes.','Pour in 1¼ cups water; season with salt.','Cover and cook until the water is absorbed and dalia is tender, about 8 minutes (or 2 whistles in a pressure cooker).','Fluff with a fork, garnish with coriander, and serve hot.']::text[], ARRAY['breakfast','dinner']::text[], 'bowl', 220, 230, 7.2, 40, 5.8, 5, 2.2, 38, 0, 345, false),
  (481, 'Ragi Porridge', 'South Indian', 'south_indian', 'veg', true, 'main', '1', '2 min', '8 min', 'Finger millet porridge sweetened lightly with jaggery and flavoured with cardamom — a deeply nourishing breakfast with exceptional calcium content.', 'Whisk the ragi flour into cold milk first before heating; adding it to hot liquid causes lumps.', 'Therapeutic', ARRAY['Vegetarian','Gluten-Free','Nut-Free','Calcium-Rich','Iron-Rich']::text[], ARRAY['Ragi flour (finger millet) — 3 tbsp','Milk (dairy or plant-based) — 1½ cups','Jaggery, grated — 1 tbsp','Cardamom, ground — ¼ tsp','A pinch of salt']::text[], ARRAY['Whisk ragi flour into ½ cup cold milk until completely smooth with no lumps.','Pour the remaining 1 cup milk into a saucepan and bring to a gentle simmer.','Slowly pour in the ragi-milk mixture, stirring continuously.','Cook over low heat, stirring, 5–6 minutes until the porridge thickens.','Add jaggery and cardamom; stir until the jaggery dissolves.','Serve warm.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 175, 4.8, 34, 1.8, 2.5, 2.8, 210, 0.2, 85, false),
  (482, 'Ragi Idli', 'South Indian', 'south_indian', 'vegan', true, 'main', '2', '15 min + overnight ferment', '15 min', 'Steamed finger-millet idlis that bring ragi''s exceptional calcium and iron to the classic South Indian breakfast — fluffy, wholesome, and deeply satisfying.', 'Use a ratio of 1:3 ragi to urad dal for the fluffiest texture; full ragi batter tends to yield dense idlis.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','Calcium-Rich','Iron-Rich']::text[], ARRAY['Ragi flour — ¾ cup','Urad dal (split black lentil), soaked 4 h — ¼ cup','Poha (flattened rice), soaked 10 min — 2 tbsp','Salt — to taste','Water — as needed']::text[], ARRAY['Blend the soaked urad dal and poha with a little water to a fluffy, smooth batter.','Mix in the ragi flour; add water to achieve a thick dropping consistency.','Add salt, cover, and ferment overnight in a warm place.','Grease idli moulds; ladle batter into each mould.','Steam in an idli steamer for 10–12 minutes until a skewer comes out clean.','Allow to rest 2 minutes before un-moulding.','Serve hot with coconut chutney and sambar.']::text[], ARRAY['breakfast','dinner']::text[], 'serving', 150, 185, 5.5, 36, 2.2, 3.2, 3.1, 178, 0, 285, false),
  (483, 'Bajra Cheela', 'Rajasthani', 'north_indian', 'vegan', false, 'main', '2', '10 min', '15 min', 'Crisp pearl millet pancakes spiced with ajwain and coriander — a gluten-free, iron-rich breakfast from the heart of Rajasthan.', 'Bajra batter is naturally thicker than wheat batter; add water until it just flows easily off the ladle.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','Iron-Rich','High-Fibre']::text[], ARRAY['Bajra flour (pearl millet) — 1 cup','Onion, finely chopped — 1 small','Green chilli, minced — 1','Ginger, grated — ½ tsp','Ajwain (carom seeds) — ¼ tsp','Fresh coriander, chopped — 2 tbsp','Turmeric — ¼ tsp','Salt — to taste','Oil — for cooking','Water — as needed']::text[], ARRAY['Combine bajra flour, onion, green chilli, ginger, ajwain, coriander, turmeric, and salt in a bowl.','Add water gradually and whisk to a smooth, pourable batter.','Heat a non-stick tawa over medium heat; brush lightly with oil.','Pour a ladleful of batter and spread to a thin circle with the back of the ladle.','Cook 2–3 minutes until the surface looks dry and edges turn golden; drizzle a little oil around the edges.','Flip and cook 1–2 minutes more.','Serve with yogurt and green chutney.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 200, 6.5, 36, 4.8, 4.2, 3, 42, 0, 275, false),
  (484, 'Moong Dal Cheela', 'North Indian', 'north_indian', 'vegan', false, 'main', '2', '10 min + 2 h soak', '15 min', 'Thin, golden savoury pancakes made from blended soaked moong dal — high in folate, plant protein, and iron, with a naturally light texture.', 'Adding a tablespoon of semolina to the batter gives the cheela a slightly crisp edge without thickening it too much.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich']::text[], ARRAY['Moong dal (yellow split), soaked 2 h — ¾ cup','Green chilli — 1','Ginger, 1-inch piece','Cumin seeds — ½ tsp','Onion, finely chopped — ½','Fresh coriander, chopped — 2 tbsp','Turmeric — ¼ tsp','Asafoetida — a pinch','Salt — to taste','Oil — for cooking']::text[], ARRAY['Drain the soaked moong dal; blend with green chilli, ginger, cumin seeds, and 3 tbsp water to a smooth batter.','Stir in onion, coriander, turmeric, asafoetida, and salt.','Heat a non-stick tawa over medium-high heat; brush with oil.','Pour a ladleful of batter and spread to a thin circle.','Cook 2 minutes until the underside is golden; drizzle oil around edges.','Flip and cook 1 minute more.','Serve with mint chutney or sliced cucumber raita.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 195, 10.5, 30, 4.5, 4.8, 2.5, 48, 0, 270, false),
  (485, 'Oats-Moong Dal Dosa', 'South Indian Fusion', 'south_indian', 'vegan', true, 'main', '2', '10 min + 1 h soak', '15 min', 'Lacy, ferment-free dosas from soaked moong dal and rolled oats — ready same-day yet packed with soluble fibre, iron, and protein.', 'The batter is naturally thin; do not add more flour to thicken it — a thin spread on the tawa gives the characteristic lacy, crisp dosa.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre','Cholesterol-Friendly']::text[], ARRAY['Rolled oats — ½ cup','Moong dal (yellow split), soaked 1 h — ½ cup','Green chilli — 1','Ginger, 1-inch piece','Cumin seeds — ½ tsp','Curry leaves — 6','Salt — to taste','Oil — for cooking','Water — as needed']::text[], ARRAY['Drain the soaked moong dal; blend with oats, green chilli, ginger, cumin seeds, and enough water to make a thin, pourable batter.','Stir in curry leaves and salt; rest 5 minutes.','Heat a non-stick tawa over high heat; splash a few drops of water — it should sizzle away immediately.','Reduce heat to medium; pour a ladleful of batter and spread in a thin circle.','Drizzle oil around the edges; cook 2–3 minutes until golden and crisp.','Fold and serve with coconut chutney and sambar.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 220, 8.5, 36, 4.8, 5.5, 2.6, 50, 0, 280, false),
  (486, 'Masoor Dal with Tomato and Lemon', 'North Indian', 'north_indian', 'vegan', false, 'dal', '3', '5 min', '25 min', 'Red lentils simmered until silky, brightened with ripe tomatoes and finished with fresh lemon — one of the most bioavailable plant-iron dishes in the Indian kitchen.', 'Adding lemon juice after cooking (not during) preserves vitamin C, which significantly boosts the absorption of non-haem iron from the lentils.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Red lentils (masoor dal) — 1 cup','Tomatoes, chopped — 2','Onion, finely chopped — 1','Garlic, minced — 3 cloves','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Red chilli powder — ½ tsp','Lemon juice — 2 tbsp','Oil — 2 tsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Rinse the masoor dal and add to a saucepan with 2½ cups water and turmeric.','Bring to a boil, skimming foam, then simmer 15 minutes until the dal is completely soft.','Heat oil in a separate pan; add cumin seeds and let them splutter.','Add onion and cook until golden, about 6 minutes.','Add garlic and ginger; cook 1 minute, then add tomatoes and red chilli powder.','Cook until tomatoes break down into a thick masala, about 5 minutes.','Pour the masala into the cooked dal; stir and simmer together 5 minutes.','Remove from heat; stir in lemon juice, season with salt, garnish with coriander, and serve with roti or rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 180, 195, 12.5, 30, 3.5, 8.5, 4.2, 52, 0, 385, false),
  (487, 'Mixed Dal (Moong-Masoor)', 'North Indian', 'north_indian', 'vegan', false, 'dal', '3', '5 min', '25 min', 'Yellow moong and red masoor lentils cooked together — combining the digestibility of moong with the exceptional iron content of masoor in one comforting bowl.', 'This dal thickens as it sits; add a splash of hot water when reheating and it comes back to the right consistency.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Yellow moong dal — ½ cup','Red masoor dal — ½ cup','Onion, sliced — 1','Tomato, chopped — 1','Garlic, minced — 3 cloves','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Coriander powder — 1 tsp','Red chilli powder — ½ tsp','Lemon juice — 1 tbsp','Ghee or oil — 2 tsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Rinse both dals together; add to a pressure cooker with 2 cups water, turmeric, and salt.','Cook for 3 whistles; let pressure release naturally.','Heat ghee in a pan; add cumin seeds and let them splutter.','Add onion and cook until golden, about 6 minutes.','Add garlic, ginger, and spice powders; cook 1 minute.','Add tomato; cook until soft, about 4 minutes.','Pour the tadka into the cooked dal; stir well and simmer 5 minutes.','Finish with lemon juice and garnish with coriander.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 180, 215, 12.8, 32, 4.2, 8, 3.8, 58, 0, 350, false),
  (488, 'Palak-Rajma Curry', 'North Indian', 'north_indian', 'vegan', false, 'curry', '4', '15 min + overnight soak', '40 min', 'Iron-rich kidney beans simmered in a vibrant spinach gravy — a powerhouse combination that delivers exceptional plant iron alongside vitamin C to maximise its absorption.', 'Cooking the spinach purée briefly in the oil before adding rajma removes raw bitterness and deepens the green colour.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','Calcium-Rich','High-Fibre']::text[], ARRAY['Kidney beans (rajma), soaked overnight — 1 cup','Fresh spinach — 300 g','Onion, chopped — 2','Tomatoes, chopped — 2','Garlic — 5 cloves','Ginger — 1½-inch piece','Green chilli — 1','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Coriander powder — 1½ tsp','Garam masala — ½ tsp','Oil — 2 tbsp','Salt — to taste']::text[], ARRAY['Pressure cook the soaked rajma with water and a pinch of salt for 5–6 whistles until completely tender; drain, reserving liquid.','Blanch spinach in boiling water 1 minute; drain and blend to a smooth purée.','Heat oil; add cumin seeds, then onion, and cook until golden.','Blend tomatoes, garlic, ginger, and green chilli into a paste; add to the pan.','Cook the masala until oil separates, about 8 minutes.','Add turmeric, coriander powder, and garam masala; cook 1 minute.','Add spinach purée; fry 3 minutes.','Add cooked rajma and enough reserved liquid for a medium-thick gravy; simmer 10 minutes.','Season with salt and serve with roti or brown rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 200, 245, 13.5, 34, 5.8, 9.5, 5.5, 120, 0, 420, false),
  (489, 'Mixed Legume Curry (Rajma-Chana)', 'North Indian', 'north_indian', 'vegan', false, 'curry', '4', '15 min + overnight soak', '45 min', 'Kidney beans and chickpeas braised together in a rich, spiced tomato-onion gravy — two legumes that together provide an extraordinary hit of plant protein, iron, and fibre.', 'Cooking both legumes in the same pot saves time; chickpeas take slightly longer, so start them 10 minutes ahead if cooking separately.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Kidney beans (rajma), soaked overnight — ½ cup','Chickpeas (chana), soaked overnight — ½ cup','Onion, finely chopped — 2','Tomatoes, puréed — 2','Garlic, minced — 5 cloves','Ginger, grated — 1½ tsp','Cumin seeds — 1 tsp','Bay leaf — 1','Turmeric — ½ tsp','Coriander powder — 2 tsp','Cumin powder — 1 tsp','Garam masala — ½ tsp','Kashmiri red chilli — 1 tsp','Oil — 2 tbsp','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Pressure cook soaked rajma and chana together with water and a pinch of salt for 6–7 whistles until tender; drain, reserving liquid.','Heat oil; add cumin seeds and bay leaf.','Add onion and cook until deep golden, about 8 minutes.','Add garlic and ginger; cook 1 minute.','Add tomato purée and all spice powders; cook until oil rises to the surface, about 8 minutes.','Add the cooked legumes with 1 cup reserved liquid; stir well.','Simmer 12 minutes until the gravy thickens and coats the beans.','Garnish with coriander and serve with rice or roti.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 200, 260, 14.2, 38, 5.5, 10.5, 4.8, 75, 0, 410, false),
  (490, 'Palak Dal (Toovar-Spinach)', 'South Indian', 'south_indian', 'vegan', false, 'dal', '4', '10 min', '30 min', 'Pigeon peas and fresh spinach cooked together into a wholesome dal — toovar''s mild earthiness and spinach''s iron-rich vividity make this a nutritional cornerstone of South Indian meals.', 'Stir the spinach into the dal in the last 5 minutes only; prolonged cooking dulls the colour and reduces vitamin content.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','Calcium-Rich','High-Fibre']::text[], ARRAY['Toovar dal (split pigeon peas) — 1 cup','Fresh spinach, roughly chopped — 200 g','Tomato, chopped — 1','Onion, chopped — 1','Garlic, minced — 3 cloves','Green chilli — 1','Mustard seeds — ½ tsp','Cumin seeds — ½ tsp','Curry leaves — 10','Turmeric — ½ tsp','Tamarind pulp — 1 tsp','Oil — 2 tsp','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Rinse toovar dal; pressure cook with 2 cups water and turmeric for 4 whistles until soft.','Mash the cooked dal lightly with the back of a spoon.','Heat oil in a saucepan; add mustard seeds and cumin seeds and let them splutter.','Add curry leaves, onion, and green chilli; cook until the onion softens.','Add garlic and tomato; cook until the tomato breaks down, about 5 minutes.','Add tamarind pulp and the mashed dal with enough water for a medium consistency.','Simmer 5 minutes, then stir in the spinach; cook 3–4 minutes until wilted.','Season with salt, garnish with coriander, and serve with rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 180, 200, 11.5, 28, 4.5, 7.5, 5.2, 115, 0, 390, false),
  (491, 'Vegetable Barley Khichdi', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '10 min', '30 min', 'Pearl barley and moong dal cooked one-pot with seasonal vegetables — barley''s beta-glucan fibre actively lowers LDL cholesterol, making this khichdi a therapeutic one-bowl meal.', 'Pearl barley needs more water than rice; use a 1:3 ratio (barley to water) to ensure it cooks through without going mushy.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','High-Fibre','Cholesterol-Friendly','Iron-Rich']::text[], ARRAY['Pearl barley — ½ cup','Yellow moong dal — ¼ cup','Mixed vegetables (carrot, beans, peas), chopped — 1 cup','Onion, sliced — 1','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Bay leaf — 1','Turmeric — ½ tsp','Coriander powder — 1 tsp','Ghee — 1 tsp','Salt — to taste','Fresh coriander — garnish','Lemon juice — 1 tsp']::text[], ARRAY['Rinse barley and moong dal separately; soak barley in water for 30 minutes if time allows.','Heat ghee in a pressure cooker; add cumin seeds and bay leaf.','Add onion and ginger; cook until softened, about 3 minutes.','Add mixed vegetables, turmeric, and coriander powder; stir 2 minutes.','Add drained barley, moong dal, 2 cups water, and salt.','Pressure cook for 4 whistles; let pressure release naturally.','Stir gently, add a splash of water if needed for porridge-like consistency.','Finish with lemon juice and garnish with coriander.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 265, 9.5, 48, 4.8, 8.5, 2.8, 48, 0, 360, false),
  (492, 'Mushroom-Methi Stir-Fry', 'North Indian', 'north_indian', 'vegan', false, 'side', '2', '10 min', '15 min', 'Button mushrooms and fresh fenugreek leaves sautéed with spices — one of the few Indian vegetable dishes that provides meaningful plant-source vitamin D, while methi adds iron and fibre.', 'Don''t crowd the pan when frying mushrooms; cook in one layer so they sear golden rather than steam and turn watery.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb','Iron-Rich','Vitamin-D-Rich']::text[], ARRAY['Button mushrooms, halved — 300 g','Fresh methi (fenugreek leaves), stems removed — 1 cup','Onion, thinly sliced — 1','Garlic, minced — 3 cloves','Green chilli, slit — 1','Cumin seeds — ½ tsp','Turmeric — ¼ tsp','Coriander powder — 1 tsp','Kashmiri red chilli — ½ tsp','Oil — 2 tsp','Salt — to taste','Lemon juice — 1 tsp']::text[], ARRAY['Heat oil in a wide pan over high heat; add cumin seeds.','Add onion and cook until it starts to colour, about 4 minutes.','Add garlic and green chilli; cook 30 seconds.','Add mushrooms in a single layer; cook without stirring for 2 minutes to get golden colour, then toss.','Add turmeric, coriander powder, and Kashmiri chilli; stir well.','Add methi leaves; cook, stirring, 3 minutes until the leaves wilt and most moisture evaporates.','Finish with lemon juice, season with salt, and serve as a dry subji with roti.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 120, 145, 6.5, 12, 7.8, 4.5, 1.8, 42, 0, 325, false),
  (493, 'Moong Dal and Spinach Curry', 'North Indian', 'north_indian', 'vegan', false, 'dal', '3', '5 min', '25 min', 'Yellow moong dal and fresh spinach in a lightly spiced gravy — easily digestible, iron-dense, and ideal for anyone managing iron deficiency.', 'Moong dal cooks quickly; avoid over-boiling or it turns gluey. Cook just until the dal is soft but the grains still hold their shape.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','Calcium-Rich']::text[], ARRAY['Yellow moong dal — 1 cup','Fresh spinach — 200 g','Onion, chopped — 1','Tomato, chopped — 1','Garlic, minced — 3 cloves','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Coriander powder — 1 tsp','Red chilli powder — ½ tsp','Garam masala — ¼ tsp','Oil — 2 tsp','Salt — to taste','Lemon juice — 1 tsp']::text[], ARRAY['Cook moong dal with 2 cups water and turmeric until soft but not mushy, about 15 minutes.','Heat oil in a separate pan; add cumin seeds.','Add onion and cook until golden, about 5 minutes.','Add garlic and ginger; cook 1 minute.','Add tomato, coriander powder, chilli powder, and garam masala; cook until oil separates.','Add the cooked dal and mix well.','Stir in spinach; simmer 4 minutes until wilted.','Finish with lemon juice, season with salt, and serve with roti.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 180, 185, 11.2, 26, 3.8, 6.8, 4.8, 98, 0, 375, false),
  (494, 'Masoor Dal Soup', 'North Indian', 'north_indian', 'vegan', false, 'soup', '3', '5 min', '20 min', 'A light, warming soup of red lentils with aromatic spices and bright lemon — fast to make, exceptionally iron-rich, and light enough as an evening meal on its own.', 'For a silkier soup, blend half the cooked dal and stir back into the pot; this creates body without adding cream.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre','Low-Fat']::text[], ARRAY['Red masoor dal — ¾ cup','Onion, chopped — 1','Garlic, minced — 3 cloves','Ginger, grated — 1 tsp','Tomato, chopped — 1','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Red chilli powder — ½ tsp','Lemon juice — 2 tbsp','Oil — 1 tsp','Fresh coriander — garnish','Salt — to taste','Water — 3 cups']::text[], ARRAY['Heat oil in a saucepan; add cumin seeds and let them splutter.','Add onion and cook until softened, about 4 minutes.','Add garlic and ginger; cook 30 seconds.','Add tomato, turmeric, and chilli powder; cook until tomato softens.','Add rinsed masoor dal and water; bring to a boil.','Simmer uncovered 15 minutes until the dal has dissolved completely.','Blend half the soup for a creamier consistency if desired.','Stir in lemon juice, season with salt, garnish with coriander, and serve.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 160, 10.5, 24, 2.8, 7.5, 3.8, 45, 0, 400, false),
  (495, 'Moong Dal Khichdi with Brown Rice', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '5 min + 30 min soak', '30 min', 'The classic Ayurvedic one-pot meal — split moong and brown rice cooked together with turmeric and cumin into a healing, easily digested porridge.', 'Brown rice needs a longer soak (30 min) and more water than white rice; the 1:2.5 ratio of rice to water gives the right soft texture for khichdi.', 'Therapeutic', ARRAY['Vegetarian','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Brown rice — ½ cup, soaked 30 min','Yellow moong dal — ½ cup','Onion, sliced — 1','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Bay leaf — 1','Turmeric — ½ tsp','Ghee — 1 tsp','Asafoetida — a pinch','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Rinse soaked brown rice and moong dal together.','Heat ghee in a pressure cooker; add cumin seeds, bay leaf, and asafoetida.','Add onion and ginger; cook 2 minutes.','Add the rice-dal mixture, turmeric, 2½ cups water, and salt.','Pressure cook for 5 whistles; let pressure release naturally.','The khichdi should have a soft, porridge-like consistency; add hot water and stir if needed.','Garnish with coriander and serve with yogurt and pickle.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 280, 11.5, 50, 5.2, 5.5, 2.8, 48, 0, 340, false),
  (496, 'Palak-Toovar Dal', 'South Indian', 'south_indian', 'vegan', false, 'dal', '4', '10 min', '30 min', 'A South Indian-style spiced pigeon pea dal finished with fresh spinach — toovar''s protein and spinach''s iron-calcium richness come together in one satisfying bowl.', 'Use tender baby spinach for this dal; it wilts faster and has a milder flavour than mature spinach, which can taste bitter in dal.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','Calcium-Rich']::text[], ARRAY['Toovar dal (split pigeon peas) — 1 cup','Fresh spinach, chopped — 150 g','Tomato, chopped — 1','Onion, chopped — 1','Garlic — 4 cloves','Dried red chilli — 2','Mustard seeds — ½ tsp','Cumin seeds — ½ tsp','Curry leaves — 10','Turmeric — ½ tsp','Coriander powder — 1 tsp','Sambar powder — 1 tsp','Oil — 2 tsp','Salt — to taste','Lemon juice — 1 tsp']::text[], ARRAY['Pressure cook toovar dal with 2 cups water and turmeric until very soft; mash lightly.','Heat oil; add mustard seeds and dried red chilli; let them splutter.','Add cumin seeds and curry leaves; fry 20 seconds.','Add onion and cook until golden.','Add garlic and cook 1 minute.','Add tomato, coriander powder, and sambar powder; cook until masala is thick.','Add the mashed dal with water for desired consistency; simmer 5 minutes.','Stir in spinach; cook 3 minutes until wilted.','Finish with lemon juice and season with salt.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 180, 195, 10.8, 28, 4.2, 7, 5, 110, 0, 385, false),
  (497, 'Chana Dal', 'North Indian', 'north_indian', 'vegan', false, 'dal', '4', '10 min + 1 h soak', '30 min', 'Split Bengal gram cooked slow with whole spices and a vibrant tomato-onion base — chana dal is exceptionally high in protein and soluble fibre, with a naturally low glycaemic index.', 'Chana dal holds its shape even after pressure cooking; if you prefer a smoother texture, cook for one extra whistle and mash lightly.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre','Low-Glycaemic']::text[], ARRAY['Chana dal (split Bengal gram), soaked 1 h — 1 cup','Onion, finely chopped — 1','Tomatoes, chopped — 2','Garlic, minced — 4 cloves','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Cloves — 2','Cinnamon — ½-inch piece','Turmeric — ½ tsp','Coriander powder — 1½ tsp','Red chilli powder — ½ tsp','Garam masala — ½ tsp','Oil — 2 tsp','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Pressure cook drained chana dal with 2 cups water for 4 whistles until tender but not mushy.','Heat oil; add cumin seeds, cloves, and cinnamon; fry 30 seconds.','Add onion and cook until golden, about 7 minutes.','Add garlic and ginger; cook 1 minute.','Add tomatoes and all spice powders; cook until oil separates, about 7 minutes.','Add the cooked chana dal with its liquid; stir and simmer 8 minutes.','Adjust consistency with water; finish with garam masala.','Garnish with coriander and serve with roti or rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 225, 12.5, 36, 4.5, 8, 3.2, 52, 0, 360, false),
  (498, 'Mixed Sprout Pulao', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '15 min + overnight sprout', '25 min', 'Freshly sprouted legumes cooked with brown rice and fragrant whole spices — sprouting dramatically increases bioavailable iron and vitamin C in the beans.', 'Home-sprouting takes 24–36 hours but boosts iron and folate content significantly; rinse the sprouts twice daily to keep them fresh.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','High-Fibre']::text[], ARRAY['Brown rice — ¾ cup','Mixed sprouts (moong, matki, chana) — 1 cup','Onion, thinly sliced — 1','Tomato, chopped — 1','Green chilli — 1','Ginger-garlic paste — 1 tsp','Bay leaf — 1','Cloves — 2','Cinnamon — ½-inch piece','Cardamom — 1 pod','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Coriander powder — 1 tsp','Garam masala — ½ tsp','Ghee or oil — 2 tsp','Salt — to taste','Fresh mint and coriander — for garnish']::text[], ARRAY['Wash and soak brown rice 30 minutes; drain.','Heat ghee in a heavy-bottomed pot; add cumin seeds, bay leaf, cloves, cinnamon, and cardamom.','Add onion and cook until golden.','Add ginger-garlic paste and green chilli; cook 1 minute.','Add tomato, turmeric, coriander powder, and garam masala; cook until masala thickens.','Add sprouts and rice; stir to coat in the masala.','Add 1¾ cups water and salt; bring to a boil.','Cover tightly and cook on low heat 20 minutes until rice is done and water absorbed.','Rest 5 minutes, then fluff gently. Garnish with mint and coriander.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 250, 295, 10.5, 52, 5.8, 7.5, 3.5, 55, 0, 345, false),
  (499, 'Moong-Methi Dal', 'North Indian', 'north_indian', 'vegan', false, 'dal', '3', '10 min', '20 min', 'Yellow moong dal cooked with fresh fenugreek leaves — methi adds bitter depth, iron, and a compound linked to blood glucose regulation.', 'If fresh methi is unavailable, use 2 tbsp dried kasuri methi; add it with the spices rather than at the end.', 'Therapeutic', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein','Iron-Rich','Calcium-Rich']::text[], ARRAY['Yellow moong dal — 1 cup','Fresh methi (fenugreek leaves), stripped — 1 cup','Onion, finely chopped — 1','Tomato, chopped — 1','Garlic, minced — 3 cloves','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Red chilli powder — ½ tsp','Coriander powder — 1 tsp','Oil — 2 tsp','Salt — to taste','Lemon juice — 1 tsp']::text[], ARRAY['Cook moong dal with 2 cups water and turmeric until soft; set aside.','Heat oil; add cumin seeds and let them splutter.','Add onion and cook until golden.','Add garlic; cook 30 seconds.','Add tomato, chilli powder, and coriander powder; cook until oil separates.','Add cooked dal; stir and simmer 5 minutes, adjusting water for medium consistency.','Stir in the methi leaves; cook 4 minutes until tender.','Finish with lemon juice and salt.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 185, 10.2, 28, 3.5, 6.5, 3.2, 78, 0, 360, false),
  (500, 'Mushroom-Barley Khichdi', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '10 min', '35 min', 'Pearl barley and yellow moong cooked one-pot with earthy button mushrooms — barley''s beta-glucan lowers LDL cholesterol while mushrooms contribute rare plant-source vitamin D.', 'Add the mushrooms after the initial pressure release so they remain plump and meaty rather than dissolving into the khichdi.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','High-Fibre','Cholesterol-Friendly','Vitamin-D-Rich']::text[], ARRAY['Pearl barley — ½ cup','Yellow moong dal — ¼ cup','Button mushrooms, quartered — 200 g','Onion, sliced — 1','Ginger, grated — 1 tsp','Garlic, minced — 2 cloves','Cumin seeds — 1 tsp','Bay leaf — 1','Turmeric — ½ tsp','Black pepper — ½ tsp','Ghee or oil — 1 tsp','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Rinse barley and moong dal; soak barley in cold water for 30 minutes.','Heat ghee in a pressure cooker; add cumin seeds and bay leaf.','Add onion, ginger, and garlic; cook 3 minutes.','Add drained barley and moong; stir to coat.','Add 2¼ cups water, turmeric, pepper, and salt; pressure cook 4 whistles.','Let pressure release naturally; open the lid and gently fold in the mushrooms.','Cover (without locking) and steam on low heat 5 minutes until mushrooms are cooked.','Stir, check seasoning, garnish with coriander, and serve hot.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 255, 9.2, 46, 4.5, 8.2, 2.2, 38, 0, 350, false),
  (501, 'Bajra Khichdi', 'Rajasthani', 'north_indian', 'veg', false, 'main', '3', '10 min + 30 min soak', '30 min', 'Pearl millet and moong dal cooked into a warming khichdi — a winter staple from Rajasthan that is rich in iron, plant protein, and provides sustained warmth and energy.', 'A small piece of jaggery added during cooking balances bajra''s naturally robust, slightly bitter flavour beautifully.', 'Therapeutic', ARRAY['Vegetarian','Gluten-Free','Nut-Free','Iron-Rich','High-Fibre']::text[], ARRAY['Bajra (pearl millet), soaked 30 min — ¾ cup','Yellow moong dal — ¼ cup','Onion, chopped — 1','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Ghee — 1 tsp','Jaggery — ½ tsp (optional)','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Drain soaked bajra; rinse moong dal.','Heat ghee in a pressure cooker; add cumin seeds.','Add onion and ginger; cook until softened.','Add bajra and moong dal; stir to combine.','Add 2½ cups water, turmeric, salt, and jaggery if using.','Pressure cook for 5–6 whistles until the bajra is completely soft.','Let pressure release; open and stir well — the khichdi should be soft and porridge-like.','Garnish with coriander and serve with ghee, yogurt, and green chutney.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 270, 8.5, 50, 5.5, 6.5, 3.2, 38, 0, 330, false),
  (502, 'Vegetable Barley Pulao', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '10 min', '35 min', 'Pearl barley cooked pulao-style with fragrant spices and mixed vegetables — an elegant, cholesterol-friendly alternative to rice that looks and tastes like a feast.', 'Barley absorbs flavour deeply; toast it in ghee for 2 minutes before adding water to unlock a rich, nutty aroma.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','High-Fibre','Iron-Rich','Cholesterol-Friendly']::text[], ARRAY['Pearl barley — 1 cup','Mixed vegetables (carrot, beans, peas, corn) — 1 cup','Onion, thinly sliced — 1','Ginger-garlic paste — 1 tsp','Bay leaf — 1','Cloves — 3','Cardamom — 2 pods','Cinnamon — 1-inch piece','Cumin seeds — 1 tsp','Turmeric — ¼ tsp','Garam masala — ½ tsp','Ghee or oil — 2 tsp','Salt — to taste','Fresh mint and coriander — garnish']::text[], ARRAY['Rinse barley; soak in cold water 30 minutes then drain.','Heat ghee; add cumin seeds, bay leaf, cloves, cardamom, and cinnamon.','Add onion and cook until golden, about 6 minutes.','Add ginger-garlic paste; cook 1 minute.','Add mixed vegetables; stir 2 minutes.','Add barley and toast, stirring, 2 minutes.','Add 2½ cups water, turmeric, garam masala, and salt; bring to a boil.','Reduce heat; cover and cook 25 minutes until barley is tender and water absorbed.','Fluff gently, garnish with fresh herbs, and serve with raita.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 250, 285, 9.8, 54, 5.2, 8.8, 2.5, 42, 0, 355, false),
  (503, 'Dalia-Vegetable Khichdi', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '5 min', '25 min', 'Broken wheat and moong dal cooked together with a medley of seasonal vegetables — a lighter, lower-glycaemic cousin of rice khichdi that is high in fibre and easy to digest.', 'This khichdi comes together very quickly compared to rice or barley — watch it closely after the second whistle to avoid over-cooking.', 'Therapeutic', ARRAY['Vegetarian','Nut-Free','High-Protein','High-Fibre','Iron-Rich','Cholesterol-Friendly']::text[], ARRAY['Broken wheat (dalia) — ½ cup','Yellow moong dal — ¼ cup','Mixed vegetables (carrot, peas, potato), chopped — ¾ cup','Onion, chopped — 1','Ginger, grated — 1 tsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Bay leaf — 1','Ghee or oil — 1 tsp','Salt — to taste','Fresh coriander — garnish','Lemon juice — 1 tsp']::text[], ARRAY['Rinse dalia and moong dal together.','Heat ghee in a pressure cooker; add cumin seeds and bay leaf.','Add onion and ginger; cook 2 minutes.','Add mixed vegetables and turmeric; stir 1 minute.','Add the dalia-dal mixture and toast, stirring, 1 minute.','Add 2 cups water and salt; stir well.','Pressure cook for 2 whistles; let pressure release naturally.','Open, stir gently, add a splash of water if needed.','Finish with lemon juice and garnish with coriander.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 250, 9.5, 44, 5.5, 6.2, 2.4, 45, 0, 340, false),
  (504, 'Sambar Sadam', 'Tamil', 'south_indian', 'veg', false, 'main', '2', '10 min', '30 min', 'Rice cooked with toor dal, tamarind, and a medley of vegetables in the quintessential Tamil sambar — a complete one-pot lunch.', 'Use small shallots for authentic sweetness. A generous squeeze of ghee on top elevates the flavour.', 'Traditional', NULL, ARRAY['Rice — 1 cup, washed','Toor dal — ½ cup','Tamarind — small lemon-sized ball','Tomato — 2, chopped','Drumstick — 1, cut into pieces','Carrot — 1, diced','Onion — 1, sliced','Sambar powder — 2 tsp','Turmeric — ¼ tsp','Asafoetida — a pinch','Ghee — 1 tsp','Mustard seeds — 1 tsp','Curry leaves — 10','Salt to taste','Coriander leaves to garnish']::text[], ARRAY['Pressure cook rice and dal together with 3 cups water until soft.','Soak tamarind in warm water, extract juice and set aside.','Sauté mustard seeds, curry leaves, and asafoetida in a deep pot.','Add onion, cook until translucent, then add tomatoes.','Add tamarind water, sambar powder, turmeric, and vegetables.','Simmer 15 min until vegetables are cooked and sambar thickens.','Stir in cooked rice-dal mixture, season and simmer 5 min.','Serve hot topped with a drizzle of ghee.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 300, 380, 14, 68, 5, 6, 3.2, 62, 0.1, 480, true),
  (505, 'Puliyodarai', 'Tamil', 'south_indian', 'vegan', true, 'main', '2', '15 min', '20 min', 'Tamarind rice — a tangy, spiced temple offering that doubles as the most beloved Tamil travel and tiffin box lunch.', 'The pulikachal (tamarind paste) can be made ahead and stored for a week. Adjust chilli to taste.', 'Temple Classic', NULL, ARRAY['Rice — 1 cup, cooked and cooled','Tamarind — lime-sized ball','Groundnuts — 3 tbsp, roasted','Chana dal — 1 tbsp','Urad dal — 1 tbsp','Dry red chilli — 3','Mustard seeds — 1 tsp','Curry leaves — 10','Turmeric — ¼ tsp','Asafoetida — a pinch','Gingelly (sesame) oil — 2 tbsp','Salt to taste']::text[], ARRAY['Soak tamarind in 1 cup warm water, extract thick juice.','Heat gingelly oil, add mustard seeds, both dals, and dry chillies.','Add curry leaves and asafoetida, then pour in tamarind extract.','Add turmeric, salt, and cook on medium until the paste thickens.','Mix in roasted groundnuts and cook until oil separates.','Add this pulikachal to cooled rice, fold gently to coat evenly.','Serve at room temperature — this dish tastes best that way.']::text[], ARRAY['lunch']::text[], 'plate', 250, 320, 8, 58, 8, 4, 2.8, 45, 0, 420, true),
  (506, 'Thayir Sadam', 'Tamil', 'south_indian', 'veg', true, 'main', '2', '5 min', '15 min', 'Curd rice — the cooling finale to every Tamil meal and a complete lunch on its own. Creamy, tangy, and deeply comforting.', 'Use slightly overcooked rice for best texture. Full-fat curd gives a richer result.', 'Comfort', NULL, ARRAY['Rice — 1 cup, cooked soft','Curd (yoghurt) — 1 cup, beaten','Milk — ¼ cup','Ginger — ½ inch, finely grated','Green chilli — 1, finely chopped','Pomegranate seeds — 2 tbsp (garnish)','Ghee — 1 tsp','Mustard seeds — ½ tsp','Dry red chilli — 1','Curry leaves — 8','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Mash warm cooked rice lightly with a fork.','Mix in milk and let it cool to room temperature.','Beat curd smooth and mix into the rice until creamy.','Heat ghee, add mustard seeds, red chilli, and curry leaves.','Pour tempering over the rice and mix.','Add ginger, green chilli, salt, and coriander.','Garnish with pomegranate seeds. Serve chilled or at room temperature.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 250, 260, 9, 48, 6, 2, 0.8, 120, 0.4, 220, true),
  (507, 'Keerai Kootu', 'Tamil', 'south_indian', 'vegan', true, 'dal', '2', '10 min', '20 min', 'Spinach and chana dal simmered with coconut — a nourishing Tamil kootu that is best eaten with hot rice and a drizzle of ghee.', 'Blanch the spinach just before adding to preserve colour. A kootu should be thick, not watery.', 'Traditional', NULL, ARRAY['Spinach (keerai) — 2 cups, roughly chopped','Chana dal — ½ cup, soaked 30 min','Coconut — 4 tbsp, grated','Cumin seeds — 1 tsp','Green chilli — 2','Turmeric — ¼ tsp','Coconut oil — 1 tbsp','Mustard seeds — ½ tsp','Urad dal — 1 tsp','Dry red chilli — 2','Curry leaves — 8','Salt to taste']::text[], ARRAY['Cook soaked chana dal until just tender. Set aside.','Grind coconut, cumin, and green chilli to a coarse paste.','Blanch spinach in boiling water for 2 min, drain and roughly chop.','Combine cooked dal, spinach, and coconut paste in a pan.','Add turmeric, salt, and simmer on low for 8 min until thick.','Prepare tempering: mustard seeds, urad dal, red chilli, curry leaves in coconut oil.','Pour tempering over the kootu and serve with rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 200, 12, 28, 8, 8, 4.5, 140, 0, 280, true),
  (508, 'Elumichai Sadam', 'Tamil', 'south_indian', 'vegan', true, 'main', '2', '10 min', '15 min', 'Lemon rice — bright, citrusy, and ready in minutes. A Tamil staple for festive days and lunchboxes alike.', 'Use day-old rice for the best texture — fresh rice turns sticky when mixed with lemon juice.', 'Quick & Festive', NULL, ARRAY['Rice — 1 cup, cooked and cooled','Lemon juice — 3 tbsp','Groundnuts — 3 tbsp, roasted','Green chilli — 2, slit','Ginger — ½ inch, grated','Turmeric — ½ tsp','Mustard seeds — 1 tsp','Chana dal — 1 tsp','Urad dal — 1 tsp','Curry leaves — 10','Cashews — 1 tbsp (optional)','Gingelly oil — 2 tbsp','Salt to taste','Coriander leaves to garnish']::text[], ARRAY['Heat gingelly oil, add mustard seeds, both dals, and cashews.','When dals turn golden, add green chilli, ginger, and curry leaves.','Add turmeric and sauté 30 seconds.','Add cooled rice and mix gently on low heat.','Remove from heat, squeeze in lemon juice, and toss well.','Add roasted groundnuts and coriander, season and serve.']::text[], ARRAY['lunch']::text[], 'plate', 250, 290, 7, 54, 7, 4, 2.1, 32, 0, 280, true),
  (509, 'Thengai Sadam', 'Tamil', 'south_indian', 'vegan', true, 'main', '2', '10 min', '15 min', 'Coconut rice — fragrant, mildly sweet rice tossed with fresh coconut and spices. A temple offering and a celebration in every bite.', 'Fresh coconut is non-negotiable for this dish. Dry coconut gives a flat flavour.', 'Temple Classic', NULL, ARRAY['Rice — 1 cup, cooked and cooled','Fresh coconut — ½ cup, grated','Green chilli — 2, slit','Cashews — 2 tbsp','Chana dal — 1 tbsp','Urad dal — 1 tbsp','Mustard seeds — 1 tsp','Dry red chilli — 2','Curry leaves — 10','Coconut oil — 2 tbsp','Salt to taste']::text[], ARRAY['Heat coconut oil in a wide pan.','Add mustard seeds, both dals, red chilli, and curry leaves.','Add cashews and green chilli, sauté until golden.','Add grated coconut and toast for 2 min on medium heat.','Add cooked rice, salt, and toss gently until evenly coated.','Serve warm or at room temperature.']::text[], ARRAY['lunch']::text[], 'plate', 250, 310, 6, 52, 9, 3, 1.5, 18, 0, 200, true),
  (510, 'Vatha Kuzhambu', 'Tamil', 'south_indian', 'vegan', true, 'curry', '2', '10 min', '25 min', 'A bold, tangy tamarind-based Tamil curry cooked with sun-dried manathakkali or sundakkai — poured generously over rice for a deeply satisfying lunch.', 'Gingelly oil is essential — it gives the authentic flavour. This curry actually tastes better the next day.', 'Traditional', NULL, ARRAY['Tamarind — lemon-sized ball','Manathakkali or Sundakkai vathal (sun-dried berries) — 2 tbsp','Sambar powder — 1½ tsp','Coriander powder — 1 tsp','Turmeric — ¼ tsp','Asafoetida — a pinch','Gingelly oil — 2 tbsp','Mustard seeds — 1 tsp','Toor dal — 1 tsp (for tempering)','Curry leaves — 10','Jaggery — ½ tsp','Salt to taste']::text[], ARRAY['Soak tamarind in 1½ cups warm water, extract juice.','Heat gingelly oil, fry vathal until it puffs and darkens slightly.','Add mustard seeds, toor dal, and curry leaves.','Pour in tamarind extract, add sambar powder, coriander powder, turmeric.','Simmer on medium for 15–20 min until the kuzhambu thickens.','Add jaggery and asafoetida, simmer 2 more min.','Serve with hot rice topped with a spoon of ghee.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 120, 150, 3, 22, 7, 3, 2.4, 38, 0, 560, true),
  (511, 'Paruppu', 'Tamil', 'south_indian', 'veg', true, 'dal', '2', '5 min', '20 min', 'Toor dal cooked Tamil style — lightly spiced, finished with ghee and asafoetida. The backbone of a complete Tamil lunch plate.', 'This dal should be thicker than North Indian dal fry — almost like a soft paste poured over rice.', 'Staple', NULL, ARRAY['Toor dal — ½ cup','Tomato — 2, chopped','Green chilli — 2','Turmeric — ¼ tsp','Ghee — 1½ tsp','Cumin seeds — 1 tsp','Dry red chilli — 2','Asafoetida — ¼ tsp','Curry leaves — 8','Salt to taste','Coriander leaves to garnish']::text[], ARRAY['Pressure cook toor dal with tomatoes and green chilli until very soft.','Mash the dal until smooth and creamy.','Add turmeric, salt and simmer on low for 5 min.','Heat ghee, add cumin seeds, red chilli, asafoetida, and curry leaves.','Pour the sizzling tempering over the dal.','Serve over hot rice as the base of a Tamil lunch plate.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 190, 13, 28, 5, 5, 3.8, 48, 0.05, 240, true),
  (512, 'Idli with Sambar', 'Tamil', 'south_indian', 'vegan', false, 'main', '2', '10 min (+ overnight ferment)', '20 min', 'Soft, steamed rice-and-lentil cakes served with piping hot sambar — the most iconic Tamil breakfast, eaten in homes and dhabas across the state every morning.', 'Use the 3:1 rice-to-urad ratio. Well-fermented batter is the secret to airy idlis.', 'Iconic', NULL, ARRAY['Idli rice — 3 cups, soaked overnight','Urad dal — 1 cup, soaked overnight','Fenugreek seeds — 1 tsp','Salt to taste','For sambar: toor dal — ¼ cup','Tomato — 1','Shallots — 5','Sambar powder — 1½ tsp','Tamarind — small piece','Turmeric — ¼ tsp','Mustard seeds — ½ tsp','Curry leaves — 8','Oil — 1 tsp']::text[], ARRAY['Grind soaked dal and fenugreek until fluffy. Grind rice to a slightly coarse batter.','Mix both, add salt, and ferment overnight.','Pour into greased idli moulds and steam for 10–12 min.','Meanwhile, cook toor dal with tomato and shallots until soft.','Add sambar powder, tamarind water, turmeric, and simmer 10 min.','Temper with mustard seeds and curry leaves.','Serve 4 idlis with a generous bowl of sambar.']::text[], ARRAY['breakfast']::text[], 'serving', 250, 220, 10, 40, 2, 4, 2.4, 42, 0, 380, true),
  (513, 'Ven Pongal', 'Tamil', 'south_indian', 'veg', true, 'main', '2', '5 min', '20 min', 'Creamy, peppery rice-and-moong dal porridge — the quintessential Tamil breakfast offered in temples and eaten in millions of homes on weekends.', 'The generous addition of ghee is not optional — it is what makes Pongal Pongal. Use good-quality peppercorns.', 'Temple Classic', NULL, ARRAY['Raw rice — ½ cup','Yellow moong dal — ¼ cup','Water — 3 cups','Ghee — 2 tsp','Black pepper — 1 tsp, coarsely crushed','Cumin seeds — 1 tsp','Cashews — 1 tbsp','Ginger — ½ inch, grated','Curry leaves — 10','Asafoetida — a pinch','Salt to taste']::text[], ARRAY['Dry roast moong dal until lightly golden.','Pressure cook rice and roasted dal with water and salt until very soft.','Mash until creamy — Pongal should be porridge-like.','Heat ghee, add cashews and toast golden.','Add cumin, pepper, ginger, curry leaves, and asafoetida.','Pour the sizzling ghee tempering over the pongal and mix well.','Serve hot with coconut chutney and sambar.']::text[], ARRAY['breakfast','lunch']::text[], 'bowl', 250, 340, 12, 56, 8, 4, 2.8, 38, 0.05, 320, true),
  (514, 'Rava Upma', 'Tamil', 'south_indian', 'vegan', false, 'main', '2', '5 min', '15 min', 'Semolina cooked with onions, green chillies, and curry leaves — a beloved South Indian breakfast that is ready in 15 minutes and keeps you full until noon.', 'Roasting the rava until fragrant prevents lumps. Add water all at once and stir quickly.', 'Quick', NULL, ARRAY['Rava (semolina) — 1 cup, dry roasted','Onion — 1, finely chopped','Green chilli — 2, slit','Ginger — ½ inch, grated','Tomato — 1, chopped','Mustard seeds — 1 tsp','Chana dal — 1 tsp','Urad dal — 1 tsp','Curry leaves — 10','Water — 2 cups, boiling','Oil — 1½ tsp','Salt to taste','Coriander leaves to garnish','Lemon juice — 1 tsp']::text[], ARRAY['Heat oil, add mustard seeds, both dals, and curry leaves.','Add onion, green chilli, ginger and sauté until onion softens.','Add tomato and cook 2 min.','Pour in boiling water, add salt, and bring to a boil.','Add roasted rava in a steady stream, stirring constantly.','Cover and cook on low for 3–4 min until water is absorbed.','Add lemon juice and coriander. Serve hot.']::text[], ARRAY['breakfast']::text[], 'bowl', 200, 230, 8, 44, 4, 3, 1.8, 28, 0, 310, true),
  (515, 'Adai', 'Tamil', 'south_indian', 'vegan', false, 'main', '2', '20 min (+ 2 hr soak)', '15 min', 'A thick, protein-rich lentil-and-rice crepe — earthier and more filling than a dosa. Made with mixed dals, eaten with jaggery or avial.', 'No fermentation needed — just soak, grind, and cook. The batter should be coarser than dosa batter.', 'Protein Rich', NULL, ARRAY['Raw rice — ½ cup, soaked 2 hr','Chana dal — ¼ cup, soaked','Toor dal — ¼ cup, soaked','Urad dal — 2 tbsp, soaked','Dry red chilli — 3','Ginger — 1 inch','Asafoetida — a pinch','Curry leaves — 10','Onion — 1, finely chopped','Coconut — 2 tbsp, grated','Salt to taste','Oil for cooking']::text[], ARRAY['Grind soaked rice and dals with red chilli and ginger to a slightly coarse batter.','Add asafoetida, salt, and mix in curry leaves, onion, and coconut.','Heat a griddle, pour a ladleful and spread in a thick circle.','Drizzle oil around the edges, make a hole in the centre.','Cook until the base is crisp and golden, about 4 min.','Flip and cook the other side 2 min.','Serve with coconut chutney or jaggery.']::text[], ARRAY['breakfast','dinner']::text[], 'serving', 200, 280, 14, 44, 6, 7, 4.2, 62, 0, 260, true),
  (517, 'Erissery', 'Kerala', 'south_indian', 'vegan', true, 'curry', '2', '10 min', '25 min', 'Pumpkin and black-eyed peas simmered in spiced coconut paste — a sweet-savoury Kerala curry that is as nourishing as it is comforting.', 'The roasted coconut garnish at the end is not optional — it gives the dish its characteristic depth.', 'Traditional', NULL, ARRAY['Pumpkin (mathanga) — 2 cups, cubed','Black-eyed peas — ½ cup, cooked','Turmeric — ¼ tsp','Red chilli powder — ½ tsp','Fresh coconut — ½ cup, grated','Cumin seeds — 1 tsp','Coconut oil — 2 tsp','Dry red chilli — 2','Mustard seeds — ½ tsp','Curry leaves — 10','Salt to taste']::text[], ARRAY['Cook pumpkin with turmeric, red chilli powder, and salt until just soft.','Add cooked black-eyed peas and mash a few pieces to thicken.','Grind coconut and cumin to a paste, add to the pan.','Simmer for 5 min until well combined.','In a separate pan, heat coconut oil and add remaining grated coconut.','Roast until golden brown, add mustard seeds, red chilli, curry leaves.','Pour the roasted coconut tempering over the erissery and serve.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 250, 9, 38, 9, 7, 2.8, 52, 0, 280, true),
  (518, 'Olan', 'Kerala', 'south_indian', 'vegan', true, 'curry', '2', '10 min', '20 min', 'Ash gourd and red cowpeas simmered in thin coconut milk — the most delicately flavoured dish on a Kerala sadya leaf, a study in restraint.', 'Do not let the coconut milk boil after adding — gentle heat preserves its sweetness.', 'Sadya Essential', NULL, ARRAY['Ash gourd (kumbalanga) — 2 cups, cubed','Red cowpeas (vanpayar) — ½ cup, cooked','Thin coconut milk — 1 cup','Thick coconut milk — ½ cup','Green chilli — 3, slit','Coconut oil — 1½ tsp','Curry leaves — 10','Salt to taste']::text[], ARRAY['Cook ash gourd and green chilli in thin coconut milk until tender.','Add cooked red cowpeas and simmer 5 min.','Season with salt.','Add thick coconut milk and heat on very low flame — do not boil.','Drizzle coconut oil and add curry leaves.','Serve immediately as part of a rice plate.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 180, 7, 24, 8, 5, 1.8, 42, 0, 180, true),
  (519, 'Parippu Curry', 'Kerala', 'south_indian', 'vegan', false, 'dal', '2', '5 min', '20 min', 'Kerala-style moong dal in coconut milk — richer and sweeter than North Indian dal, it is the first item poured onto a banana leaf at any sadya.', 'The second pour of coconut oil and curry leaves at the end is the defining step — do not skip it.', 'Sadya First Pour', NULL, ARRAY['Moong dal (yellow) — ½ cup','Turmeric — ¼ tsp','Thick coconut milk — ¾ cup','Green chilli — 2','Coconut oil — 1½ tsp','Mustard seeds — ½ tsp','Shallots — 3, sliced','Dry red chilli — 2','Curry leaves — 10','Salt to taste']::text[], ARRAY['Cook moong dal with turmeric until very soft and mushy.','Blend smooth or mash well.','Add green chilli, salt, and simmer on low.','Pour in thick coconut milk and heat gently — do not boil.','Prepare tempering: shallots, mustard seeds, red chilli, curry leaves in coconut oil.','Pour sizzling tempering over the dal.','Serve immediately over rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 200, 12, 30, 9, 5, 2.8, 62, 0, 220, true),
  (520, 'Vegetarian Jollof Rice', 'West African', 'african', 'vegan', false, 'main', '3', '10 min', '35 min', 'The beloved West African party rice — long-grain rice cooked in a rich tomato-pepper sauce, smoky and vibrant. This vegetarian version loses nothing of the original spirit.', 'The secret is the "party smoke" — high heat at the end lets the bottom crust slightly for that iconic flavour.', 'Party Classic', NULL, ARRAY['Long-grain rice — 1 cup, washed','Tomatoes — 4, blended','Red bell pepper — 2, blended','Scotch bonnet chilli — 1 (or to taste)','Onion — 2, one blended, one sliced','Tomato paste — 2 tbsp','Vegetable stock — 1½ cups','Bay leaf — 2','Thyme — 1 tsp','Curry powder — 1 tsp','Oil — 3 tbsp','Salt to taste','Spring onions to garnish']::text[], ARRAY['Blend tomatoes, peppers, scotch bonnet, and one onion together.','Heat oil in a heavy pot, fry the sliced onion until golden.','Add tomato paste and fry 3 min until darkened.','Add the blended tomato-pepper mixture and cook on high heat for 20 min until thick.','Add thyme, curry powder, bay leaves, salt, and stock. Bring to a boil.','Add washed rice, stir once, cover tightly.','Cook on low heat 25 min. Raise heat to high for 2 min at the end for the smoky crust.','Serve garnished with spring onions.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 300, 380, 8, 72, 9, 4, 3.5, 38, 0, 520, true),
  (521, 'Ewa Riro', 'West African', 'african', 'vegan', false, 'curry', '2', '10 min', '25 min', 'Nigerian stewed black-eyed peas simmered in a bold tomato-pepper sauce — rich, protein-packed, and eaten with rice, bread, or plantain for lunch.', 'Start with canned beans for speed, or soak overnight. The longer the sauce fries, the deeper the flavour.', 'Classic', NULL, ARRAY['Black-eyed peas — 1½ cups, cooked','Tomatoes — 3, blended','Red bell pepper — 1, blended','Scotch bonnet — ½','Onion — 1, chopped','Palm oil or neutral oil — 2 tbsp','Crayfish powder — 1 tsp (optional)','Seasoning cube — 1 (or salt)','Salt to taste','Spring onions to garnish']::text[], ARRAY['Blend tomatoes, bell pepper, scotch bonnet together.','Heat oil in a pot, add onion and fry until translucent.','Add the blended pepper mixture and fry on medium-high heat for 15 min, stirring often.','Season with salt (and seasoning cube if using).','Add cooked beans and stir to coat in the sauce.','Simmer 10 min until the sauce clings to the beans.','Garnish with spring onions. Serve with rice or plantain.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 200, 270, 14, 42, 8, 10, 5.2, 65, 0, 420, true),
  (522, 'Vegetarian Groundnut Soup', 'West African', 'african', 'vegan', false, 'soup', '3', '15 min', '30 min', 'A rich, peanut-based West African soup thickened with groundnut paste and spiced with peppers — warming, filling, and endlessly satisfying over rice.', 'Roast your own groundnuts and grind fresh for the best flavour. Adjust chilli to taste.', 'Traditional', NULL, ARRAY['Groundnut (peanut) paste — 4 tbsp','Sweet potato — 1 cup, cubed','Tomatoes — 3, chopped','Onion — 1, chopped','Scotch bonnet — 1','Vegetable stock — 2 cups','Spinach — 1 cup','Tomato paste — 1 tbsp','Ginger — 1 inch, grated','Garlic — 2 cloves','Oil — 1 tbsp','Salt to taste']::text[], ARRAY['Blend tomatoes, onion, scotch bonnet, ginger, and garlic.','Heat oil in a pot and fry the blended mixture for 10 min until thick.','Add tomato paste and stir well.','Whisk groundnut paste with stock until smooth.','Pour groundnut mixture into the pot, add sweet potato.','Simmer 20 min until sweet potato is tender and soup is thick.','Stir in spinach and cook 2 min.','Serve over rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 310, 12, 38, 14, 7, 4.8, 62, 0, 480, true),
  (524, 'Sai Bhaji', 'Sindhi', 'west_indian', 'vegan', false, 'dal', '2', '10 min', '30 min', 'A one-pot Sindhi stew of spinach, dal, and vegetables — humble, deeply nourishing, and a staple of every Sindhi household at lunch.', 'The key is to cook everything together from the start — no separate steps. Everything melts into one harmonious dish.', 'Comfort', NULL, ARRAY['Spinach — 2 cups, roughly chopped','Chana dal — ¼ cup, soaked','Potato — 1, cubed','Tomato — 2, chopped','Onion — 1, sliced','Fenugreek leaves (methi) — ¼ cup','Green chilli — 2','Ginger-garlic paste — 1 tsp','Turmeric — ½ tsp','Red chilli powder — ½ tsp','Oil — 1½ tbsp','Salt to taste']::text[], ARRAY['Pressure cook chana dal, spinach, potato, tomato, onion, methi, green chilli with all spices and 1 cup water for 3 whistles.','Let pressure release naturally.','Mash everything together into a thick, homogeneous stew.','Heat oil in a pan, add ginger-garlic paste and sauté.','Add the mashed mixture and simmer for 10 min, adjusting consistency.','Serve over plain boiled rice with a wedge of lemon.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 180, 11, 28, 6, 8, 4.8, 88, 0, 320, true),
  (525, 'Dal Pakwan', 'Sindhi', 'west_indian', 'vegan', true, 'main', '2', '20 min (+ 8 hr soak)', '30 min', 'Sindhi Sunday-morning ritual: crispy deep-fried wheat crisps served with chana dal and three chutneys — this is Sindhi soul food at its finest.', 'The pakwan must be completely crisp — if it bends, fry longer. Soak the dal overnight for the smoothest texture.', 'Heritage', NULL, ARRAY['Chana dal — 1 cup, soaked overnight','Turmeric — ¼ tsp','Red chilli powder — ½ tsp','Cumin seeds — 1 tsp','Amchur (mango powder) — ½ tsp','For pakwan: whole wheat flour — 1½ cup','Cumin seeds — 1 tsp','Carom seeds (ajwain) — ½ tsp','Oil — 2 tbsp + for frying','Salt to taste','Green chutney and tamarind chutney to serve']::text[], ARRAY['Boil soaked chana dal until just tender but holding its shape.','Temper with cumin, turmeric, red chilli, and amchur.','Mix wheat flour with cumin, ajwain, salt, and oil.','Add water to make a stiff dough. Rest 15 min.','Roll thin and cut into rounds or squares.','Deep fry on medium heat until crisp and golden.','Serve dal in a bowl with pakwan on the side and chutneys.']::text[], ARRAY['breakfast','lunch']::text[], 'plate', 250, 390, 16, 58, 12, 9, 5.2, 75, 0, 480, true),
  (526, 'Gongura Pappu', 'Andhra', 'south_indian', 'veg', false, 'dal', '2', '10 min', '20 min', 'Toor dal cooked with sour gongura (sorrel) leaves — the defining flavour of Andhra cuisine. Bold, tangy, and deeply satisfying with rice and ghee.', 'Gongura provides natural tartness — no need for tamarind. Use more leaves for extra sourness.', 'Signature', NULL, ARRAY['Toor dal — ½ cup','Gongura (sorrel) leaves — 1 cup, stems removed','Green chilli — 3','Tomato — 1','Turmeric — ¼ tsp','Ghee — 1 tsp','Mustard seeds — ½ tsp','Dry red chilli — 2','Cumin seeds — ½ tsp','Garlic — 4 cloves, crushed','Asafoetida — a pinch','Curry leaves — 10','Salt to taste']::text[], ARRAY['Pressure cook toor dal with gongura leaves, tomato, green chilli, and turmeric.','Once cooked, mash and blend until smooth.','Heat ghee, fry garlic until golden, add mustard seeds, cumin, red chilli, and curry leaves.','Add asafoetida, pour tempering over the dal and mix.','Simmer 5 min and serve with hot rice and a drizzle of ghee.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 210, 14, 32, 5, 6, 4.2, 58, 0.05, 290, true),
  (527, 'Gutti Vankaya Curry', 'Andhra', 'south_indian', 'vegan', true, 'curry', '2', '15 min', '25 min', 'Baby brinjals stuffed with a fiery peanut-sesame masala and slow-cooked in their own steam — one of the most beloved Andhra lunch curries.', 'Slit the brinjals deep but do not cut through. Freshly roasted and ground peanuts make all the difference.', 'Regional Favourite', NULL, ARRAY['Baby brinjals — 8','Peanuts — 3 tbsp, dry roasted','Sesame seeds — 2 tbsp, roasted','Desiccated coconut — 2 tbsp','Red chilli powder — 1½ tsp','Coriander powder — 1 tsp','Turmeric — ¼ tsp','Tamarind paste — ½ tsp','Oil — 2 tbsp','Mustard seeds — ½ tsp','Curry leaves — 10','Salt to taste']::text[], ARRAY['Grind peanuts, sesame, coconut, red chilli, coriander, turmeric, tamarind, and salt to a coarse paste.','Slit each brinjal into 4 from the base, keeping the stem intact.','Stuff the masala paste into each brinjal.','Heat oil in a wide pan, add mustard seeds and curry leaves.','Add stuffed brinjals and arrange in a single layer.','Cover and cook on low, turning occasionally, for 20 min until soft.','Serve with Andhra rice and pappu.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 190, 7, 22, 11, 7, 3.5, 55, 0, 380, true),
  (529, 'Mulakkada Pappu', 'Andhra', 'south_indian', 'veg', true, 'dal', '2', '10 min', '25 min', 'Drumstick dal — toor dal simmered with drumstick pieces in a gently spiced Andhra base. A weekday staple across every Andhra home.', 'Cook drumstick separately if you prefer firmer pieces. The dal should be creamy and slightly thick.', 'Everyday', NULL, ARRAY['Toor dal — ½ cup','Drumstick — 2, cut into 3-inch pieces','Tomato — 2, chopped','Green chilli — 2','Turmeric — ¼ tsp','Red chilli powder — ½ tsp','Ghee — 1 tsp','Mustard seeds — ½ tsp','Cumin seeds — ½ tsp','Dry red chilli — 2','Curry leaves — 10','Asafoetida — a pinch','Salt to taste']::text[], ARRAY['Pressure cook dal with drumstick, tomato, green chilli, and turmeric.','Mash dal smooth while leaving drumstick intact.','Add red chilli powder, salt, and water if needed. Simmer 5 min.','Prepare tempering with ghee, mustard seeds, cumin, red chilli, curry leaves, asafoetida.','Pour tempering over dal and serve with Andhra rice and papad.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 200, 13, 30, 4, 5, 3.8, 68, 0.05, 260, true),
  (531, 'Jolada Rotti with Ennegai', 'Karnataka', 'south_indian', 'vegan', false, 'main', '2', '15 min', '20 min', 'Jowar (sorghum) flatbread paired with stuffed brinjal curry — a rustic North Karnataka lunch that is gluten-free, deeply satisfying, and rich in fibre.', 'Jowar rotis need practice — knead with very hot water and roll with wet hands for best results.', 'Regional', NULL, ARRAY['Jowar flour — 2 cups','Hot water — as needed','Salt to taste','For Ennegai: small brinjals — 6','Groundnuts — 4 tbsp, roasted and ground','Onion — 1, grated','Red chilli powder — 1 tsp','Coriander powder — 1 tsp','Jaggery — 1 tsp','Tamarind paste — ½ tsp','Oil — 2 tbsp','Mustard seeds, curry leaves for tempering']::text[], ARRAY['Mix jowar flour with salt, knead with very hot water into a pliable dough.','Make balls and pat into thick rounds using wet hands.','Cook on a dry griddle on medium heat, turning until brown spots appear.','For ennegai: mix peanuts, onion, chilli, coriander, jaggery, tamarind, salt.','Stuff brinjals, cook in oil until soft (15 min covered).','Serve rotti with ennegai and a side of yoghurt.']::text[], ARRAY['lunch','dinner']::text[], 'plate', 250, 340, 12, 54, 10, 7, 4.5, 62, 0, 380, true),
  (532, 'Saaru', 'Karnataka', 'south_indian', 'veg', true, 'dal', '2', '5 min', '20 min', 'Karnataka''s beloved thin rasam-like soup — made with tomatoes, tamarind, and the fragrant saaru pudi. Poured generously over rice for a light, restorative lunch.', 'Saaru should be watery, not thick — it is a soup to pour, not a curry. Drink any leftover straight from the bowl.', 'Traditional', NULL, ARRAY['Tomato — 3, chopped','Tamarind — small piece','Toor dal — 2 tbsp (for body)','Saaru pudi (rasam powder) — 1½ tsp','Turmeric — ¼ tsp','Jaggery — ½ tsp','Ghee — 1 tsp','Mustard seeds — ½ tsp','Cumin seeds — ½ tsp','Dry red chilli — 2','Curry leaves — 10','Asafoetida — a pinch','Coriander leaves to garnish','Salt to taste']::text[], ARRAY['Cook tomatoes and dal in 2 cups water until dal is soft. Blend or mash.','Soak tamarind, extract juice.','Add tamarind water, saaru pudi, turmeric, jaggery, and salt.','Simmer for 10 min until fragrant.','Prepare tempering with ghee, mustard seeds, cumin, red chilli, curry leaves, asafoetida.','Add tempering to the saaru, garnish with coriander.','Serve over rice or drink as a soup.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 90, 3, 14, 3, 3, 1.8, 32, 0, 280, true),
  (533, 'Sheer Chai (Noon Chai)', 'Kashmiri', 'north_indian', 'veg', true, 'drink', '2', '5 min', '15 min', 'Kashmiri pink tea — brewed with special gunpowder tea, baking soda, milk, and salt, topped with crushed almonds and sesame. A warming winter morning ritual in the Valley.', 'The pink colour develops from the reaction between baking soda and the special tea leaves. Brew patiently for the deepest colour.', 'Heritage', NULL, ARRAY['Kashmiri Noon Chai leaves (or green tea) — 1 tsp','Water — 1½ cups','Baking soda — a small pinch','Milk — 1 cup','Salt — ¼ tsp (traditional) or omit','Cardamom — 2 pods, crushed','Almonds — 2 tbsp, slivered','Sesame seeds — 1 tsp, toasted']::text[], ARRAY['Boil tea leaves in water for 5 min.','Add baking soda and stir — the water turns red.','Add milk and cardamom, simmer 8 min until a deep pink develops.','Add salt (Noon Chai is traditionally salty — omit for a sweeter version).','Strain into cups.','Top with slivered almonds and toasted sesame.','Serve with Kashmiri bread (girda or lavasa).']::text[], ARRAY['breakfast','snack']::text[], 'glass', 200, 120, 4, 12, 5, 0, 0.8, 145, 0.5, 180, true),
  (534, 'Kashmiri Kehwa', 'Kashmiri', 'north_indian', 'vegan', true, 'drink', '2', '2 min', '8 min', 'Saffron-steeped green tea spiced with cardamom, cinnamon, and cloves — the aromatic essence of Kashmiri hospitality, drunk morning and evening.', 'Brew on the lowest flame and never boil. The longer it steeps, the more fragrant it becomes.', 'Heritage', NULL, ARRAY['Kashmiri green tea — 1½ tsp','Water — 2 cups','Saffron — a few strands','Cardamom — 3 pods, bruised','Cinnamon stick — ½ inch','Cloves — 2','Almonds — 1 tbsp, slivered','Walnuts — 1 tbsp, chopped','Honey — 1 tsp (optional)']::text[], ARRAY['Bring water to a simmer with cardamom, cinnamon, and cloves.','Add green tea leaves and steep on low heat 5 min.','Add saffron and honey if using.','Strain into cups.','Top with slivered almonds and walnuts.','Serve immediately.']::text[], ARRAY['breakfast','snack']::text[], 'cup', 200, 45, 1, 6, 2, 0, 0.5, 22, 0, 15, true),
  (535, 'Kashmiri Haakh', 'Kashmiri', 'north_indian', 'vegan', true, 'side', '2', '10 min', '15 min', 'Collard greens or Kashmiri saag cooked simply with water, asafoetida, and dried red chilli — Kashmiri cooking at its most elemental. Eaten with rice at lunch and dinner.', 'Do not overcook — the greens should retain some bite. The flavour relies entirely on simplicity.', 'Traditional', NULL, ARRAY['Haakh (collard greens or kale) — 3 cups, roughly chopped','Mustard oil — 1½ tbsp','Dry red chilli (whole) — 2','Asafoetida — ¼ tsp','Water — ¼ cup','Salt to taste']::text[], ARRAY['Heat mustard oil to smoking point to mellow its sharpness.','Add dry red chilli and asafoetida — let them sizzle 10 seconds.','Add haakh greens and toss well.','Add water, cover, and cook on medium for 12 min.','Season with salt.','Serve with plain rice — this is traditionally a very simple preparation.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 110, 5, 12, 6, 5, 3.8, 145, 0, 220, true),
  (536, 'Aloo Pitika', 'Assamese', 'northeast_indian', 'vegan', false, 'side', '2', '10 min', '15 min', 'Mashed potato with raw mustard oil, shallots, and green chillies — Assamese food at its most comforting. Simple but utterly addictive alongside dal and rice.', 'Use good-quality cold-pressed mustard oil — the raw, pungent version. Do not heat it. That rawness is the whole point.', 'Heritage', NULL, ARRAY['Potato — 3, boiled and peeled','Raw mustard oil — 1½ tsp','Shallots — 4, finely chopped','Green chilli — 2, finely chopped','Coriander leaves — 2 tbsp','Salt to taste']::text[], ARRAY['Mash potatoes while still warm.','Mix in raw mustard oil immediately — it binds into the warmth.','Add shallots, green chilli, coriander, and salt.','Mix well by hand — Assamese cooks traditionally mix with fingers.','Serve at room temperature alongside rice and dal.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 120, 180, 4, 36, 3, 4, 2.2, 22, 0, 180, true),
  (537, 'Khar', 'Assamese', 'northeast_indian', 'vegan', true, 'dal', '2', '15 min', '25 min', 'Assam''s unique alkaline preparation — raw papaya and moong dal simmered with khar (alkali from banana peel ash). A must-know dish to understand Assamese cuisine.', 'Khar is the distinctive ingredient — filter banana peel ash water or use food-grade baking soda as a substitute (½ tsp). The taste is slightly soapy and entirely unique.', 'Traditional', NULL, ARRAY['Raw papaya — 1 cup, peeled and grated','Yellow moong dal — ¼ cup, soaked','Khar water — 3 tbsp (or ½ tsp baking soda in water)','Mustard oil — 1½ tbsp','Green chilli — 2, slit','Cumin seeds — ½ tsp','Salt to taste','Coriander leaves to garnish']::text[], ARRAY['Heat mustard oil, add cumin seeds and green chilli.','Add moong dal and sauté 2 min.','Add grated papaya and cook 5 min, stirring.','Pour khar water and ½ cup plain water.','Simmer covered for 15 min until papaya is soft.','Season lightly with salt.','Garnish with coriander. Serve with rice.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 170, 8, 26, 6, 4, 2.8, 38, 0, 220, true),
  (538, 'Steamed Rice', 'Pan-Indian', 'pan_indian', 'vegan', true, 'staple', '2', '2 min', '15 min', 'Plain boiled or steamed rice — the neutral, nourishing base that ties together every South Indian meal and most Indian meals across all regions.', 'The absorption method gives consistent results: 1 cup rice to 1¾ cups water. Let it rest 5 min off heat before fluffing.', 'Staple', NULL, ARRAY['Rice (short-grain or long-grain) — 1 cup, washed well','Water — 1¾ cups','Salt — a small pinch (optional)']::text[], ARRAY['Wash rice in cold water 2–3 times until water runs clear.','Combine rice, water, and salt in a heavy pot. Bring to a boil.','Reduce heat to the lowest setting, cover tightly.','Cook for 12 min — do not lift the lid.','Remove from heat and rest, covered, for 5 min.','Fluff gently with a fork and serve immediately alongside sambar, rasam, dal, or any curry.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 210, 4, 46, 0, 0, 0.4, 6, 0, 5, true),
  (539, 'Phulka', 'Pan-Indian', 'pan_indian', 'vegan', true, 'staple', '2', '15 min (+ 20 min rest)', '15 min', 'Thin, feather-light whole-wheat rotis puffed directly over an open flame — the lightest form of Indian flatbread, eaten from Gujarat to Bengal at every meal.', 'Roll very thin (2 mm) and cook on the tawa first, then place directly on the flame to puff. The puffing means steam is trapped evenly — a sign of good dough and thin rolling.', 'Staple', NULL, ARRAY['Whole wheat flour (atta) — 1 cup','Water — approximately ½ cup, slightly warm','Salt — a pinch','A few drops of oil for the dough']::text[], ARRAY['Mix flour and salt, add water gradually and knead into a soft, smooth dough.','Add a few drops of oil and knead 2 min more. Rest, covered, 20 min.','Divide into small equal balls (smaller than chapati).','Roll each ball into a very thin round (2 mm).','Cook on a hot dry tawa for 30 seconds until small bubbles appear.','Flip and cook 20 seconds.','Place directly over a medium flame — it will puff into a ball in seconds.','Remove with tongs, wrap in a clean cloth to keep soft.','Serve immediately with any dal, sabzi, or curd.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'piece', 40, 80, 3, 16, 0.5, 2, 0.8, 8, 0, 40, true),
  (540, 'Plain Paratha', 'Pan-Indian', 'pan_indian', 'veg', true, 'staple', '2', '15 min (+ 20 min rest)', '15 min', 'Layered whole-wheat flatbread cooked with a touch of ghee — flakier and more substantial than a phulka. The everyday bread of North India, equally at home at breakfast, lunch, or dinner.', 'The layering technique (roll, fold, roll again) is what creates the flakiness. Do not press too hard — the layers need air between them.', 'Staple', NULL, ARRAY['Whole wheat flour (atta) — 1 cup','Water — approximately ½ cup, warm','Salt — a pinch','Ghee or oil — 1 tsp for the dough + 1 tsp per paratha for cooking']::text[], ARRAY['Mix flour and salt, knead into a soft dough with water and a little ghee.','Rest covered for 20 min.','Make medium balls. Roll each into a circle (5 inches).','Spread a little ghee on the surface, fold into a half-moon, spread ghee again, fold into a triangle.','Roll the triangle out again into a thicker flatbread.','Cook on a medium-hot tawa with ghee, pressing gently, until golden on both sides.','Serve with pickle, curd, or any curry.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'piece', 60, 160, 4, 28, 5, 3, 1.2, 12, 0, 80, true),
  (541, 'Plain Curd', 'Pan-Indian', 'pan_indian', 'veg', true, 'dairy', '2', '0 min (set overnight)', '0 min', 'Fresh set curd — cooling, probiotic, and essential. Eaten alongside rice and curry in South India, with roti in North India, and as a simple meal-ender across every region.', 'Full-fat milk gives the thickest, most flavourful curd. The setting temperature (40–45°C) is critical — too hot kills the culture, too cool prevents setting.', 'Staple', NULL, ARRAY['Full-fat milk — 2 cups','Live curd (starter) — 1 tsp']::text[], ARRAY['Heat milk until just warm to the touch (40–45°C) — not boiling.','Add the curd starter and stir gently.','Cover and leave undisturbed in a warm spot for 6–8 hours.','Once set, refrigerate for 2 hours before serving.','Serve as a side with rice, roti, or paratha.','Use as a base for raita, kadhi, or lassi.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'bowl', 150, 100, 7, 12, 5, 0, 0.2, 245, 0.5, 80, true),
  (542, 'Brown Rice', 'Pan-Indian', 'pan_indian', 'vegan', true, 'staple', '2', '2 min', '25 min', 'Whole-grain brown rice — slightly nutty, more fibre-rich, and with a lower glycaemic index than white rice. Excellent with sambar, rasam, dal, or any South Indian curry.', 'Brown rice needs more water (1:2.5 ratio) and longer cooking. Soaking for 30 min before cooking speeds it up and improves texture.', 'Staple', NULL, ARRAY['Brown rice — 1 cup, soaked 30 min and washed','Water — 2½ cups','Salt — a pinch (optional)']::text[], ARRAY['Drain soaked brown rice and add to a pot with water.','Bring to a boil, then reduce to the lowest heat.','Cover tightly and cook for 20–22 min.','Rest, covered, for 5 min off heat.','Fluff gently and serve with any curry, sambar, or dal.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 220, 5, 46, 1, 4, 1.2, 20, 0, 5, true),
  (543, 'Jowar Roti', 'Pan-Indian', 'pan_indian', 'vegan', true, 'staple', '2', '10 min', '15 min', 'Sorghum flatbread — gluten-free, fibre-rich, and a daily staple in rural Karnataka, Maharashtra, and Rajasthan. Eaten with chutney at breakfast and with dal-sabzi at lunch or dinner.', 'Jowar dough needs very hot water and quick work — it does not have gluten so it tears easily. Wetting your palms helps in patting it out.', 'Staple', NULL, ARRAY['Jowar flour (sorghum) — 1 cup','Hot water — as needed','Salt — a pinch']::text[], ARRAY['Mix jowar flour and salt. Add boiling water gradually, mixing with a spoon.','Once cool enough to handle, knead into a smooth pliable dough.','Divide into balls. Wet your palms and pat each ball into a flat round directly on the tawa.','Or place between two sheets of wet plastic and roll gently.','Cook on a dry medium-hot tawa until small brown spots appear (2–3 min).','Flip and cook the other side.','Hold briefly over a flame for slight char and extra flavour.','Serve immediately with ghee, dal, or sabzi.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'piece', 60, 130, 4, 28, 1, 4, 2.2, 18, 0, 30, true),
  (544, 'Bajra Roti', 'Pan-Indian', 'pan_indian', 'veg', true, 'staple', '2', '10 min', '15 min', 'Pearl millet flatbread — warming, gluten-free, and a nutritional powerhouse. The winter staple of Rajasthan and Gujarat, eaten with ghee and garlic chutney.', 'Like jowar, bajra needs hot water. The rotis are best eaten piping hot — they harden quickly as they cool.', 'Staple', NULL, ARRAY['Bajra flour (pearl millet) — 1 cup','Hot water — as needed','Salt — a pinch','Ghee — for serving']::text[], ARRAY['Mix bajra flour and salt, add hot water gradually to make a pliable dough.','Knead well. Divide into equal balls.','Wet palms and pat each ball into a round directly on the tawa, or roll with wet plastic sheets.','Cook on a hot dry tawa, pressing gently with a cloth, until cooked through.','Hold over a direct flame briefly for slight char.','Serve hot with a generous knob of ghee.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'piece', 60, 140, 4, 28, 2, 4, 3.5, 22, 0, 30, true),
  (545, 'Banana', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '1', '0 min', '0 min', 'The most widely eaten fruit across India — instant energy, rich in potassium, gentle on digestion. Eaten at breakfast, as a snack, or as an offering.', 'Choose firm ripe bananas with small brown spots — they are sweetest at this stage.', 'Fresh Fruit', NULL, ARRAY['Banana — 1 medium (approx 120 g)']::text[], ARRAY['Peel and eat as is.','Slice over porridge, oats, or poha.','Blend into smoothies or lassi.','Pair with a handful of nuts for a balanced snack.']::text[], ARRAY['snack','breakfast']::text[], 'piece', 120, 90, 1, 23, 0, 3, 0.3, 6, 0, 1, true),
  (546, 'Mango', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '1', '5 min', '0 min', 'The king of Indian fruits — sweet, fragrant, and bursting with vitamins A and C. Available through summer; a complete sensory experience eaten as is or with rice and ghee.', 'Alphonso, Kesar, Dasheri, Langra — variety determines the flavour. Chill before cutting for the best experience.', 'Seasonal King', NULL, ARRAY['Mango — 1 medium, ripe (approx 200 g)']::text[], ARRAY['Wash, peel, and slice the mango.','Eat fresh, or cube and serve in a bowl.','Traditional South Indian way: suck mango halves directly.','Can be paired with curd or rice for a complete summer meal.']::text[], ARRAY['snack','breakfast']::text[], 'piece', 200, 100, 1, 25, 0, 3, 0.4, 15, 0, 2, true),
  (547, 'Papaya', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '2', '5 min', '0 min', 'One of the most digestive-friendly fruits — rich in papain enzymes, beta-carotene, and vitamin C. Eaten fresh, with lime, or as a digestive starter to lunch.', 'Press the skin gently — a ripe papaya yields slightly. Squeeze lime juice and a pinch of black salt for the classic Indian way to eat it.', 'Digestive', NULL, ARRAY['Papaya — ½ medium, ripe (approx 200 g)','Lime — a squeeze (optional)','Black salt — a pinch (optional)']::text[], ARRAY['Halve the papaya and scoop out seeds.','Peel and cut into cubes or slices.','Squeeze lime juice and sprinkle black salt.','Serve fresh as a first course or snack.']::text[], ARRAY['snack','breakfast']::text[], 'bowl', 150, 60, 1, 15, 0, 2, 0.5, 22, 0, 10, true),
  (548, 'Guava', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '1', '2 min', '0 min', 'India''s everyday superfruit — high in vitamin C, fibre, and folate. Eaten with a sprinkle of chaat masala and salt across street corners all over the country.', 'Pick guavas with a slight yellow tinge — fully green ones are tart and hard, over-ripe ones are mushy.', 'Everyday', NULL, ARRAY['Guava — 1 medium','Chaat masala — ¼ tsp (optional)','Salt — a pinch (optional)']::text[], ARRAY['Wash the guava well.','Quarter or slice it.','Sprinkle with chaat masala and salt in the classic Indian way.','Eat with or without seeds.']::text[], ARRAY['snack']::text[], 'piece', 120, 70, 1, 15, 0, 5, 0.6, 18, 0, 2, true),
  (549, 'Pomegranate', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '1', '5 min', '0 min', 'Ruby-red arils bursting with iron, antioxidants, and vitamin K — particularly valuable for vegetarians. Eaten fresh, scattered over raita, or juiced.', 'Roll the pomegranate firmly on a counter before cutting — it loosens the arils. Use a bowl of water to de-seed to avoid staining.', 'Iron Rich', NULL, ARRAY['Pomegranate — 1 medium']::text[], ARRAY['Score the pomegranate into quarters without cutting fully through.','Break apart over a bowl of water.','Separate arils by hand — the seeds sink, the pith floats.','Drain and serve fresh.','Optionally scatter over curd or use as a garnish.']::text[], ARRAY['snack','breakfast']::text[], 'bowl', 100, 80, 2, 19, 1, 4, 0.8, 12, 0, 5, true),
  (550, 'Amla (Indian Gooseberry)', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '1', '2 min', '0 min', 'India''s most potent fruit — amla contains 20× more vitamin C than an orange, is revered in Ayurveda, and is eaten raw, pickled, candied, or juiced.', 'Raw amla is intensely sour and astringent — the bitterness fades quickly and leaves a sweet aftertaste. A pinch of salt brings out its flavour.', 'Ayurvedic Superfood', NULL, ARRAY['Amla — 3–4 fresh (or 1 tbsp amla powder for off-season)','Salt — a pinch','Honey — ½ tsp (optional)']::text[], ARRAY['Wash fresh amla well.','Eat as is with a pinch of salt, or cut into wedges.','For amla juice: blend with water, strain, and add honey.','One amla daily in the morning is the Ayurvedic recommendation.']::text[], ARRAY['snack','breakfast']::text[], 'serving', 60, 45, 1, 10, 0, 3, 1.2, 25, 0, 2, true),
  (551, 'Watermelon', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '2', '5 min', '0 min', 'Summer''s most hydrating fruit — 92% water, rich in lycopene and vitamin C. Eaten in thick slices on hot afternoons across India.', 'Tap the watermelon — a deep hollow sound means it is ripe. Refrigerate whole for best flavour.', 'Summer', NULL, ARRAY['Watermelon — 2 thick slices (approx 300 g)','Black salt — a pinch (optional)','Lime — a squeeze (optional)']::text[], ARRAY['Cut watermelon into thick wedges or cubes.','Sprinkle black salt and lime if desired.','Serve ice cold.','Alternatively blend with mint for a fresh summer cooler.']::text[], ARRAY['snack']::text[], 'bowl', 150, 50, 1, 12, 0, 1, 0.4, 8, 0, 2, true),
  (552, 'Seasonal Fruit Bowl', 'Pan-Indian', 'pan_indian', 'vegan', true, 'fruit', '2', '10 min', '0 min', 'A mix of seasonal Indian fruits — a nutritionally balanced start to the morning or a light afternoon snack that celebrates whatever the season brings.', 'Use whatever is local and in season — a fruit bowl is most nutritious when the fruits have not travelled far.', 'Balanced', NULL, ARRAY['Banana — 1, sliced','Papaya — ½ cup, cubed','Pomegranate arils — 2 tbsp','Apple or pear — 1, diced','Lime juice — 1 tsp','Chaat masala — ¼ tsp (optional)','Fresh mint leaves — a few']::text[], ARRAY['Prepare all fruits and combine in a bowl.','Squeeze lime juice over the top.','Sprinkle chaat masala if using.','Garnish with mint leaves.','Serve immediately.']::text[], ARRAY['snack','breakfast']::text[], 'bowl', 200, 120, 2, 28, 1, 5, 1, 32, 0, 5, true),
  (553, 'Kheer', 'North Indian', 'north_indian', 'veg', true, 'dessert', '4', '5 min', '40 min', 'Slow-cooked rice pudding simmered in full-fat milk with saffron, cardamom, and nuts — the quintessential Indian festive dessert.', 'Cook on low heat and stir frequently — patience is the key to thick, creamy kheer. It thickens further as it cools.', 'Festival Classic', NULL, ARRAY['Full-fat milk — 1 litre','Rice — 3 tbsp, washed','Sugar — 4 tbsp','Saffron — a few strands, soaked in 1 tbsp warm milk','Cardamom — 4 pods, crushed','Cashews — 1 tbsp, chopped','Almonds — 1 tbsp, slivered','Pistachios — 1 tbsp','Rose water — ½ tsp (optional)']::text[], ARRAY['Bring milk to a boil in a heavy-bottomed pot.','Add washed rice, reduce heat to low.','Cook stirring frequently for 30–35 min until rice is very soft and milk thickens.','Add sugar and saffron milk, stir well.','Add cardamom, nuts, and rose water.','Serve warm or refrigerate and serve chilled.']::text[], ARRAY['snack']::text[], 'bowl', 150, 230, 8, 32, 8, 1, 0.5, 260, 0.7, 80, true),
  (554, 'Gajar Halwa', 'North Indian', 'north_indian', 'veg', false, 'dessert', '4', '15 min', '40 min', 'Slow-cooked grated carrot halwa — a winter festival favourite that fills the home with the aroma of ghee, cardamom, and khoya.', 'Use Delhi red carrots for the authentic winter version — they are sweeter and more flavourful than orange carrots.', 'Winter Festival', NULL, ARRAY['Carrots — 500 g, grated','Full-fat milk — 1 cup','Sugar — 5 tbsp','Ghee — 2 tbsp','Khoya (mawa) — 4 tbsp (optional)','Cardamom — 4 pods, crushed','Cashews — 2 tbsp','Almonds — 2 tbsp, slivered','Raisins — 1 tbsp']::text[], ARRAY['Heat ghee in a heavy pan, fry cashews and almonds until golden.','Add grated carrot and sauté on medium heat for 10 min.','Pour in milk and cook on medium, stirring often, until milk is absorbed (20 min).','Add sugar and khoya, mix well.','Cook until halwa leaves the sides of the pan.','Add cardamom and raisins.','Serve warm garnished with nuts.']::text[], ARRAY['snack','breakfast','lunch','dinner']::text[], 'bowl', 150, 280, 7, 40, 11, 4, 1.8, 140, 0.6, 95, true),
  (556, 'Payasam', 'South Indian', 'south_indian', 'veg', true, 'dessert', '4', '5 min', '30 min', 'South India''s kheer — semiya (vermicelli) or moong dal simmered in coconut milk and jaggery with cardamom. Every region has its own version; every sadya ends with it.', 'Use thick coconut milk for the richest payasam. Add it only off the heat — boiling coconut milk can split.', 'Sadya Sweet', NULL, ARRAY['Semiya (roasted vermicelli) — ½ cup','Coconut milk — 1½ cups (thin + thick)','Jaggery — 5 tbsp, grated','Ghee — 1 tsp','Cardamom — ½ tsp, powdered','Cashews — 2 tbsp','Raisins — 1 tbsp','Saffron — a few strands (optional)']::text[], ARRAY['Heat ghee, fry cashews until golden, add raisins.','Add vermicelli and toast until lightly browned.','Pour in thin coconut milk and simmer until vermicelli is soft (10 min).','Dissolve jaggery in 3 tbsp hot water, strain and add.','Simmer 5 min, then remove from heat.','Stir in thick coconut milk, cardamom, and saffron.','Serve warm or at room temperature.']::text[], ARRAY['snack']::text[], 'bowl', 150, 200, 6, 28, 7, 2, 1.2, 32, 0, 48, true),
  (557, 'Moong Dal Halwa', 'North Indian', 'north_indian', 'veg', true, 'dessert', '4', '6 hr (soak) + 10 min', '40 min', 'A labour of love — soaked yellow moong dal slow-roasted in ghee until golden, then cooked with sugar and milk. Rich, dense, and utterly indulgent.', 'The roasting phase takes patience — at least 30 min on medium heat until the dal turns deep golden. Do not rush it or the halwa will be raw-tasting.', 'Festive Indulgence', NULL, ARRAY['Yellow moong dal — 1 cup, soaked 6 hr and blended coarse','Ghee — 5 tbsp','Sugar — ½ cup','Milk — 1 cup, warm','Cardamom — ½ tsp','Saffron — a few strands in 2 tbsp warm milk','Cashews and almonds — 3 tbsp total','Raisins — 1 tbsp']::text[], ARRAY['Heat 4 tbsp ghee in a heavy pan. Add coarsely blended dal.','Roast on medium-low heat, stirring constantly, for 30–35 min until deep golden.','Meanwhile, heat milk and dissolve sugar into it.','Add the sweet milk to the roasted dal gradually, stirring.','Cook until all liquid is absorbed and halwa comes together.','Add remaining ghee, cardamom, saffron milk, and nuts.','Serve warm.']::text[], ARRAY['snack']::text[], 'bowl', 100, 310, 10, 42, 14, 3, 3.5, 65, 0.4, 90, true),
  (558, 'Paal Kozhukattai', 'Tamil', 'south_indian', 'vegan', true, 'dessert', '3', '10 min', '20 min', 'Rice flour dumplings simmered in sweet coconut milk with jaggery and cardamom — a comforting Tamil sweet eaten at festivals and on ordinary evenings alike.', 'Make the rice flour balls small and even — they cook evenly and look more appealing. Do not boil after adding thick coconut milk.', 'Traditional', NULL, ARRAY['Rice flour — 1 cup','Water — 1 cup + for kneading','Salt — a pinch','Thick coconut milk — 1 cup','Jaggery — 4 tbsp','Cardamom — ½ tsp','Coconut — 2 tbsp, grated (garnish)']::text[], ARRAY['Boil 1 cup water with a pinch of salt, add rice flour gradually, mixing.','Knead into a smooth dough. Shape into small marble-sized balls.','Cook rice balls in 2 cups boiling water until they float (5 min).','Dissolve jaggery in 3 tbsp water, strain.','Add jaggery water, coconut milk, and cardamom to the cooked balls.','Heat gently — do not boil.','Garnish with grated coconut. Serve warm.']::text[], ARRAY['snack']::text[], 'bowl', 150, 190, 4, 32, 6, 2, 0.8, 22, 0, 45, true),
  (559, 'Filter Kaapi', 'South Indian', 'south_indian', 'veg', true, 'drink', '2', '5 min', '5 min', 'South Indian filter coffee — dark, fragrant decoction cut with hot milk and sugar, served frothed between two tumblers. The morning ritual of Tamil Nadu, Karnataka, and Kerala.', 'The froth (the trademark foam) comes from lifting the decoction high and pouring between tumbler and dabarah. Chicory blend is traditional and gives the signature bitter-sweet note.', 'Icon', NULL, ARRAY['Filter coffee decoction — 4 tbsp (made with coffee-chicory blend in a filter)','Full-fat milk — 1 cup, hot','Sugar — 2 tsp (adjust to taste)']::text[], ARRAY['Brew decoction in a traditional South Indian filter (upper vessel + lower vessel).','Heat milk until frothy.','Add 2 tbsp decoction to a tumbler.','Add hot milk and sugar.','Pour between the tumbler and the wide dabarah repeatedly to froth.','Serve in the tumbler with the dabarah on the side.']::text[], ARRAY['snack','breakfast']::text[], 'cup', 150, 80, 4, 10, 4, 0, 0.2, 135, 0.4, 50, true),
  (560, 'Neer Mor (Spiced Buttermilk)', 'Tamil', 'south_indian', 'veg', true, 'drink', '2', '5 min', '0 min', 'Thin spiced buttermilk with ginger, green chilli, curry leaves, and asafoetida — the essential Tamil summer digestive, drunk at lunch and through the afternoon.', 'Neer mor should be watery, not thick. The tempering in oil is optional but gives it a restaurant-style flavour.', 'Digestive', NULL, ARRAY['Curd — ½ cup, beaten','Water — 2 cups (cold)','Ginger — ½ inch, finely grated','Green chilli — 1, slit','Curry leaves — 6','Asafoetida — a pinch','Coriander leaves — 1 tbsp','Salt to taste']::text[], ARRAY['Beat curd smooth, whisk in cold water until completely diluted.','Add ginger, salt, and asafoetida.','Bruise green chilli and curry leaves in your hand and drop in.','Mix in coriander.','Serve cold as a digestive alongside lunch or on its own.']::text[], ARRAY['snack','lunch']::text[], 'glass', 200, 35, 2, 4, 1, 2, 0.2, 75, 0.2, 180, true),
  (562, 'Chaas (Spiced Buttermilk)', 'Pan-Indian', 'pan_indian', 'veg', true, 'drink', '2', '5 min', '0 min', 'North Indian spiced lassi — thin, tangy buttermilk with roasted cumin, black salt, and ginger. The digestive drink of Rajasthan and Gujarat, drunk at every lunch.', 'Use full-fat curd for a richer chaas. The roasted cumin powder is the backbone — freshly roast and grind for best flavour.', 'Digestive', NULL, ARRAY['Curd — ½ cup, beaten','Water — 2 cups (cold)','Roasted cumin powder — ½ tsp','Black salt — ¼ tsp','Regular salt — a pinch','Ginger — ½ tsp, grated','Coriander leaves — 1 tbsp, chopped','Green chilli — ½ (optional)']::text[], ARRAY['Whisk curd smooth with cold water until thin and frothy.','Add roasted cumin powder, black salt, regular salt, and ginger.','Add coriander and green chilli if using.','Stir well, taste for seasoning.','Serve cold over ice.']::text[], ARRAY['snack','lunch']::text[], 'glass', 200, 40, 2, 4, 1, 2, 0.2, 75, 0.2, 220, true),
  (563, 'Plain Rice', 'Indian', 'pan_indian', 'vegan', true, 'staple', '3', NULL, NULL, 'Community recipe.', NULL, 'Traditional', NULL, ARRAY['1 cup of raw rice - Sona Masoori, Surti Kolam, Govind Bhog, etc']::text[], ARRAY['1. Wash and soak the rice for about 5 min in warm water.','2. Steam the rice 2 cups of water in pressure cooker - 3 or 4 whistles','3. Serve when hoy','Goes well as a staple food with most of the Indian dishes.']::text[], ARRAY['lunch','dinner','breakfast']::text[], 'bowl', 150, 220, 4, 40, 0.5, 0, 0.6, 15, 0, 3, true)
