-- Recipes that are the same dish as one already in the list: link them, no duplicate
UPDATE public.food_items f SET recipe_id = v.recipe_id
FROM (VALUES
  ('Ven Pongal', 513),
  ('Guava', 548),
  ('Pomegranate', 549),
  ('Amla (Indian Gooseberry)', 550),
  ('Watermelon', 551),
  ('Chana Dal (cooked)', 497),
  ('Upma', 514),
  ('Curd / Yogurt', 541),
  ('Brown Rice (cooked)', 542),
  ('Banana (ripe)', 545),
  ('Mango (ripe)', 546),
  ('Papaya (ripe)', 547),
  ('Payasam / Kheer', 553),
  ('White Rice (cooked)', 563)
) AS v(name, recipe_id)
WHERE f.name = v.name AND f.kutumbh_id IS NULL AND f.recipe_id IS NULL;


